-- Verkündungen: ogvbl-2026-19, ogvbl-2026-72, einzelverkuendung-2024-03-01, stanzo-2026-44
CREATE TABLE law_norm_derived (
  norm_id TEXT PRIMARY KEY REFERENCES law_norms(id) ON DELETE CASCADE,
  relations_json TEXT NOT NULL,
  recommendations_json TEXT NOT NULL,
  origin_json TEXT NOT NULL,
  text_references_json TEXT NOT NULL,
  portal_links_json TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE law_norm_history (
  norm_id TEXT NOT NULL REFERENCES law_norms(id) ON DELETE CASCADE,
  entry_index INTEGER NOT NULL,
  change_date TEXT NOT NULL,
  change_type TEXT NOT NULL,
  title TEXT NOT NULL,
  citation TEXT NOT NULL,
  note TEXT,
  affecting_version_id TEXT,
  related_norm TEXT,
  PRIMARY KEY (norm_id, entry_index)
);
CREATE TABLE law_norm_keywords (
  norm_id TEXT NOT NULL REFERENCES law_norms(id) ON DELETE CASCADE,
  keyword TEXT NOT NULL,
  index_letter TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'derived',
  PRIMARY KEY (norm_id, keyword)
);
CREATE TABLE law_norm_subjects (
  norm_id TEXT NOT NULL REFERENCES law_norms(id) ON DELETE CASCADE,
  subject TEXT NOT NULL,
  subject_slug TEXT NOT NULL,
  PRIMARY KEY (norm_id, subject_slug)
);
CREATE TABLE law_norms (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  short_title TEXT NOT NULL,
  abbr TEXT,
  type TEXT NOT NULL,
  status TEXT NOT NULL,
  revosax_law_id TEXT,
  current_version_id TEXT,
  document_date TEXT,
  publication_date TEXT,
  effective_date TEXT,
  expiry_date TEXT,
  initial_citation TEXT NOT NULL,
  summary TEXT NOT NULL,
  responsible_ministry TEXT,
  enacting_body TEXT,
  source_kind TEXT NOT NULL DEFAULT 'repository',
  updated_at TEXT NOT NULL, meta_json TEXT, history_json TEXT, sort_title TEXT, current_valid_from TEXT, subjects_json TEXT NOT NULL DEFAULT '[]', primary_subject TEXT, keywords_json TEXT NOT NULL DEFAULT '[]', aliases_json TEXT NOT NULL DEFAULT '[]', origin_kind TEXT, origin_baseline_version_id TEXT, origin_last_own_change_date TEXT, version_count INTEGER NOT NULL DEFAULT 0, last_change_date TEXT, index_letter TEXT NOT NULL DEFAULT '#', last_activity_date TEXT, is_amendment INTEGER NOT NULL DEFAULT 0, in_inventory INTEGER NOT NULL DEFAULT 1, sort_word TEXT, funding_area TEXT,
  CHECK (source_kind IN ('repository', 'revosax-baseline'))
);
CREATE TABLE law_publications (
  slug TEXT PRIMARY KEY,
  publication_date TEXT NOT NULL,
  publication TEXT NOT NULL,
  year INTEGER NOT NULL,
  issue TEXT NOT NULL,
  publication_json TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE law_runtime_meta (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
CREATE VIRTUAL TABLE law_search USING fts5(
  norm_id UNINDEXED,
  version_id UNINDEXED,
  provision_path UNINDEXED,
  anchor UNINDEXED,
  block_type UNINDEXED,
  references_json UNINDEXED,
  slug UNINDEXED,
  title,
  short_title,
  abbr,
  label,
  heading,
  body,
  content='law_search_units',
  content_rowid='id',
  tokenize = 'unicode61 remove_diacritics 2'
);
CREATE TABLE law_search_documents (
  norm_id TEXT NOT NULL,
  version_id TEXT NOT NULL,
  document_json TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (norm_id, version_id),
  FOREIGN KEY (norm_id) REFERENCES law_norms(id) ON DELETE CASCADE
);
CREATE TABLE law_search_units (
  id INTEGER PRIMARY KEY,
  norm_id TEXT NOT NULL,
  version_id TEXT NOT NULL,
  provision_path TEXT NOT NULL,
  anchor TEXT NOT NULL,
  block_type TEXT NOT NULL,
  references_json TEXT,
  slug TEXT NOT NULL,
  title TEXT NOT NULL,
  short_title TEXT NOT NULL,
  abbr TEXT NOT NULL,
  label TEXT NOT NULL,
  heading TEXT NOT NULL,
  body TEXT NOT NULL
);
CREATE TABLE law_source_objects (
  norm_id TEXT NOT NULL,
  version_id TEXT NOT NULL,
  source_index INTEGER NOT NULL,
  kind TEXT NOT NULL,
  label TEXT NOT NULL,
  url TEXT,
  local_source TEXT,
  object_key TEXT,
  media_type TEXT,
  sha256 TEXT,
  retrieved_at TEXT,
  source_valid_from TEXT,
  source_valid_to TEXT,
  PRIMARY KEY (norm_id, version_id, source_index),
  FOREIGN KEY (norm_id, version_id)
    REFERENCES law_versions(norm_id, version_id)
    ON DELETE CASCADE
);
CREATE TABLE law_version_blocks (
  norm_id TEXT NOT NULL,
  version_id TEXT NOT NULL,
  block_index INTEGER NOT NULL,
  part_index INTEGER NOT NULL DEFAULT 0,
  part_count INTEGER NOT NULL DEFAULT 1,
  block_json TEXT NOT NULL,
  PRIMARY KEY (norm_id, version_id, block_index, part_index),
  FOREIGN KEY (norm_id, version_id)
    REFERENCES law_versions(norm_id, version_id)
    ON DELETE CASCADE
);
CREATE TABLE law_versions (
  norm_id TEXT NOT NULL,
  version_id TEXT NOT NULL,
  valid_from TEXT NOT NULL,
  valid_to TEXT,
  is_current INTEGER NOT NULL CHECK (is_current IN (0, 1)),
  title TEXT,
  short_title TEXT,
  abbr TEXT,
  summary TEXT,
  citation TEXT NOT NULL,
  change_note TEXT NOT NULL,
  source_sha256 TEXT,
  source_url TEXT,
  source_retrieved_at TEXT,
  source_object_key TEXT,
  updated_at TEXT NOT NULL, version_json TEXT, full_citation TEXT, publication_ref_json TEXT, temporal_kind TEXT, publication_source TEXT, publication_year TEXT,
  PRIMARY KEY (norm_id, version_id),
  FOREIGN KEY (norm_id) REFERENCES law_norms(id) ON DELETE CASCADE
);
CREATE INDEX idx_law_norm_history_date ON law_norm_history(change_type, change_date DESC);
CREATE INDEX idx_law_norm_keywords_kind ON law_norm_keywords(kind, index_letter, keyword);
CREATE INDEX idx_law_norm_keywords_letter ON law_norm_keywords(index_letter, keyword, norm_id);
CREATE INDEX idx_law_norm_subjects_subject ON law_norm_subjects(subject_slug, norm_id);
CREATE INDEX idx_law_norms_amendment ON law_norms(is_amendment, last_change_date);
CREATE INDEX idx_law_norms_current_version ON law_norms(current_version_id);
CREATE INDEX idx_law_norms_index_letter ON law_norms(index_letter, sort_title);
CREATE INDEX idx_law_norms_inventory_letter ON law_norms(in_inventory, index_letter, sort_word);
CREATE INDEX idx_law_norms_inventory_origin ON law_norms(in_inventory, origin_kind, sort_word);
CREATE INDEX idx_law_norms_inventory_status ON law_norms(in_inventory, status, sort_word);
CREATE INDEX idx_law_norms_inventory_type ON law_norms(in_inventory, type, sort_word);
CREATE INDEX idx_law_norms_origin_kind ON law_norms(origin_kind, sort_title);
CREATE INDEX idx_law_norms_revosax_id ON law_norms(revosax_law_id);
CREATE INDEX idx_law_norms_sort_title ON law_norms(sort_title);
CREATE INDEX idx_law_norms_status ON law_norms(status);
CREATE INDEX idx_law_norms_status_sort ON law_norms(status, sort_title);
CREATE INDEX idx_law_norms_type ON law_norms(type);
CREATE INDEX idx_law_norms_type_sort ON law_norms(type, sort_title);
CREATE INDEX idx_law_publications_date ON law_publications(publication_date);
CREATE INDEX idx_law_search_units_norm ON law_search_units(norm_id);
CREATE INDEX idx_law_search_units_norm_version ON law_search_units(norm_id, version_id);
CREATE INDEX idx_law_search_units_slug ON law_search_units(slug);
CREATE INDEX idx_law_versions_candidate ON law_versions(norm_id, temporal_kind, publication_source, publication_year);
CREATE INDEX idx_law_versions_current ON law_versions(norm_id, is_current);
CREATE INDEX idx_law_versions_validity ON law_versions(norm_id, valid_from, valid_to);
CREATE TRIGGER law_search_units_ad AFTER DELETE ON law_search_units BEGIN
  INSERT INTO law_search(law_search, rowid, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body)
  VALUES ('delete', old.id, old.norm_id, old.version_id, old.provision_path, old.anchor, old.block_type, old.references_json, old.slug, old.title, old.short_title, old.abbr, old.label, old.heading, old.body);
END;
CREATE TRIGGER law_search_units_ai AFTER INSERT ON law_search_units BEGIN
  INSERT INTO law_search(rowid, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body)
  VALUES (new.id, new.norm_id, new.version_id, new.provision_path, new.anchor, new.block_type, new.references_json, new.slug, new.title, new.short_title, new.abbr, new.label, new.heading, new.body);
END;
CREATE TRIGGER law_search_units_au AFTER UPDATE ON law_search_units BEGIN
  INSERT INTO law_search(law_search, rowid, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body)
  VALUES ('delete', old.id, old.norm_id, old.version_id, old.provision_path, old.anchor, old.block_type, old.references_json, old.slug, old.title, old.short_title, old.abbr, old.label, old.heading, old.body);
  INSERT INTO law_search(rowid, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body)
  VALUES (new.id, new.norm_id, new.version_id, new.provision_path, new.anchor, new.block_type, new.references_json, new.slug, new.title, new.short_title, new.abbr, new.label, new.heading, new.body);
END;
