INSERT INTO law_norms (id, slug, title, short_title, abbr, type, status, revosax_law_id, current_version_id, document_date, publication_date, effective_date, expiry_date, initial_citation, summary, responsible_ministry, enacting_body, source_kind, updated_at, meta_json, history_json, sort_title, current_valid_from, subjects_json, primary_subject, keywords_json, aliases_json, origin_kind, origin_baseline_version_id, origin_last_own_change_date, version_count, last_change_date, index_letter, last_activity_date, is_amendment, in_inventory, sort_word, funding_area) VALUES ('dienstanordnung-momentane-terrorgefahr-2024', 'dienstanordnung-momentane-terrorgefahr-2024', 'Dienstanordnung anlässlich der momentanen Terrorgefahr', 'Dienstanordnung anlässlich der momentanen Terrorgefahr', NULL, 'verwaltungsvorschrift', 'repealed', NULL, '2024-10-02', '2024-10-02', '2024-10-15', '2024-10-02', '2024-10-06', 'Dienstanordnung vom 2. Oktober 2024 (OGVBl. 2024 Nr. II S. 4)', 'Ordnet wegen einer benannten Terrorgefahr Heimarbeit für die Beschäftigten der Staatsregierung an.', 'Staatskanzlei des Freistaates Ostdeutschland', 'Staatsregierung des Freistaates Ostdeutschland', 'repository', '2026-01-01T00:00:00.000Z', '{"id":"dienstanordnung-momentane-terrorgefahr-2024","slug":"dienstanordnung-momentane-terrorgefahr-2024","title":"Dienstanordnung anlässlich der momentanen Terrorgefahr","type":"verwaltungsvorschrift","enactingBody":"Staatsregierung des Freistaates Ostdeutschland","responsibleMinistry":"Staatskanzlei des Freistaates Ostdeutschland","subjects":["Staatliche Organisation","Sicherheitsrecht und Polizeirecht"],"primarySubject":"Staatliche Organisation","keywords":["Heimarbeit"],"initialCitation":"Dienstanordnung vom 2. Oktober 2024 (OGVBl. 2024 Nr. II S. 4)","predecessor":null,"successor":null,"affectedByNorms":["berichtigung-verschiedener-verkuendungen-2026"],"summary":"Ordnet wegen einer benannten Terrorgefahr Heimarbeit für die Beschäftigten der Staatsregierung an.","status":"repealed","documentDate":"2024-10-02","publicationDate":"2024-10-15","effectiveDate":"2024-10-02","expiryDate":"2024-10-06","dateNote":"Das zeitgenössische Einzeldokument und seine Discord-Veröffentlichung nennen den 2. Oktober 2024; die spätere Sammelausgabe gibt im Einleitungssatz abweichend den 23. September 2024 an und lässt das im Original bestimmte Außerkrafttreten am 6. Oktober 2024 aus. Für Datum und Geltungsende ist das zeitgenössische Original maßgeblich.","sourceReferences":[{"kind":"structured-html-transcription","label":"Vollständige strukturtragende HTML-Fassung der amtlichen Ausgabe","availability":"versioned","localSource":"Gesetze/OGVBl II-24.html","sha256":"058b560351875ba92af82acaab8890b3ebdd40fc8d46c6c9c6f82a714d8e7684","mediaType":"text/html","pageRange":"4","verifiedAt":"2026-08-28","sourceRole":"structure-bearing"},{"kind":"primary-pdf","label":"Amtliche visuelle Veröffentlichungsfassung","availability":"versioned","localSource":"Gesetze/OGVBl II-24.pdf","sha256":"9b9b5f8d691c8f4341711a5c30b4c1ac2a03a73a00cbf915688ef8a00b91a6fd","mediaType":"application/pdf","pageCount":32,"pageRange":"4","verifiedAt":"2026-08-28","sourceRole":"visual-control","derivedSource":"Gesetze/OGVBl II-24.html"},{"kind":"amendment-source","label":"Vollständige strukturtragende HTML-Fassung der amtlichen Ausgabe – Berichtigung Berichtigung vom 14. August 2026 (OGVBl. 2026 Nr. 68 S. 2)","availability":"versioned","localSource":"Gesetze/OGVBl.2026Nr.68.html","sha256":"7db4c0851e9a2f2c9bb4ef24675495b3c3a734373cc0b3c33189b4b005988013","mediaType":"text/html","pageRange":"2–5","verifiedAt":"2026-08-28","sourceRole":"amendment-evidence"},{"kind":"primary-pdf","label":"Amtliche visuelle Veröffentlichungsfassung – Berichtigung Berichtigung vom 14. August 2026 (OGVBl. 2026 Nr. 68 S. 2)","availability":"versioned","localSource":"Gesetze/OGVBl. 2026 Nr. 68.pdf","sha256":"4424c1ae079ae0ab0cd105de5192ac206b8bd325fc30b3fdfea2bcb7a91b385d","mediaType":"application/pdf","pageCount":5,"pageRange":"2–5","verifiedAt":"2026-08-28","sourceRole":"visual-control","derivedSource":"Gesetze/OGVBl.2026Nr.68.html"}]}', '{"initialVersionId":"2024-10-02","entries":[{"date":"2024-10-02","type":"initial","title":"Stammfassung verkündet.","citation":"Dienstanordnung vom 2. Oktober 2024 (OGVBl. 2024 Nr. II S. 4)","affectingVersionId":"2024-10-02"},{"date":"2026-08-27","type":"notice","title":"Datum und ausgelassenes Außerkrafttreten der nachgedruckten Dienstanordnung wurden amtlich berichtigt.","citation":"Berichtigung vom 14. August 2026 (OGVBl. 2026 Nr. 68 S. 2)","note":"Deklaratorische Berichtigung der Verkündungsfassung; kein materieller Fassungswechsel.","affectingVersionId":"2024-10-02","relatedNorm":"berichtigung-verschiedener-verkuendungen-2026"}]}', 'dienstanordnung anlässlich der momentanen terrorgefahr', '2024-10-02', '["Staatliche Organisation","Sicherheitsrecht und Polizeirecht"]', 'Staatliche Organisation', '["Heimarbeit"]', '[]', 'ostdeutsch-original', NULL, NULL, 1, '2024-10-02', 'D', '2026-08-27', 0, 1, 'dienstanordnung anlasslich der momentanen terrorgefahr', NULL);
INSERT INTO law_norms (id, slug, title, short_title, abbr, type, status, revosax_law_id, current_version_id, document_date, publication_date, effective_date, expiry_date, initial_citation, summary, responsible_ministry, enacting_body, source_kind, updated_at, meta_json, history_json, sort_title, current_valid_from, subjects_json, primary_subject, keywords_json, aliases_json, origin_kind, origin_baseline_version_id, origin_last_own_change_date, version_count, last_change_date, index_letter, last_activity_date, is_amendment, in_inventory, sort_word, funding_area) VALUES ('gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo', 'gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo', 'Gesetz über die Einführung einer kommunalen Privatisierungsbremse im Freistaat Ostdeutschland', 'Gesetz über die Einführung einer kommunalen Privatisierungsbremse im Freistaat Ostdeutschland', NULL, 'aenderungsvorschrift', 'in-force', NULL, '2026-03-23', '2026-03-23', '2026-03-24', '2026-03-25', NULL, 'Gesetz vom 23. März 2026 (OGVBl. 2026 Nr. 19)', 'Ändert die Ostdeutsche Gemeindeordnung: Kommunal beherrschte Versorgungs-, Infrastruktur-, Wohnungs- und Krankenhausunternehmen dürfen nur durch Satzung mit Zweidrittelmehrheit oder nach Bürgerentscheid veräußert werden.', 'Staatsministerium des Innern, Bau und für kommunale Angelegenheiten', NULL, 'repository', '2026-01-01T00:00:00.000Z', '{"id":"gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo","slug":"gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo","title":"Gesetz über die Einführung einer kommunalen Privatisierungsbremse im Freistaat Ostdeutschland","type":"aenderungsvorschrift","responsibleMinistry":"Staatsministerium des Innern, Bau und für kommunale Angelegenheiten","subjects":["Kommunalrecht"],"primarySubject":"Kommunalrecht","keywords":["Kommunen","Landkreise","Verwaltung","über"],"initialCitation":"Gesetz vom 23. März 2026 (OGVBl. 2026 Nr. 19)","predecessor":null,"successor":null,"affectedNorms":["saechsische-gemeindeordnung"],"summary":"Ändert die Ostdeutsche Gemeindeordnung: Kommunal beherrschte Versorgungs-, Infrastruktur-, Wohnungs- und Krankenhausunternehmen dürfen nur durch Satzung mit Zweidrittelmehrheit oder nach Bürgerentscheid veräußert werden.","status":"in-force","documentDate":"2026-03-23","publicationDate":"2026-03-24","effectiveDate":"2026-03-25","sourceReferences":[{"kind":"structured-html-transcription","label":"Vollständige strukturtragende HTML-Fassung der amtlichen Ausgabe","availability":"versioned","localSource":"Gesetze/OGVBl. 2026 Nr. 19.html","sha256":"9e0b79c9976d2ceb343f1ac97b3b572136e946cf07171fa541f0e193cf344f0e","mediaType":"text/html","pageRange":"2-3","verifiedAt":"2026-08-28","sourceRole":"structure-bearing"},{"kind":"primary-pdf","label":"Amtliche visuelle Veröffentlichungsfassung","availability":"versioned","localSource":"Gesetze/OGVBl. 2026 Nr. 19.pdf","sha256":"dcf81a44aa354df8d5c12e7641f0a0762318dc288fe0d34cc9aa282a1edc62dd","mediaType":"application/pdf","pageCount":3,"pageRange":"2-3","verifiedAt":"2026-08-28","sourceRole":"visual-control","derivedSource":"Gesetze/OGVBl. 2026 Nr. 19.html"}]}', '{"initialVersionId":"2026-03-23","entries":[{"date":"2026-03-23","type":"initial","title":"Stammfassung.","citation":"Gesetz vom 23. März 2026 (OGVBl. 2026 Nr. 19)","affectingVersionId":"2026-03-23"}]}', 'gesetz über die einführung einer kommunalen privatisierungsbremse im freistaat ostdeutschland', '2026-03-25', '["Kommunalrecht"]', 'Kommunalrecht', '["Kommunen","Landkreise","Verwaltung","über"]', '[]', 'ostdeutsch-original', NULL, NULL, 1, '2026-03-25', 'E', '2026-03-25', 1, 1, 'einfuhrung einer kommunalen privatisierungsbremse im freistaat ostdeutschland', NULL);
