,"predecessor":null,"successor":null,"status":"in-force","documentDate":"2022-11-30","sourceReferences":[{"kind":"revosax-snapshot","label":"Amtliche REVOSax-Fassung 19855.1, gültig ab 2021-01-01","availability":"r2-archived","objectKey":"revosax/2023-11-01/19855.html","url":"https://www.revosax.sachsen.de/vorschrift/19855","retrievedAt":"2026-09-03","sha256":"afb0809cf530af4a144363e2b3ce0b78cf6591af855252d79064a60d55beefae","lawId":"19855","sourceValidFrom":"2021-01-01","mediaType":"text/html","sourceRole":"official-snapshot","fsnNumber":"5502-V22.1"}]}', '{"initialVersionId":"2023-11-01","entries":[{"date":"2023-11-01","type":"initial","title":"Vollständige Ausgangsfassung zum Rechtsüberleitungsstichtag.","citation":"Interreg Ostdeutschland – Tschechien 2021–2027 vom 30. November 2022 (SächsABl. S. 1467)","affectingVersionId":"2023-11-01"}]}', 'bekanntmachung des ostdeutschen staatsministeriums für regionalentwicklung über das inkrafttreten des gemeinsamen umsetzungsdokumentes zur förderung der grenzübergreifenden zusammenarbeit zwischen dem freistaat ostdeutschland und der tschechischen republik in der förderperiode 2021–2027', '2023-11-01', '["Förderrichtlinien"]', 'Förderrichtlinien', '[]', '[]', 'inherited-unchanged', '2023-11-01', NULL, 1, '2023-11-01', 'I', '2023-11-01', 0, 1, 'interreg ostdeutschland – tschechien 2021–2027', '550');
INSERT INTO law_norms (id, slug, title, short_title, abbr, type, status, revosax_law_id, current_version_id, document_date, publication_date, effective_date, expiry_date, initial_citation, summary, responsible_ministry, enacting_body, source_kind, updated_at, meta_json, history_json, sort_title, current_valid_from, subjects_json, primary_subject, keywords_json, aliases_json, origin_kind, origin_baseline_version_id, origin_last_own_change_date, version_count, last_change_date, index_letter, last_activity_date, is_amendment, in_inventory, sort_word, funding_area) VALUES ('ndr-staatsvertrag', 'ndr-staatsvertrag', 'Staatsvertrag über den Norddeutschen Rundfunk', 'Staatsvertrag über den Norddeutschen Rundfunk', NULL, 'staatsvertrag', 'in-force', NULL, '2026-09-03', '2021-03-09', NULL, '2021-09-01', NULL, 'Staatsvertrag über den Norddeutschen Rundfunk (NDR-Staatsvertrag) vom 4./9. März 2021 (GVOBl. M-V S. 797)', 'Errichtet den Norddeutschen Rundfunk als gemeinsame Anstalt des öffentlichen Rechts der vertragschließenden Länder und regelt Auftrag, Angebote, Rundfunkrat, Verwaltungsrat, Intendanz, Wirtschaftsführung, Aufsicht und Datenschutz.', NULL, NULL, 'repository', '2026-01-01T00:00:00.000Z', '{"id":"ndr-staatsvertrag","slug":"ndr-staatsvertrag","title":"Staatsvertrag über den Norddeutschen Rundfunk","shortTitle":"NDR-Staatsvertrag","shortTitleSource":"official","type":"staatsvertrag","subjects":["Presse-, Rundfunk-, Filmwesen","Staatsverträge, Abkommen, Durchführung völkerrechtlicher und zwischenstaatlicher Vereinbarungen, Auslandsbeziehungen"],"primarySubject":"Presse-, Rundfunk-, Filmwesen","keywords":["NDR","NDR-StV","Norddeutscher Rundfunk","Rundfunkrat","Verwaltungsrat","Landesfunkhaus"],"initialCitation":"Staatsvertrag über den Norddeutschen Rundfunk (NDR-Staatsvertrag) vom 4./9. März 2021 (GVOBl. M-V S. 797)","predecessor":null,"successor":null,"affectedByNorms":["staatsvertrag-zur-anderung-des-staatsvertrages-uber-den-nord-122dpnt"],"summary":"Errichtet den Norddeutschen Rundfunk als gemeinsame Anstalt des öffentlichen Rechts der vertragschließenden Länder und regelt Auftrag, Angebote, Rundfunkrat, Verwaltungsrat, Intendanz, Wirtschaftsführung, Aufsicht und Datenschutz.","status":"in-force","documentDate":"2021-03-09","effectiveDate":"2021-09-01","dateNote":"Am 4. März 2021 (Hamburg), 5. März 2021 (Niedersachsen), 8. März 2021 (Schleswig-Holstein) und 9. März 2021 (Mecklenburg-Vorpommern) unterzeichnet und amtlich als „vom 4./9. März 2021“ zitiert. Nach § 52 Absatz 1 am 1. September 2021 in Kraft getreten.","sourceReferences":[{"kind":"structured-html-transcription","label":"Unveränderte amtliche Verkündungsfassung des Niedersächsischen Vorschrifteninformationssystems","availability":"versioned","localSource":"Gesetze/NDR-Staatsvertrag.html","sha256":"0d6aec03a0855b329af0aa2d74b028f7e4c140a154e16f97364b94273ccea6aa","mediaType":"text/html","verifiedAt":"2026-09-08","sourceRole":"structure-bearing"},{"kind":"primary-pdf","label":"Amtliche Vertragsfassung des Norddeutschen Rundfunks","availability":"versioned","localSource":"Gesetze/NDR-Staatsvertrag.pdf","url":"https://www.ndr.de/der_ndr/zahlen_und_daten/staatsvertrag202.pdf","sha256":"91f1bef329acdfc74735a7bf8607783bdd3a0b9af805892934e693fc1735907a","mediaType":"application/pdf","pageCount":30,"pageRange":"1–30","verifiedAt":"2026-09-08","sourceRole":"visual-control","derivedSource":"Gesetze/NDR-Staatsvertrag.html"},{"kind":"amendment-source","label":"OVertrBl. 2026 Nr. 4","availability":"versioned","localSource":"Gesetze/OVertrBl. 2026 Nr. 4.html"}],"editorialResolutions":[{"id":"ndr-vertragsblatt-4-quellenkorrektur-2026-09-02","status":"resolved-source-conflict","decisionDate":"2026-09-02","issue":"Die zuvor versionierte und gesperrte Fassung von OVertrBl. 2026 Nr. 4 enthielt in Anlage 1 einen fehlerhaften unausgefüllten Mustergesetz-Platzhalter anstelle der tatsächlich geänderten Ausgangsnorm.","publishedText":"Der Staatsvertrag über den Norddeutschen Rundfunk (NDR-Staatsvertrag) vom 4./9. März 2021 (GVOBl. M-V S. 797) wird wie folgt geändert:","resolvedApplication":"Für die Erfassung des Änderungsstaatsvertrags ist ausschließlich die korrigierte Fassung von OVertrBl. 2026 Nr. 4 maßgeblich. Der frühere Mustergesetz-Platzhalter wird nicht als eigene Zielnorm ausgewertet.","rationale":"Die frühere Fassung beruhte auf einem Fehler in den Quellen. Die korrigierte strukturtragende HTML-Fassung und die dazugehörige PDF-Fassung bezeichnen übereinstimmend den NDR-Staatsvertrag als Zielnorm und ersetzen die gesperrte fehlerhafte Ausgabe.","evidence":["Gesetze/OVertrBl. 2026 Nr. 4.html","Gesetze/OVertrBl. 2026 Nr. 4.pdf","content/verkuendungen/overtrbl-2026-04.json","content/normen/staatsvertrag-zur-anderung-des-staatsvertrages-uber-den-nord-122dpnt/versions/2026-03-08.json"]},{"id":"ndr-anlage-1-reichweite-2026-09-08","status":"resolved-source-conflict","decisionDate":"2026-09-08","issue":"Artikel 1 Absatz 1 Nummer 1 des Änderungsstaatsvertrages ordnet an, die Nennung Mecklenburg-Vorpommerns in allen Bestimmungen zu streichen. Anlage 1 setzt das für die Präambel, § 1 Absatz 1, § 2 Absatz 2, § 18 Absatz 1, § 20 Absatz 3, § 25 Absatz 1, § 28 Absatz 6 und § 39 Absatz 1 um; § 49 Absatz 4 bleibt unberührt und nennt Mecklenburg-Vorpommern weiterhin.","publishedText":"Die konkreten Textänderungen ergeben sich aus Anlage 1 zu diesem Staatsvertrag und sind Bestandteil dieses Staatsvertrags.","resolvedApplication":"Maßgeblich sind ausschließlich die in Anlage 1 einzeln verkündeten Änderungsbefehle. § 49 Absatz 4 wird unverändert wiedergegeben; eine über die Anlage hinausgehende Streichung wird nicht abgeleitet.","rationale":"Artikel 1 Absatz 2 bestimmt ausdrücklich, dass sich die konkreten Textänderungen aus Anlage 1 ergeben. Eine Vorschrift ohne Änderungsbefehl heuristisch umzuschreiben, wäre eine Auslegung ohne Primärquelle; sie unterbliebe bei einer späteren amtlichen Berichtigung nachträglich zu Recht.","evidence":["Gesetze/OVertrBl. 2026 Nr. 4.html","content/normen/staatsvertrag-zur-anderung-des-staatsvertrages-uber-den-nord-122dpnt/versions/2026-03-08.json","content/normen/ndr-staatsvertrag/versions/2026-09-03.json"]}]}', '{"initialVersionId":"2021-09-01","entries":[{"date":"2021-09-01","type":"initial","title":"Vollständige amtliche Ausgangsfassung, unverändert aus der archivierten Verkündungsfassung übernommen.","citation":"Staatsvertrag über den Norddeutschen Rundfunk (NDR-Staatsvertrag) vom 4./9. März 2021 (GVOBl. M-V S. 797)","affectingVersionId":"2021-09-01"},{"date":"2026-09-03","type":"amendment","title":"Die Präambel, das Sendegebiet, die Landesfunkhäuser, die Zusammensetzung von Rundfunkrat und Verwaltungsrat, der Vorsitzwechsel und die Rechtsaufsicht wurden auf das Land Niedersachsen-Holstein umgestellt; die Mitträgerschaft Mecklenburg-Vorpommerns entfällt.","citation":"Staatsvertrag vom 8. März 2026 (OVertrBl. 2026 Nr. 4 S. 2)","affectingVersionId":"2026-09-03","relatedNorm":"staatsvertrag-zur-anderung-des-staatsvertrages-uber-den-nord-122dpnt"}]}', 'staatsvertrag über den norddeutschen rundfunk', '2026-09-03', '["Presse-, Rundfunk-, Filmwesen","Staatsverträge, Abkommen, Durchführung völkerrechtlicher und zwischenstaatlicher Vereinbarungen, Auslandsbeziehungen"]', 'Presse-, Rundfunk-, Filmwesen', '["NDR","NDR-StV","Norddeutscher Rundfunk","Rundfunkrat","Verwaltungsrat","Landesfunkhaus"]', '["NDR-Staatsvertrag"]', 'origin-unresolved', NULL, '2026-09-03', 2, '2026-09-03', 'N', '2026-09-03', 0, 1, 'norddeutschen rundfunk', NULL);
INSERT INTO law_norms (id, slug, title, short_title, abbr, type, status, revosax_law_id, current_version_id, document_date, publication_date, effective_date, expiry_date, initial_citation, summary, responsible_ministry, enacting_body, source_kind, updated_at, meta_json, history_json, sort_title, current_valid_from, subjects_json, primary_subject, keywords_json, aliases_json, origin_kind, origin_baseline_version_id, origin_last_own_change_date, version_count, last_change_date, index_letter, last_activity_date, is_amendment, in_inventory, sort_word, funding_area) VALUES ('oberstufenund-abiturprufungsverordnung', 'oberstufenund-abiturprufungsverordnung', 'Verordnung des Sächsischen Staatsministeriums für Kultus über die gymnasiale Oberstufe und die Abiturprüfung an allgemeinbildenden Gymnasien im Freistaat Sachsen', 'Oberstufen- und Abiturprüfungsverordnung', 'OAVO', 'verordnung', 'repealed', NULL, '2024-10-15', NULL, NULL, NULL, '2008-07-31', 'Verordnung vom 15. Oktober 2024 (OGVBl. 2024 Nr. 2 S. 2)', 'Die Verordnung konkretisiert die gesetzlichen Vorgaben zu „Oberstufen- und Abiturprüfungsverordnung“ und bestimmt das anzuwendende Verfahren.', 'Staatsministerium für Kultus, Jugend und Sport', NULL, 'repository', '2026-01-01T00:00:00.000Z', '{"id":"oberstufenund-abiturprufungsverordnung","slug":"oberstufenund-abiturprufungsverordnung","title":"Verordnung des Sächsischen Staatsministeriums für Kultus über die gymnasiale Oberstufe und die Abiturprüfung an allgemeinbildenden Gymnasien im Freistaat Sachsen","shortTitle":"Oberstufen- und Abiturprüfungsverordnung","abbr":"OAVO","type":"verordnung","responsibleMinistry":"Staatsministerium für Kultus, Jugend und Sport","subjects":["Bildungswesen"],"primarySubject":"Bildungswesen","keywords":["Bildung","Weiterbildung","Schule","über"],"initialCitation":"Verordnung vom 15. Oktober 2024 (OGVBl. 2024 Nr. 2 S. 2)","predecessor":null,"successor":null,"affectedByNorms":["verordnung-aenderung-oberstufen-abiturpruefungsverordnung-2024","verordnung-zur-bereinigung-des-allgemeinbildenden-schulordnungsrechts-2026"],"relatedNorms":["schulordnung-erweiterte-oberschulen-und-abiturpruefung"],"summary":"Die Verordnung konkretisiert die gesetzlichen Vorgaben zu „Oberstufen- und Abiturprüfungsverordnung“ und bestimmt das anzuwendende Verfahren.","status":"repealed","expiryDate":"2008-07-31","dateNote":"Die Verordnung vom 15. Januar 1996 war nach der amtlichen Klarstellung in OGVBl. 2026 Nr. 67 seit dem 1. August 2008 außer Kraft. Der 2024 verkündete Änderungsakt setzte sie weder neu noch wieder in Kraft.","sourceReferences":[{"kind":"legacy-markdown-transcription","label":"Historische Markdown-Transkription (Altbestand)","availability":"versioned","localSource":"Gesetze/OGVBl. 2024 Nr. 2 S. 2.md"}]}', '{"initialVersionId":null,"entries":[{"date":"2024-10-15","type":"notice","title":"Historischer Text veröffentlicht; keine Wiederinkraftsetzung.","citation":"Verordnung vom 15. Oktober 2024 (OGVBl. 2024 Nr. 2 S. 2)","note":"OGVBl. 2026 Nr. 67 stellt verbindlich klar, dass die ältere Stammverordnung bereits seit dem 1. August 2008 außer Kraft war und der Akt von 2024 sie nicht wieder in Kraft setzte.","affectingVersionId":"2024-10-15"},{"date":"2026-08-16","type":"notice","title":"Außerkrafttreten und fehlende Wiederinkraftsetzung amtlich klargestellt.","citation":"Verordnung vom 16. August 2026 (OGVBl. 2026 Nr. 67 S. 21)","relatedNorm":"verordnung-zur-bereinigung-des-allgemeinbildenden-schulordnungsrechts-2026"}]}', 'verordnung des sächsischen staatsministeriums für kultus über die gymnasiale oberstufe und die abiturprüfung an allgemeinbildenden gymnasien im freistaat sachsen', '1996-01-15', '["Bildungswesen"]', 'Bildungswesen', '["Bildung","Weiterbildung","Schule","über"]', '[]', 'origin-unresolved', NULL, NULL, 1, '1996-01-15', 'O', '2026-08-16', 0, 1, 'oberstufen- und abiturprufungsverordnung', NULL);
