INSERT INTO law_versions (norm_id, version_id, valid_from, valid_to, is_current, title, short_title, abbr, summary, citation, change_note, source_sha256, source_url, source_retrieved_at, source_object_key, updated_at, version_json, full_citation, publication_ref_json, temporal_kind, publication_source, publication_year) VALUES ('abschiebe-aussetzungsverordnung', '2024-03-01', '2024-03-01', '2025-09-15', 0, NULL, NULL, NULL, NULL, 'Verordnung vom 1. März 2024 (amtliche Einzelverkündung)', 'Amtlich verkündete Stammfassung.', NULL, NULL, NULL, NULL, '2026-01-01T00:00:00.000Z', '{"versionId":"2024-03-01","validFrom":"2024-03-01","validTo":"2025-09-15","isCurrent":false,"citation":"Verordnung vom 1. März 2024 (amtliche Einzelverkündung)","changeNote":"Amtlich verkündete Stammfassung.","sourceReferences":[{"kind":"structured-html-transcription","label":"Redaktionell geprüfte strukturierte Transkription der PDF-Lesefassung","availability":"versioned","localSource":"Gesetze/Abschiebe-Aussetzungsverordnung.html","mediaType":"text/html","verifiedAt":"2026-08-27","sourceRole":"structure-bearing","derivedSource":"Gesetze/Abschiebe-Aussetzungsverordnung.pdf"},{"kind":"primary-pdf","label":"Amtliche PDF-Lesefassung der historischen Verordnung","availability":"versioned","localSource":"Gesetze/Abschiebe-Aussetzungsverordnung.pdf","url":"/assets/recht/einzelverkuendung-2024-03-01.pdf","sha256":"314662ec15a652a51297251f266b34c3187838af8b1c6e78ff4132dcb18552fb","mediaType":"application/pdf","pageCount":4,"pageRange":"1–4","verifiedAt":"2026-08-27","sourceRole":"visual-control","derivedSource":"Gesetze/Abschiebe-Aussetzungsverordnung.html"}],"sourceNotes":[{"label":"Zeitliche Wirkung","text":"Der Abschiebungsstopp galt nach dem Wortlaut für drei Monate ab dem 1. März 2024. Die Stammnorm blieb bis zu ihrer ausdrücklichen Aufhebung am 16. September 2025 historisch dokumentiert."}]}', 'Verordnung Aussetzung von Abschiebungen vom 1. März 2024 (amtliche Einzelverkündung)', '{"publicationSl