INSERT INTO law_versions (norm_id, version_id, valid_from, valid_to, is_current, title, short_title, abbr, summary, citation, change_note, source_sha256, source_url, source_retrieved_at, source_object_key, updated_at, version_json, full_citation, publication_ref_json, temporal_kind, publication_source, publication_year) VALUES ('dienstanordnung-momentane-terrorgefahr-2024', '2024-10-02', '2024-10-02', '2024-10-06', 0, NULL, NULL, NULL, NULL, 'Dienstanordnung vom 2. Oktober 2024 (OGVBl. 2024 Nr. II S. 4)', 'Amtlich verkündete Stammfassung.', NULL, NULL, NULL, NULL, '2026-01-01T00:00:00.000Z', '{"versionId":"2024-10-02","validFrom":"2024-10-02","validTo":"2024-10-06","isCurrent":false,"citation":"Dienstanordnung vom 2. Oktober 2024 (OGVBl. 2024 Nr. II S. 4)","changeNote":"Amtlich verkündete Stammfassung.","sourceReferences":[{"kind":"structured-html-transcription","label":"Redaktionell geprüfte strukturierte Transkription der Ausgabe","availability":"versioned","localSource":"Gesetze/OGVBl II-24.html","mediaType":"text/html","pageRange":"4","verifiedAt":"2026-07-23","sourceRole":"structure-bearing","derivedSource":"Gesetze/OGVBl II-24.pdf"},{"kind":"primary-pdf","label":"Amtliches Original-PDF der Ausgabe","availability":"versioned","localSource":"Gesetze/OGVBl II-24.pdf","sha256":"9b9b5f8d691c8f4341711a5c30b4c1ac2a03a73a00cbf915688ef8a00b91a6fd","mediaType":"application/pdf","pageCount":32,"pageRange":"4","verifiedAt":"2026-07-23","sourceRole":"visual-control","derivedSource":"Gesetze/OGVBl II-24.html"},{"kind":"primary-pdf","label":"Zeitgenössisches amtliches Einzeldokument","availability":"versioned","localSource":"Gesetze/Veordnung_24-03_MP.pdf","url":"/assets/recht/Veordnung_24-03_MP.pdf","sha256":"b5b1a81aea01146a774f9c3072dd67091e9a511f1e980528941d44cbc964ef43","mediaType":"application/pdf","pageCount":1,"pageRange":"1","verifiedAt":"2026-08-27","sourceRole":"visual-control"},{"kind":"amendment-source","label":"Vollständige strukturtragende HTML-Fassung der amtlichen Ausgabe – Berichtigung Berichtigung vom 14. August 2026 (OGVBl. 2026 Nr. 68 S. 2)","availability":"versioned","localSource":"Gesetze/OGVBl.2026Nr.68.html","sha256":"7db4c0851e9a2f2c9bb4ef24675495b3c3a734373cc0b3c33189b4b005988013","mediaType":"text/html","pageRange":"2–5","verifiedAt":"2026-08-28","sourceRole":"amendment-evidence"},{"kind":"primary-pdf","label":"Amtliche visuelle Veröffentlichungsfassung – Berichtigung Berichtigung vom 14. August 2026 (OGVBl. 2026 Nr. 68 S. 2)","availability":"versioned","localSource":"Gesetze/OGVBl. 2026 Nr. 68.pdf","sha256":"4424c1ae079ae0ab0cd105de5192ac206b8bd325fc30b3fdfea2bcb7a91b385d","mediaType":"application/pdf","pageCount":5,"pageRange":"2–5","verifiedAt":"2026-08-28","sourceRole":"visual-control","derivedSource":"Gesetze/OGVBl.2026Nr.68.html"}],"sourceNotes":[{"label":"Abweichende Datumsangaben","text":"Das Inhaltsverzeichnis nennt den 2. Oktober 2024, der Einleitungssatz im Normtext dagegen den 23. September 2024. Das Portal führt beide Angaben getrennt und nimmt keine stillschweigende Bereinigung vor."},{"label":"Amtliche Berichtigung","text":"Berichtigung vom 14. August 2026 (OGVBl. 2026 Nr. 68 S. 2): Datum und ausgelassenes Außerkrafttreten der nachgedruckten Dienstanordnung wurden amtlich berichtigt. Die Gültigkeit dieser Fassung beginnt unverändert am 2024-10-02."}]}', 'Dienstanordnung anlässlich der momentanen Terrorgefahr vom 2. Oktober 2024 (OGVBl. 2024 Nr. II S. 4)', '{"publicationSlug":"ogvbl-2024-ii","publicationTitle":"Ostdeutsches Gesetz- und Verordnungsblatt 2024 Nr. II","publicationDate":"2024-10-15","publication":"OGVBl.","publicationAliases":["OGVBl Nr. II/24","OGVBl. 2024 Nr. II"],"issue":"II","entryId":"dienstanordnung-momentane-terrorgefahr-2024","entryTitle":"Dienstanordnung anlässlich der momentanen Terrorgefahr","citation":"Dienstanordnung vom 2. Oktober 2024 (OGVBl. 2024 Nr. II S. 4)","pages":"4"}', 'historical', 'OGVBl.', '2024');
