INSERT INTO law_versions (norm_id, version_id, valid_from, valid_to, is_current, title, short_title, abbr, summary, citation, change_note, source_sha256, source_url, source_retrieved_at, source_object_key, updated_at, version_json, full_citation, publication_ref_json, temporal_kind, publication_source, publication_year) VALUES ('interreg-ostdeutschland-tschechien-2021-2027', '2023-11-01', '2023-11-01', NULL, 1, 'Bekanntmachung des Ostdeutschen Staatsministeriums für Regionalentwicklung über das Inkrafttreten des Gemeinsamen Umsetzungsdokumentes zur Förderung der grenzübergreifenden Zusammenarbeit zwischen dem Freistaat Ostdeutschland und der Tschechischen Republik in der Förderperiode 2021–2027', 'Interreg Ostdeutschland – Tschechien 2021–2027', NULL, NULL, 'Interreg Ostdeutschland – Tschechien 2021–2027 vom 30. November 2022 (SächsABl. S. 1467)', 'Ausgangsfassung zum Rechtsüberleitungsstichtag 2023-11-01: übernommener Rechtsstand dieses Tages.', 'afb0809cf530af4a144363e2b3ce0b78cf6591af855252d79064a60d55beefae', 'https://www.revosax.sachsen.de/vorschrift/19855', '2026-09-03', 'revosax/2023-11-01/19855.html', '2026-01-01T00:00:00.000Z', '{"versionId":"2023-11-01","validFrom":"2023-11-01","validTo":null,"isCurrent":true,"title":"Bekanntmachung des Ostdeutschen Staatsministeriums für Regionalentwicklung über das Inkrafttreten des Gemeinsamen Umsetzungsdokumentes zur Förderung der grenzübergreifenden Zusammenarbeit zwischen dem Freistaat Ostdeutschland und der Tschechischen Republik in der Förderperiode 2021–2027","shortTitle":"Interreg Ostdeutschland – Tschechien 2021–2027","citation":"Interreg Ostdeutschland – Tschechien 2021–2027 vom 30. November 2022 (SächsABl. S. 1467)","changeNote":"Ausgangsfassung zum Rechtsüberleitungsstichtag 2023-11-01: übernommener Rechtsstand dieses Tages.","sourceReferences":[{"kind":"revosax-snapshot","label":"Amtliche REVOSax-Fassung 19855.1, gültig ab 2021-01-01","availability":"r2-archived","objectKey":"revosax/2023-11-01/19855.html","url":"https://www.revosax.sachsen.de/vorschrift/19855","retrievedAt":"2026-09-03","sha256":"afb0809cf530af4a144363e2b3ce0b78cf6591af855252d79064a60d55beefae","lawId":"19855","sourceValidFrom":"2021-01-01","mediaType":"text/html","sourceRole":"official-snapshot","fsnNumber":"5502-V22.1"}]}', 'Interreg Ostdeutschland – Tschechien 2021–2027 vom 30. November 2022 (SächsABl. S. 1467)', NULL, 'current', NULL, NULL);
INSERT INTO law_versions (norm_id, version_id, valid_from, valid_to, is_current, title, short_title, abbr, summary, citation, change_note, source_sha256, source_url, source_retrieved_at, source_object_key, updated_at, version_json, full_citation, publication_ref_json, temporal_kind, publication_source, publication_year) VALUES ('ndr-staatsvertrag', '2021-09-01', '2021-09-01', '2026-09-02', 0, 'Staatsvertrag über den Norddeutschen Rundfunk', 'NDR-Staatsvertrag', NULL, NULL, 'Staatsvertrag über den Norddeutschen Rundfunk (NDR-Staatsvertrag) vom 4./9. März 2021 (GVOBl. M-V S. 797)', 'Amtliche Ausgangsfassung des Staatsvertrages; unverändert aus der archivierten Verkündungsfassung übernommen.', '0d6aec03a0855b329af0aa2d74b028f7e4c140a154e16f97364b94273ccea6aa', NULL, NULL, NULL, '2026-01-01T00:00:00.000Z', '{"versionId":"2021-09-01","validFrom":"2021-09-01","validTo":"2026-09-02","isCurrent":false,"title":"Staatsvertrag über den Norddeutschen Rundfunk","shortTitle":"NDR-Staatsvertrag","citation":"Staatsvertrag über den Norddeutschen Rundfunk (NDR-Staatsvertrag) vom 4./9. März 2021 (GVOBl. M-V S. 797)","changeNote":"Amtliche Ausgangsfassung des Staatsvertrages; unverändert aus der archivierten Verkündungsfassung übernommen.","sourceReferences":[{"kind":"structured-html-transcription","label":"Unveränderte amtliche Verkündungsfassung des Niedersächsischen Vorschrifteninformationssystems","availability":"versioned","localSource":"Gesetze/NDR-Staatsvertrag.html","sha256":"0d6aec03a0855b329af0aa2d74b028f7e4c140a154e16f97364b94273ccea6aa","mediaType":"text/html","verifiedAt":"2026-09-08","sourceRole":"structure-bearing"},{"kind":"primary-pdf","label":"Amtliche Vertragsfassung des Norddeutschen Rundfunks","availability":"versioned","localSource":"Gesetze/NDR-Staatsvertrag.pdf","url":"https://www.ndr.de/der_ndr/zahlen_und_daten/staatsvertrag202.pdf","sha256":"91f1bef329acdfc74735a7bf8607783bdd3a0b9af805892934e693fc1735907a","mediaType":"application/pdf","pageCount":30,"pageRange":"1–30","verifiedAt":"2026-09-08","sourceRole":"visual-control","derivedSource":"Gesetze/NDR-Staatsvertrag.html"}],"sourceNotes":[{"label":"Verkündungsfundstellen","text":"Die archivierte Textfassung ist die niedersächsische Verkündung als Anlage des Gesetzes zum Staatsvertrag über den Norddeutschen Rundfunk vom 7. Juli 2021 (Nds. GVBl. S. 487 – VORIS 22620). Der ostdeutsche Änderungsstaatsvertrag bezeichnet dieselbe Vertragsurkunde nach der mecklenburg-vorpommerschen Verkündung (GVOBl. M-V S. 797); danach richtet sich die Zitierung."}]}', 'Staatsvertrag über den Norddeutschen Rundfunk (NDR-Staatsvertrag) vom 4./9. März 2021 (GVOBl. M-V S. 797)', NULL, 'historical', NULL, NULL);
INSERT INTO law_versions (norm_id, version_id, valid_from, valid_to, is_current, title, short_title, abbr, summary, citation, change_note, source_sha256, source_url, source_retrieved_at, source_object_key, updated_at, version_json, full_citation, publication_ref_json, temporal_kind, publication_source, publication_year) VALUES ('ndr-staatsvertrag', '2026-09-03', '2026-09-03', NULL, 1, 'Staatsvertrag über den Norddeutschen Rundfunk', NULL, NULL, NULL, 'Staatsvertrag über den Norddeutschen Rundfunk (NDR-Staatsvertrag) vom 4./9. März 2021 (GVOBl. M-V S. 797), geändert durch Artikel 1 des Staatsvertrages vom 8. März 2026 (OVertrBl. 2026 Nr. 4 S. 2)', 'Die Präambel, das Sendegebiet, die Landesfunkhäuser, die Zusammensetzung von Rundfunkrat und Verwaltungsrat, der Vorsitzwechsel und die Rechtsaufsicht wurden auf das Land Niedersachsen-Holstein umgestellt; die Mitträgerschaft Mecklenburg-Vorpommerns entfällt.', NULL, NULL, NULL, NULL, '2026-01-01T00:00:00.000Z', '{"versionId":"2026-09-03","validFrom":"2026-09-03","validTo":null,"isCurrent":true,"title":"Staatsvertrag über den Norddeutschen Rundfunk","citation":"Staatsvertrag über den Norddeutschen Rundfunk (NDR-Staatsvertrag) vom 4./9. März 2021 (GVOBl. M-V S. 797), geändert durch Artikel 1 des Staatsvertrages vom 8. März 2026 (OVertrBl. 2026 Nr. 4 S. 2)","changeNote":"Die Präambel, das Sendegebiet, die Landesfunkhäuser, die Zusammensetzung von Rundfunkrat und Verwaltungsrat, der Vorsitzwechsel und die Rechtsaufsicht wurden auf das Land Niedersachsen-Holstein umgestellt; die Mitträgerschaft Mecklenburg-Vorpommerns entfällt.","sourceReferences":[{"kind":"amendment-source","label":"OVertrBl. 2026 Nr. 4","availability":"versioned","localSource":"Gesetze/OVertrBl. 2026 Nr. 4.html"}]}', 'Staatsvertrag über den Norddeutschen Rundfunk (NDR-Staatsvertrag) vom 4./9. März 2021 (GVOBl. M-V S. 797), der zuletzt durch Staatsvertrag vom 8. März 2026 (OVertrBl. 2026 Nr. 4 S. 2) geändert worden ist', NULL, 'current', NULL, NULL);
INSERT INTO law_versions (norm_id, version_id, valid_from, valid_to, is_current, title, short_title, abbr, summary, citation, change_note, source_sha256, source_url, source_retrieved_at, source_object_key, updated_at, version_json, full_citation, publication_ref_json, temporal_kind, publication_source, publication_year) VALUES ('oberstufenund-abiturprufungsverordnung', '2024-10-15', '1996-01-15', '2008-07-31', 0, NULL, NULL, NULL, NULL, 'Verordnung vom 15. Oktober 2024 (OGVBl. 2024 Nr. 2 S. 2)', 'Historisch überlieferter Wortlaut; nach OGVBl. 2026 Nr. 67 seit dem 1. August 2008 außer Kraft und 2024 nicht wieder in Kraft gesetzt.', NULL, NULL, NULL, NULL, '2026-01-01T00:00:00.000Z', '{"versionId":"2024-10-15","validFrom":"1996-01-15","validTo":"2008-07-31","isCurrent":false,"citation":"Verordnung vom 15. Oktober 2024 (OGVBl. 2024 Nr. 2 S. 2)","changeNote":"Historisch überlieferter Wortlaut; nach OGVBl. 2026 Nr. 67 seit dem 1. August 2008 außer Kraft und 2024 nicht wieder in Kraft gesetzt."}', 'Verordnung des Sächsischen Staatsministeriums für Kultus über die gymnasiale Oberstufe und die Abiturprüfung an allgemeinbildenden Gymnasien im Freistaat Sachsen vom 15. Oktober 2024 (OGVBl. 2024 Nr. 2 S. 2)', NULL, 'historical', NULL, NULL);
INSERT INTO law_versions (norm_id, version_id, valid_from, valid_to, is_current, title, short_title, abbr, summary, citation, change_note, source_sha256, source_url, source_retrieved_at, source_object_key, updated_at, version_json, full_citation, publication_ref_json, temporal_kind, publication_source, publication_year) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', '2023-11-01', '2024-03-07', 0, 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', NULL, 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland vom 10. November 1992 (SächsGVBl. S. 536), zuletzt geändert durch Gesetz vom 30. Januar 2013 (SächsGVBl. S. 2)', 'Ausgangsfassung zum Rechtsüberleitungsstichtag 2023-11-01: übernommener Rechtsstand dieses Tages.', '16f86a9d3c195798f52d4c6a9d57265bf05a64be2a7a7357a44c336efdde3ac7', 'https://www.revosax.sachsen.de/vorschrift/3997.5', '2026-07-23', NULL, '2026-01-01T00:00:00.000Z', '{"versionId":"2023-11-01","validFrom":"2023-11-01","validTo":"2024-03-07","isCurrent":false,"title":"Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland","shortTitle":"Ostdeutsches Feiertagsgesetz","abbr":"OstFSG","citation":"Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland vom 10. November 1992 (SächsGVBl. S. 536), zuletzt geändert durch Gesetz vom 30. Januar 2013 (SächsGVBl. S. 2)","changeNote":"Ausgangsfassung zum Rechtsüberleitungsstichtag 2023-11-01: übernommener Rechtsstand dieses Tages.","sourceReferences":[{"kind":"revosax-snapshot","label":"Amtliche REVOSax-Fassung, gültig 2013-02-10 bis 2025-05-06","availability":"versioned","localSource":"data/recht/sources/revosax/ostdeutsches-feiertagsgesetz/3997.5.html","url":"https://www.revosax.sachsen.de/vorschrift/3997.5","retrievedAt":"2026-07-23","sha256":"16f86a9d3c195798f52d4c6a9d57265bf05a64be2a7a7357a44c336efdde3ac7","lawId":"3997","sourceValidFrom":"2013-02-10","sourceValidTo":"2025-05-06"}],"sourceNotes":[{"label":"1","text":"§ 1 Absatz 1 geändert durch Artikel 4 des Gesetzes vom 6. Juni 2002 (SächsGVBl. S. 168, 170)"},{"label":"2","text":"§ 2a neu eingefügt durch Gesetz vom 27. März 2008 (SächsGVBl. S. 274)"},{"label":"3","text":"§ 3 Absatz 1 geändert durch Artikel 4 des Gesetzes vom 6. Juni 2002 (SächsGVBl. S. 168, 170)"},{"label":"4","text":"§ 4 geändert durch Artikel 2 des Gesetzes vom 1. Dezember 2010 (SächsGVBl. S. 338, 340) und durch Gesetz vom 30. Januar 2013 (SächsGVBl. S. 2)"},{"label":"5","text":"§ 6 geändert durch Gesetz vom 27. März 2008 (SächsGVBl. S. 274)"},{"label":"6","text":"§ 8 Absatz 2 geändert durch Artikel 4 des Gesetzes vom 6. Juni 2002 (SächsGVBl. S. 168, 170)"}]}', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland vom 10. November 1992 (SächsGVBl. S. 536), zuletzt geändert durch Gesetz vom 30. Januar 2013 (SächsGVBl. S. 2)', NULL, 'historical', NULL, NULL);
INSERT INTO law_versions (norm_id, version_id, valid_from, valid_to, is_current, title, short_title, abbr, summary, citation, change_note, source_sha256, source_url, source_retrieved_at, source_object_key, updated_at, version_json, full_citation, publication_ref_json, temporal_kind, publication_source, publication_year) VALUES ('ostdeutsches-feiertagsgesetz', '2024-03-07', '2024-03-08', '2026-03-23', 0, 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', NULL, 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland vom 10. November 1992 (SächsGVBl. S. 536), geändert durch Gesetz vom 7. März 2024 (OGVBl. 2024 Nr. I S. 1)', 'Vollständige Fassung nach der Änderung vom 7. März 2024.', NULL, NULL, NULL, NULL, '2026-01-01T00:00:00.000Z', '{"versionId":"2024-03-07","validFrom":"2024-03-08","validTo":"2026-03-23","isCurrent":false,"title":"Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland","shortTitle":"Ostdeutsches Feiertagsgesetz","abbr":"OstFSG","citation":"Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland vom 10. November 1992 (SächsGVBl. S. 536), geändert durch Gesetz vom 7. März 2024 (OGVBl. 2024 Nr. I S. 1)","changeNote":"Vollständige Fassung nach der Änderung vom 7. März 2024.","sourceReferences":[{"kind":"amendment-source","label":"Amtliche Ausgabe OGVBl. 2024 Nr. I","availability":"versioned","localSource":"Gesetze/OGVBl-03-24.pdf"}]}', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland vom 10. November 1992 (SächsGVBl. S. 536), das zuletzt durch das Gesetz vom 7. März 2024 (OGVBl. 2024 Nr. I S. 1) geändert worden ist', NULL, 'historical', NULL, NULL);
