INSERT INTO law_versions (norm_id, version_id, valid_from, valid_to, is_current, title, short_title, abbr, summary, citation, change_note, source_sha256, source_url, source_retrieved_at, source_object_key, updated_at, version_json, full_citation, publication_ref_json, temporal_kind, publication_source, publication_year) VALUES ('ostdeutsches-landesantidiskriminierungsgesetz', '2026-03-23', '2026-03-25', '2026-09-11', 0, NULL, NULL, NULL, NULL, 'Gesetz vom 23. März 2026 (OGVBl. 2026 Nr. 25)', 'Stammfassung.', NULL, NULL, NULL, NULL, '2026-01-01T00:00:00.000Z', '{"versionId":"2026-03-23","validFrom":"2026-03-25","validTo":"2026-09-11","isCurrent":false,"citation":"Gesetz vom 23. März 2026 (OGVBl. 2026 Nr. 25)","changeNote":"Stammfassung."}', 'Gesetz zur Förderung der Gleichbehandlung und zum Schutz vor Diskriminierung im öffentlich-rechtlichen Handeln vom 23. März 2026 (OGVBl. 2026 Nr. 25)', '{"publicationSlug":"ogvbl-2026-25","publicationTitle":"Ostdeutsches Gesetz- und Verordnungsblatt 2026 Nr. 25","publicationDate":"2026-03-24","publication":"OGVBl.","publicationAliases":[],"issue":"25","entryId":"ostdeutsches-landesantidiskriminierungsgesetz","entryTitle":"Gesetz zur Förderung der Gleichbehandlung und zum Schutz vor Diskriminierung im öffentlich-rechtlichen Handeln","citation":"Gesetz vom 23. März 2026 (OGVBl. 2026 Nr. 25)"}', 'historical', 'OGVBl.', '2026');
INSERT INTO law_versions (norm_id, version_id, valid_from, valid_to, is_current, title, short_title, abbr, summary, citation, change_note, source_sha256, source_url, source_retrieved_at, source_object_key, updated_at, version_json, full_citation, publication_ref_json, temporal_kind, publication_source, publication_year) VALUES ('ostdeutsches-landesantidiskriminierungsgesetz', '2026-09-12', '2026-09-12', NULL, 1, 'Besonderes Gesetz zur Förderung der Gleichbehandlung und zum Schutz vor Diskriminierung im öffentlich-rechtlichen Handeln', 'Ostdeutsches Landesantidiskriminierungsgesetz', 'OLADG', NULL, 'Ostdeutsches Landesantidiskriminierungsgesetz vom 23. März 2026 (OGVBl. 2026 Nr. 25), als besonderes Gesetz bestätigt und geändert durch Artikel 5 des Gesetzes vom 12. September 2026 (OGVBl. 2026 Nr. 76 S. 2)', 'Als besonderes Gesetz im Sinne des Artikels 74a der Staatsverfassung bestätigt; Gesetzesüberschrift neu gefasst, § 2 (Diskriminierungsverbot) neu gefasst, in § 3 Absatz 1 Satz 1 das Wort „Landtag“ durch „Volkskammer“ ersetzt (wörtliche Ersetzung, Wortlaut wie angeordnet).', NULL, NULL, NULL, NULL, '2026-01-01T00:00:00.000Z', '{"versionId":"2026-09-12","validFrom":"2026-09-12","validTo":null,"isCurrent":true,"title":"Besonderes Gesetz zur Förderung der Gleichbehandlung und zum Schutz vor Diskriminierung im öffentlich-rechtlichen Handeln","shortTitle":"Ostdeutsches Landesantidiskriminierungsgesetz","abbr":"OLADG","citation":"Ostdeutsches Landesantidiskriminierungsgesetz vom 23. März 2026 (OGVBl. 2026 Nr. 25), als besonderes Gesetz bestätigt und geändert durch Artikel 5 des Gesetzes vom 12. September 2026 (OGVBl. 2026 Nr. 76 S. 2)","changeNote":"Als besonderes Gesetz im Sinne des Artikels 74a der Staatsverfassung bestätigt; Gesetzesüberschrift neu gefasst, § 2 (Diskriminierungsverbot) neu gefasst, in § 3 Absatz 1 Satz 1 das Wort „Landtag“ durch „Volkskammer“ ersetzt (wörtliche Ersetzung, Wortlaut wie angeordnet).","sourceReferences":[{"kind":"amendment-source","label":"OGVBl. 2026 Nr. 76","availability":"versioned","localSource":"Gesetze/OGVBl. 2026 Nr. 76.html"}]}', 'Ostdeutsches Landesantidiskriminierungsgesetz vom 23. März 2026 (OGVBl. 2026 Nr. 25), als besonderes Gesetz bestätigt und geändert durch Artikel 5 des Gesetzes vom 12. September 2026 (OGVBl. 2026 Nr. 76 S. 2), das zuletzt durch Artikel 5 des Gesetzes vom 12. September 2026 (OGVBl. 2026 Nr. 76 S. 2) geändert worden ist', NULL, 'current', NULL, NULL);
INSERT INTO law_versions (norm_id, version_id, valid_from, valid_to, is_current, title, short_title, abbr, summary, citation, change_note, source_sha256, source_url, source_retrieved_at, source_object_key, updated_at, version_json, full_citation, publication_ref_json, temporal_kind, publication_source, publication_year) VALUES ('vertrag-heiliger-stuhl-freistaat-ostdeutschland', '2023-11-01', '2023-11-01', NULL, 1, 'Vertrag zwischen dem Heiligen Stuhl und dem Freistaat Ostdeutschland', NULL, NULL, NULL, 'Vertrag zwischen dem Heiligen Stuhl und dem Freistaat Ostdeutschland vom 2. Juli 1996 (SächsGVBl. 1997 S. 18)', 'Ausgangsfassung zum Rechtsüberleitungsstichtag 2023-11-01: übernommener Rechtsstand dieses Tages.', '44e27e0a5bd8117c4a90c0a185aad1b951a2667d54f9ed74ef7baaebdc9866b7', 'https://www.revosax.sachsen.de/vorschrift/5487', '2026-09-03', 'revosax/2023-11-01/5487.html', '2026-01-01T00:00:00.000Z', '{"versionId":"2023-11-01","validFrom":"2023-11-01","validTo":null,"isCurrent":true,"title":"Vertrag zwischen dem Heiligen Stuhl und dem Freistaat Ostdeutschland","citation":"Vertrag zwischen dem Heiligen Stuhl und dem Freistaat Ostdeutschland vom 2. Juli 1996 (SächsGVBl. 1997 S. 18)","changeNote":"Ausgangsfassung zum Rechtsüberleitungsstichtag 2023-11-01: übernommener Rechtsstand dieses Tages.","sourceReferences":[{"kind":"revosax-snapshot","label":"Amtliche REVOSax-Fassung 5487.1, gültig ab 1997-04-30","availability":"r2-archived","objectKey":"revosax/2023-11-01/5487.html","url":"https://www.revosax.sachsen.de/vorschrift/5487","retrievedAt":"2026-09-03","sha256":"44e27e0a5bd8117c4a90c0a185aad1b951a2667d54f9ed74ef7baaebdc9866b7","lawId":"5487","sourceValidFrom":"1997-04-30","mediaType":"text/html","sourceRole":"official-snapshot","fsnNumber":"73-8V"}]}', 'Vertrag zwischen dem Heiligen Stuhl und dem Freistaat Ostdeutschland vom 2. Juli 1996 (SächsGVBl. 1997 S. 18)', NULL, 'current', NULL, NULL);
INSERT INTO law_versions (norm_id, version_id, valid_from, valid_to, is_current, title, short_title, abbr, summary, citation, change_note, source_sha256, source_url, source_retrieved_at, source_object_key, updated_at, version_json, full_citation, publication_ref_json, temporal_kind, publication_source, publication_year) VALUES ('vwv-abschlusspruefung-fischwirt-in', '2023-11-01', '2023-11-01', NULL, 1, 'Verwaltungsvorschrift des Regierungspräsidiums Chemnitz zur Durchführung der Abschlussprüfung im Beruf Fischwirt/in', NULL, NULL, NULL, 'Verwaltungsvorschrift des Regierungspräsidiums Chemnitz zur Durchführung der Abschlussprüfung im Beruf Fischwirt/in vom 2. November 2004 (SächsABl. S. 1293)', 'Ausgangsfassung zum Rechtsüberleitungsstichtag 2023-11-01: übernommener Rechtsstand dieses Tages.', 'ce5cef61245f122d0bf7e09adff0e7d06e852a178b1bf3b7d87077790c5a4ad0', 'https://www.revosax.sachsen.de/vorschrift/4995', '2026-09-03', 'revosax/2023-11-01/4995.html', '2026-01-01T00:00:00.000Z', '{"versionId":"2023-11-01","validFrom":"2023-11-01","validTo":null,"isCurrent":true,"title":"Verwaltungsvorschrift des Regierungspräsidiums Chemnitz zur Durchführung der Abschlussprüfung im Beruf Fischwirt/in","citation":"Verwaltungsvorschrift des Regierungspräsidiums Chemnitz zur Durchführung der Abschlussprüfung im Beruf Fischwirt/in vom 2. November 2004 (SächsABl. S. 1293)","changeNote":"Ausgangsfassung zum Rechtsüberleitungsstichtag 2023-11-01: übernommener Rechtsstand dieses Tages.","sourceReferences":[{"kind":"revosax-snapshot","label":"Amtliche REVOSax-Fassung 4995.1, gültig ab 2004-11-02","availability":"r2-archived","objectKey":"revosax/2023-11-01/4995.html","url":"https://www.revosax.sachsen.de/vorschrift/4995","retrievedAt":"2026-09-03","sha256":"ce5cef61245f122d0bf7e09adff0e7d06e852a178b1bf3b7d87077790c5a4ad0","lawId":"4995","sourceValidFrom":"2004-11-02","mediaType":"text/html","sourceRole":"official-snapshot","fsnNumber":"712-V04.7"}]}', 'Verwaltungsvorschrift des Regierungspräsidiums Chemnitz zur Durchführung der Abschlussprüfung im Beruf Fischwirt/in vom 2. November 2004 (SächsABl. S. 1293)', NULL, 'current', NULL, NULL);
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('abschiebe-aussetzungsverordnung', '2024-03-01', 0, 0, 1, '{"type":"section","title":"Geltungsbereich","children":[{"type":"paragraphText","text":"Diese Verordnung gilt für alle Abschiebungen in die folgenden Länder:"},{"type":"item","label":"–","text":"Syrien","level":0,"listId":"states","numberingStyle":"bullet","children":[]},{"type":"item","label":"–","text":"Afghanistan","level":0,"listId":"states","numberingStyle":"bullet","children":[]},{"type":"item","label":"–","text":"Irak","level":0,"listId":"states","numberingStyle":"bullet","children":[]},{"type":"item","label":"–","text":"Somalia","level":0,"listId":"states","numberingStyle":"bullet","children":[]},{"type":"item","label":"–","text":"Eritrea","level":0,"listId":"states","numberingStyle":"bullet","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('abschiebe-aussetzungsverordnung', '2024-03-01', 1, 0, 1, '{"type":"section","title":"Anwendungsbereich","children":[{"type":"paragraphText","text":"Diese Verordnung findet Anwendung auf alle ausreisepflichtigen Personen, die sich im Geltungsbereich des Freistaates befinden und deren Abschiebung in eines der oben genannten Länder bevorsteht."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('abschiebe-aussetzungsverordnung', '2024-03-01', 2, 0, 1, '{"type":"section","title":"Inhalt","children":[{"type":"paragraphText","text":"Die Abschiebung von ausreisepflichtigen Personen in die oben genannten Länder wird für einen Zeitraum von drei Monaten ab dem 01.03.2024 ausgesetzt."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('abschiebe-aussetzungsverordnung', '2024-03-01', 3, 0, 1, '{"type":"section","title":"Begründung","children":[{"type":"paragraphText","text":"Die aktuelle Lage in den oben genannten Ländern ist durch Krieg, Bürgerkriege, Terrorismus und humanitäre Notlagen gekennzeichnet. Eine Abschiebung in diese Länder würde daher eine unzumutbare Härte für die betroffenen Personen darstellen."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('abschiebe-aussetzungsverordnung', '2024-03-01', 4, 0, 1, '{"type":"section","title":"Inkrafttreten","children":[{"type":"paragraphText","text":"Diese Verordnung tritt mit ihrer Verkündung in Kraft."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('aend-ostgemo-4399', '2023-11-01', 0, 0, 1, '{"type":"part","label":"Teil 10","title":"Schlussvorschriften","children":[{"type":"paragraph","label":"§ 73","title":"Änderung anderer Rechtsvorschriften","children":[{"type":"subparagraph","label":"(1)","text":"§ 122 Abs. 4 der Gemeindeordnung für den Freistaat Ostdeutschland (OstGemO) in der Fassung der Bekanntmachung vom 14. Juni 1999 (SächsGVBl. S. 345) wird aufgehoben.","children":[]}]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('dienstanordnung-momentane-terrorgefahr-2024', '2024-10-02', 0, 0, 1, '{"type":"paragraphText","text":"Die Dienstanordnung wurde am 2. Oktober 2024 verkündet."}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('dienstanordnung-momentane-terrorgefahr-2024', '2024-10-02', 1, 0, 1, '{"type":"paragraph","label":"§ 1","title":"Schutz von Mitarbeitern der Staatsregierung","children":[{"type":"paragraphText","text":"Alle Mitarbeiter der Staatsregierung werden dazu angewiesen aufgrund der imminenten Terrorgefahr gegen staatliche Einrichtungen von Zuhause zu arbeiten."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('dienstanordnung-momentane-terrorgefahr-2024', '2024-10-02', 2, 0, 1, '{"type":"paragraph","label":"§ 2","title":"Inkrafttreten, Außerkrafttreten","children":[{"type":"paragraphText","text":"Die Verordnung tritt am Tage der Verkündung in Kraft. Diese Dienstanordnung tritt mit Ablauf des 6. Oktober 2024 außer Kraft. Sie kann jederzeit verlängert werden."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo', '2026-03-23', 0, 0, 1, '{"type":"paragraphText","text":"Der Ostdeutsche Landtag hat am 23. März 2026 das folgende Gesetz beschlossen:"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo', '2026-03-23', 1, 0, 1, '{"type":"article","label":"Artikel 1","title":"Änderung der Gemeindeordnung","children":[{"type":"paragraphText","text":"Die Sächsische Gemeindeordnung in der Fassung der Bekanntmachung vom 9. März 2018 (SächsGVBl. S. 62), die zuletzt durch Art. 5 des Gesetzes vom 28. November 2023 (SächsGVBl. S. 870) geändert worden ist, wird wie folgt geändert:"},{"type":"item","label":"1.","text":"Die Bezeichnung des Gesetzes wird wie folgt gefasst:","level":0,"listId":"zgv5jk90hem3","numberingStyle":"decimal","children":[{"type":"quotedProvision","children":[{"type":"paragraphText","text":",,Gemeindeordnung"},{"type":"paragraphText","text":"für den Ostdeutschen Freistaat"},{"type":"paragraphText","text":"(Ostdeutsche Gemeindeordnung – OstGemO)”"}]}]},{"type":"item","label":"2.","text":"Dem § 90 wird folgender Absatz angefügt:","level":0,"listId":"zgv5jk90hem3","numberingStyle":"decimal","children":[{"type":"quotedProvision","children":[{"type":"paragraphText","text":"“(5) Durch Satzung kann die Gemeinde Unternehmen veräußern, auf welche sie aufgrund Eigentum, finanzieller Beteiligung, Satzung oder sonstiger Bestimmungen, welche die Tätigkeit des Unternehmens regeln, unmittelbar oder mittelbar einen beherrschenden Einfluss ausübt und die"},{"type":"item","label":"1.","text":"Verkehrsleistungen oder Leistungen der Abfall- oder Abwasserentsorgung oder der Energie- oder Wasserversorgung für die Allgemeinheit erbringen,","level":0,"listId":"printed-outline","numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"wesentliche Beiträge zur wirtschaftlichen, verkehrlichen, städtebaulichen oder kulturellen Infrastruktur leisten,","level":0,"listId":"printed-outline","numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"geeignet sind, die Sicherung der Versorgung mit angemessenem Wohnraum zu fördern oder","level":0,"listId":"printed-outline","numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"der allgemeinen Versorgung der Bevölkerung mit Krankenhäusern dienen.","level":0,"listId":"printed-outline","numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"Der Beschluss über eine solche Satzung bedarf der Mehrheit von zwei Dritteln der Gemeinderäte oder eines erfolgreichen Bürgerentscheids nach § 24. Sie tritt nicht vor Ablauf von sechs Monaten nach ihrer Bekanntgabe in Kraft. Als Veräußerung gilt jedes Rechtsgeschäft, welches den beherrschenden Einfluss der Gemeinde beseitigt. Auf kleine Kapitalgesellschaften im Sinne des § 267 Absatz 1 des Handelsgesetzbuchs findet diese Vorschrift keine Anwendung. Gleiches gilt, wenn die Veräußerung bei Entstehen der Beherrschung beabsichtigt war und zeitnah erfolgt.“"}]}]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo', '2026-03-23', 2, 0, 1, '{"type":"article","label":"Artikel 2","title":"Inkrafttreten","children":[{"type":"paragraphText","text":"Dieses Gesetz tritt am Tag nach der Verkündung in Kraft."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('gesetz-zur-einfuehrung-von-hinweisgebermeldestellen', '2026-10-01', 0, 0, 1, '{"type":"paragraphText","text":"Der Ostdeutsche Landtag hat am 2. September 2026 das folgende Gesetz beschlossen:"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('gesetz-zur-einfuehrung-von-hinweisgebermeldestellen', '2026-10-01', 1, 0, 1, '{"type":"article","label":"Artikel 1","title":"Änderung der Gemeindeordnung","children":[{"type":"paragraphText","text":"Nach § 71g der Ostdeutschen Gemeindeordnung in der Fassung der Bekanntmachung vom 9. März 2018 (SächsGVBl. S. 62), zuletzt geändert durch Gesetz vom 20. Juli 2026 (OGVBl. 2026 Nr. 46 S. 2), wird folgender Abschnitt Sechs eingefügt:"},{"type":"quotedProvision","children":[{"type":"paragraphText","text":",,Sechster Abschnitt Hinweisgeberstellen"},{"type":"paragraph","label":"§ 71h","title":"Hinweisgeberstellen","children":[{"type":"subparagraph","label":"(1)","text":"Kommunale Gebietskörperschaften mit mindestens 50 Beschäftigten haben eine interne Meldestellen einzurichten. Kommunale Gebietsverbände können sich zur Erfüllung ihrer Aufgabe nach Satz 1 zusammenschließen.","level":0,"listId":"on3gkoot8q8","numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Tätigkeit der Stellen nach Absatz 1 richtet sich nach § 7 Absatz 2, §§ 8 bis 11, 13 bis 18 Hinweisgeberschutzgesetz; sie nehmen Meldungen bei Verstößen nach § 2 des Hinweisgeberschutzgesetzes entgegen. Sie behandeln, die entgegengenommenen Informationen vertraulich.","level":0,"listId":"on3gkoot8q8","numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(3)","text":"Die nach diesem Gesetz verpflichteten Beschäftigungsgeber sollen die Abgabe von Meldungen in Textform und in mündlicher Form ermöglichen. Soweit technisch und organisatorisch möglich, sollen auch anonyme Meldungen entgegengenommen und bearbeitet werden.”","level":0,"listId":"on3gkoot8q8","numberingStyle":"decimal","children":[]}]}]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('gesetz-zur-einfuehrung-von-hinweisgebermeldestellen', '2026-10-01', 2, 0, 1, '{"type":"article","label":"Artikel 2","title":"Änderung der Landkreisordnung","children":[{"type":"paragraphText","text":"Nach § 60 der Landkreisordnung für den Freistaat Ostdeutschland in der Fassung der Bekanntmachung vom 9. März 2018 (SächsGVBl. S. 99), zuletzt geändert durch Artikel 3 des Gesetzes vom 20. Juli 2026 (OGVBl. 2026 Nr. 46 S. 2), wird folgender Abschnitt 4 eingefügt:"},{"type":"quotedProvision","children":[{"type":"paragraphText","text":",,Vierter Abschnitt Hinweisgeberstellen"},{"type":"paragraph","label":"§ 60a","title":"Hinweisgeberstellen","children":[{"type":"paragraphText","text":"Die Landkreise errichten nach § 71b Absatz 2 und 3 entsprechend Hinweisgeberstellen.”"}]}]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('gesetz-zur-einfuehrung-von-hinweisgebermeldestellen', '2026-10-01', 3, 0, 1, '{"type":"article","label":"Artikel 3","title":"Änderung der Bezirksordnung","children":[{"type":"paragraphText","text":"Nach § 24 der Ostdeutsche Bezirksordnung vom 6. März 2025 (OGVBl. 2025 Nr. 1–7 S. 7–13), zuletzt geändert durch Artikel 8 des Gesetzes vom 20. Juli 2026 (OGVBl. 2026 Nr. 52 S. 2), wird folgender § 24a eingefügt:"},{"type":"quotedProvision","children":[{"type":"paragraph","label":"§ 24a","title":"Hinweisgeberstellen","children":[{"type":"paragraphText","text":"Die Bezirke errichten nach § 71b Absatz 2 und 3 entsprechend Hinweisgeberstellen.”"}]}]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('gesetz-zur-einfuehrung-von-hinweisgebermeldestellen', '2026-10-01', 4, 0, 1, '{"type":"article","label":"Artikel 4","title":"Inkrafttreten","children":[{"type":"paragraphText","text":"Dieses Gesetz tritt am ersten Tag des ersten Monats nach Verkündung in Kraft."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('interreg-ostdeutschland-tschechien-2021-2027', '2023-11-01', 0, 0, 1, '{"type":"section","title":"Redaktioneller Hinweis auf Änderungsbekanntmachung","children":[{"type":"paragraphText","text":"Beachte auch die Bekanntmachung vom 6. Februar 2025 (SächsABl. S. 275)."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 0, 0, 1, '{"type":"paragraphText","text":"Die Freie und Hansestadt Hamburg, vertreten durch den Senat, das Land Mecklenburg-Vorpommern, vertreten durch die Ministerpräsidentin, das Land Niedersachsen, vertreten durch den Ministerpräsidenten, und das Land Schleswig-Holstein, vertreten durch den Ministerpräsidenten, - zusammen in diesem Staatsvertrag \"die Länder\" genannt - schließen vorbehaltlich der Zustimmung ihrer verfassungsmäßig berufenen Organe den nachstehenden Staatsvertrag:"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 1, 0, 1, '{"type":"paragraph","label":"§ 1","title":"Aufgabe und Rechtsform","children":[{"type":"subparagraph","label":"(1)","text":"Der Norddeutsche Rundfunk (NDR) ist eine gemeinnützige, rechtsfähige Anstalt des öffentlichen Rechts zur Herstellung und Verbreitung von Rundfunkprogrammen und Telemedien in der Freien und Hansestadt Hamburg und den Ländern Mecklenburg-Vorpommern, Niedersachsen und Schleswig-Holstein (Sendegebiet).","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR hat das Recht der Selbstverwaltung. Er gibt sich eine Satzung.","children":[]},{"type":"subparagraph","label":"(3)","text":"Ein Insolvenzverfahren über das Vermögen des NDR findet nicht statt.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 2, 0, 1, '{"type":"paragraph","label":"§ 2","title":"Sitz und regionale Gliederung","children":[{"type":"subparagraph","label":"(1)","text":"Sitz des NDR ist Hamburg.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR unterhält Funkhäuser in Hamburg, Hannover, Kiel und Schwerin (Landesfunkhäuser) sowie Regionalstudios in Mecklenburg-Vorpommern, Niedersachsen und Schleswig-Holstein. Die Regionalstudios sind dem Funkhaus des Landes zugeordnet, in dem sie betrieben werden.","children":[]},{"type":"subparagraph","label":"(3)","text":"Einzelne Verwaltungs-, Produktions- und Programmeinrichtungen sowie redaktionelle Schwerpunktbildungen sollen in allen Ländern vorgesehen werden. Wirtschaftlichkeit und Programmverträglichkeit sind dabei angemessen zu berücksichtigen; dabei sind unternehmerisch sinnvolle Entscheidungen zu treffen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 3, 0, 1, '{"type":"paragraph","label":"§ 3","title":"Landesprogramme","children":[{"type":"subparagraph","label":"(1)","text":"Landesprogramme sind getrennte Programme der Landesfunkhäuser, die für die jeweiligen Länder bestimmt sind. Als Landesprogramme gestalten die Landesfunkhäuser jeweils ein ganztägiges Hörfunkprogramm und ein Regionalprogramm im Fernsehen außerhalb der für die Gemeinschaftsprogramme vorgesehenen Zeiten; Umfang und Struktur dieser Programme müssen den inhaltlichen Anforderungen des Absatzes 3 entsprechen. Für regionale Verbreitungsgebiete kann das jeweilige Landesfunkhaus innerhalb eines Landesprogramms regionale Sendungen verbreiten. Mit Zustimmung des Rundfunkrats, des Verwaltungsrats und des Intendanten oder der Intendantin kann das jeweilige Landesfunkhaus innerhalb eines gemeinschaftlichen Hörfunkprogramms ein weiteres Landesprogramm senden (Landesfenster).","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Landesfunkhäuser gestalten die Landesprogramme jeweils in eigener Verantwortung; der Direktor oder die Direktorin des jeweiligen Landesfunkhauses ist für die Landesprogramme verantwortlich. Der Intendant oder die Intendantin bleibt für die Einhaltung der Programmanforderungen (§§ 5, 7 bis 10) verantwortlich. Die Einstellung und Entlassung von Mitarbeitenden des Landesfunkhauses erfolgt unbeschadet der Gesamtverantwortung des Intendanten oder der Intendantin grundsätzlich in eigener Zuständigkeit. Bei Angestellten in leitender Funktion sowie bei Programmmitarbeitenden erfolgt die Einstellung und Entlassung auf Vorschlag des Intendanten oder der Intendantin mit Zustimmung des Direktors oder der Direktorin; entsprechendes gilt für Mitarbeitende des Landesfunkhauses, die den zentralen Fachdirektionen unterstellt sind.","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Landesprogramme der Landesfunkhäuser sollen das öffentliche Geschehen, die politischen Ereignisse sowie das kulturelle und soziale Leben insbesondere in dem jeweiligen Land darstellen.","children":[]},{"type":"subparagraph","label":"(4)","text":"Die Landesfunkhäuser können die gemeinsame Gestaltung von Teilen der Landesprogramme vereinbaren. Soweit dies nicht nur für einzelne Sendungen erfolgen soll, ist dafür die Zustimmung des Rundfunkrats erforderlich.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 4, 0, 1, '{"type":"paragraph","label":"§ 4","title":"Freiheit und öffentliche Verantwortung des Rundfunks","children":[{"type":"paragraphText","text":"Der NDR veranstaltet und verbreitet Rundfunk als Medium und Faktor des Prozesses freier, individueller und öffentlicher Meinungsbildung und als Sache der Allgemeinheit. Die im Sendegebiet bedeutsamen politischen, weltanschaulichen und gesellschaftlichen Kräfte und Gruppen tragen dazu bei, dass der NDR seine Aufgaben eigenverantwortlich im Rahmen des geltenden Rechts und auf der Grundlage der verfassungsrechtlich garantierten Rundfunkfreiheit erfüllt."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 5, 0, 1, '{"type":"paragraph","label":"§ 5","title":"Angebotsauftrag","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR hat den Rundfunkteilnehmern und Rundfunkteilnehmerinnen einen objektiven und umfassenden Überblick über das internationale, europäische, nationale und länderbezogene Geschehen in allen wesentlichen Lebensbereichen zu geben. Seine Angebote haben der Information, Bildung, Beratung und Unterhaltung zu dienen. Er hat Beiträge insbesondere zur Kultur anzubieten und ist berechtigt, sich an Filmförderungen zu beteiligen. Er kann auch Spartenprogramme veranstalten.","children":[]},{"type":"subparagraph","label":"(2)","text":"Norddeutschland und die Vielfalt seiner Regionen, ihre Kultur sowie ihre Regional- und Minderheitensprachen sind in den Angeboten des NDR regelmäßig und angemessen zu berücksichtigen. Der NDR soll zu diesem Zweck und zur Erhaltung kultureller Identität sein Angebot grundsätzlich in den vier Ländern seines Sendegebiets herstellen.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der NDR erlässt Richtlinien zur näheren Ausgestaltung seines Angebotsauftrags. Die Richtlinien sind in geeigneter Art und Weise zu veröffentlichen. Der NDR veröffentlicht alle zwei Jahre einen Bericht über die Erfüllung seines Angebotsauftrags, über die Qualität und Quantität seiner Angebote sowie die geplanten Schwerpunkte der jeweils anstehenden programmlichen Leistungen.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der NDR ist mit der Erbringung von Dienstleistungen von allgemeinem wirtschaftlichem Interesse im Sinne des Artikels 106 Absatz 2 des Vertrages über die Arbeitsweise der Europäischen Union (ABl. EU Nr. C 202 S. 47) auch betraut, soweit er zur Erfüllung seines Auftrags gemäß Absatz 1 bei der Herstellung und Verbreitung von Angeboten im Sinne des § 6 Absatz 1 mit anderen öffentlich-rechtlichen Rundfunkanstalten zusammenarbeitet. Die Betrauung gilt insbesondere für die Bereiche Produktion, Produktionsstandards, Programmrechteerwerb, Programmaustausch, Verbreitung und Weiterverbreitung von Angeboten, Beschaffungswesen, Sendernetzbetrieb, informationstechnische und sonstige Infrastrukturen, Vereinheitlichung von Geschäftsprozessen, Beitragsservice und allgemeine Verwaltung. Von der Betrauung nicht umfasst sind kommerzielle Tätigkeiten. Kommerzielle Tätigkeiten sind Betätigungen, bei denen Leistungen auch für Dritte im Wettbewerb angeboten werden, insbesondere Werbung und Sponsoring, Verwertungsaktivitäten, Merchandising, Produktion für Dritte und die Vermietung von Senderstandorten an Dritte.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 6, 0, 1, '{"type":"paragraph","label":"§ 6","title":"Wahrnehmung des Angebotsauftrags, Sendekapazitäten","children":[{"type":"subparagraph","label":"(1)","text":"Angebote des NDR sind Rundfunkprogramme (Hörfunk- und Fernsehprogramme) und Telemedienangebote. Die ihm bisher eingeräumten Sendekapazitäten (Frequenzen und Kanäle) stehen ihm weiterhin zur Verfügung. Der NDR kann bei Fortfall einzelner ihm zustehender Sendekapazitäten gleichwertigen Ersatz verlangen. Er darf nicht ohne die Zustimmung des oder der jeweils betroffenen Länder die Nutzung eigener Sendekapazitäten anderen Rundfunkveranstaltern überlassen oder zu deren Gunsten auf sie verzichten.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR veranstaltet bis zu drei Hörfunkprogramme, die terrestrisch in digitaler Technik verbreitet werden. Die Programme haben die folgenden Schwerpunkte:","children":[]},{"type":"item","label":"1.","text":"Ein ergänzendes Musikprogramm sowie musikjournalistische Beiträge mit Berücksichtigung der norddeutschen Musikszene,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Liveübertragungen von Veranstaltungen, Seewetterberichte sowie Sendungen für Menschen mit Migrationshintergrund,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"ein ergänzendes Musikprogramm mit dem Schwerpunkt Schlager und ähnliche deutschsprachige Produktionen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"Die Schwerpunkte aus den Nummern 1 und 2 können in einem gemeinsamen Programm bei Aufgabe eines Programms zusammengelegt werden. Die Programme nach den Nummern 1 bis 3 sind werbefrei. Der NDR ist berechtigt, in Wahrnehmung seiner Angebote nach § 5 dieses Staatsvertrages und unter den Voraussetzungen des § 29 Absatz 2 Satz 3 des Medienstaatsvertrages den Schwerpunkt nach Absatz 2 Satz 1 Nummer 3 nach Zustimmung des Rundfunkrats gegen einen anderen Schwerpunkt oder auch gegen ein Kooperationsprogramm auszutauschen, das terrestrisch in digitaler Technik verbreitet wird. Für diese Entscheidung ist dem Rundfunkrat ein Programmkonzept vorzulegen. Der NDR informiert die nach § 39 Absatz 1 aufsichtsführende Regierung rechtzeitig über einen geplanten Austausch und das Vorliegen der Voraussetzungen für einen Austausch nach diesem Absatz und veröffentlicht mindestens ein halbes Jahr vor dem Start des neuen Programms Informationen zum geplanten Programmschwerpunkt auf den Internetseiten des NDR."},{"type":"subparagraph","label":"(3)","text":"Der NDR kann bei der Wahrnehmung seiner Aufgaben in sendetechnischer, programmlicher und finanzieller Hinsicht ebenso wie die anderen Rundfunkunternehmen im Geltungsbereich des Grundgesetzes alle für Rundfunkunternehmen zur Verfügung stehenden Möglichkeiten nutzen. Eingeräumte Übertragungskapazitäten sind, soweit möglich, nach den Grundsätzen der Wirtschaftlichkeit und Sparsamkeit einzusetzen. Dabei sollen Doppel- und Mehrfachnutzungen vermieden werden.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der NDR hat sicherzustellen, dass sein Sendegebiet gleichwertig versorgt wird. Die Sendekapazitäten, die der NDR für die Grundversorgung mit Rundfunk im Umfang der bestehenden Programme benötigt, sind im Rahmen der technischen Möglichkeiten bereitzustellen. Die Zuweisung von Satellitenkanälen für weitere Hörfunk- und Fernsehprogramme erfolgt auf der Grundlage einer Vereinbarung der Länder; die Zuweisung von terrestrischen Sendekapazitäten für weitere Hörfunk- und Fernsehprogramme erfolgt nach Maßgabe der jeweiligen landesrechtlichen Bestimmungen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 7, 0, 1, '{"type":"paragraph","label":"§ 7","title":"Angebotsgrundsätze","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR ist in seinen Angeboten an die verfassungsmäßige Ordnung gebunden. Er trägt zur Verwirklichung der freiheitlichen demokratischen Grundordnung bei.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR hat in seinen Angeboten die Würde des Menschen zu achten und zu schützen. Er soll dazu beitragen, die Achtung vor Leben, Freiheit und körperlicher Unversehrtheit, vor Glauben und Meinung anderer zu stärken und sich für die Erhaltung von Natur und Umwelt sowie die Grundsätze der Nachhaltigkeit einzusetzen. Das Angebot des NDR soll die Zusammengehörigkeit innerhalb Deutschlands und Europas sowie die internationale Verständigung fördern, für die Friedenssicherung und den Minderheitenschutz eintreten, die Gleichstellung von Frau und Mann unterstützen und zur sozialen Gerechtigkeit beitragen. Die sittlichen und religiösen Überzeugungen der Bevölkerung sind zu achten.","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Vorschriften der allgemeinen Gesetze und die gesetzlichen Bestimmungen zum Schutze der Jugend und des Rechts der persönlichen Ehre sind einzuhalten.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 8, 0, 1, '{"type":"paragraph","label":"§ 8","title":"Gestaltung des Angebots","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR ist in seinen Angeboten zur Wahrheit verpflichtet. Er hat sicherzustellen, dass","children":[]},{"type":"item","label":"1.","text":"die bedeutsamen politischen, weltanschaulichen und gesellschaftlichen Kräfte und Gruppen aus dem Sendegebiet in den Angeboten angemessen zu Wort kommen können,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"das Angebot nicht einseitig einer Partei oder Gruppe, einer Interessengemeinschaft, einem Bekenntnis oder einer Weltanschauung dient und","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"in seiner Berichterstattung die Auffassungen der wesentlich betroffenen Personen, Gruppen oder Stellen angemessen und fair berücksichtigt werden. Wertende und analysierende Einzelbeiträge haben dem Gebot journalistischer Fairness und in ihrer Gesamtheit der Vielfalt der Meinungen zu entsprechen. Ziel aller Informationssendungen ist es, sachlich und umfassend zu unterrichten und damit zur selbständigen Urteilsbildung der Bürger und Bürgerinnen beizutragen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(2)","text":"Berichterstattung und Informationssendungen haben den anerkannten journalistischen Grundsätzen, auch beim Einsatz virtueller Elemente, zu entsprechen. Sie müssen unabhängig und sachlich sein. Nachrichten sind vor ihrer Verbreitung mit der nach den Umständen gebotenen Sorgfalt auf Wahrheit und Herkunft zu prüfen. Kommentare sind von der Berichterstattung deutlich zu trennen und unter Nennung des Verfassers oder der Verfasserin als solche zu kennzeichnen.","children":[]},{"type":"subparagraph","label":"(3)","text":"Soweit der NDR Meinungsumfragen wiedergibt, ist ausdrücklich anzugeben, ob sie repräsentativ sind.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 9, 0, 1, '{"type":"paragraph","label":"§ 9","title":"Kurzberichterstattung","children":[{"type":"paragraphText","text":"§ 14 des Medienstaatsvertrages findet entsprechend Anwendung."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 10, 0, 1, '{"type":"paragraph","label":"§ 10","title":"Unzulässige Angebote, Jugendschutz","children":[{"type":"paragraphText","text":"Die für den öffentlich-rechtlichen Rundfunk geltenden Bestimmungen des Jugendmedienschutz-Staatsvertrages finden Anwendung."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 11, 0, 1, '{"type":"paragraph","label":"§ 11","title":"Zusammenarbeit, Druckwerke","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR kann im Rahmen seiner Aufgaben Vereinbarungen mit anderen Rundfunkveranstaltern zum Zweck gemeinsamer Angebotsgestaltung oder der gemeinsamen Durchführung bestimmter Aufgaben abschließen. Er kann sich an internationalen, insbesondere europäischen Angeboten beteiligen; diese Beteiligung bedarf einer Vereinbarung der Länder.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR kann zur Veranstaltung und Verbreitung von Angeboten mit Dritten zusammenarbeiten und sich zu diesem Zweck an Unternehmen beteiligen (§ 37). Die Bestimmungen der §§ 7 bis 10 sowie des § 3 Absatz 3 sind dabei besonders zu beachten. Insbesondere ist sicherzustellen, dass die Mitwirkung des NDR jeweils in einem abgrenzbaren und ihm zurechenbaren Anteil an dem jeweiligen Gemeinschaftsangebot besteht.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der NDR kann zur Erfüllung seiner Aufgaben angebotsbegleitend Druckwerke mit angebotsbezogenem Inhalt anbieten.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 12, 0, 1, '{"type":"paragraph","label":"§ 12","title":"Verlautbarungsrecht","children":[{"type":"paragraphText","text":"Der NDR hat der Bundesregierung und den Regierungen der Länder für amtliche Verlautbarungen angemessene Sendezeit unverzüglich und unentgeltlich einzuräumen. Für Inhalt und Gestaltung der Sendungen ist diejenige Regierung verantwortlich, der die Sendezeit zugebilligt worden ist."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 13, 0, 1, '{"type":"paragraph","label":"§ 13","title":"Gegendarstellung","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR ist verpflichtet, eine Gegendarstellung der Person, Gruppe oder Stelle zu verbreiten, die durch eine in einem Angebot aufgestellte Tatsachenbehauptung betroffen ist. Die Pflicht zur Verbreitung einer Gegendarstellung besteht nicht, wenn die betroffene Person, Gruppe oder Stelle kein berechtigtes Interesse an der Verbreitung hat oder wenn die Gegendarstellung ihrem Umfang nach nicht angemessen ist. Überschreitet die Gegendarstellung nicht den Umfang des beanstandeten Angebotsteils, gilt sie als angemessen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Gegendarstellung muss unverzüglich, bei beanstandeten Sendungen spätestens innerhalb von zwei Monaten beziehungsweise drei Monaten nach der erstmaligen Einstellung des Telemediums, schriftlich verlangt werden und von dem oder der Betroffenen oder seinem oder ihrem gesetzlichen Vertreter oder Vertreterin unterzeichnet sein. Die Gegendarstellung muss das beanstandete Angebot und die Tatsachenbehauptung bezeichnen, sich auf tatsächliche Angaben beschränken und darf keinen strafbaren Inhalt haben.","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Gegendarstellung muss unverzüglich innerhalb desselben Angebots verbreitet werden, in welchem die beanstandete Tatsachenbehauptung erfolgt ist. Die Verbreitung erfolgt ohne Einschaltungen und Weglassungen. Eine Erwiderung auf die verbreitete Gegendarstellung muss sich auf tatsächliche Angaben beschränken.","children":[]},{"type":"subparagraph","label":"(4)","text":"Im Fernsehen und Hörfunk muss die Gegendarstellung innerhalb desselben Programms und desselben Sendungsangebots wie die beanstandete Tatsachenbehauptung sowie zur gleichen Tageszeit verbreitet werden. Ist dies nicht möglich, ist die Gegendarstellung in einer vergleichbaren Sendung sowie zu einer angemessenen Sendezeit zu verbreiten. Ist dies ebenfalls nicht möglich, muss die Gegendarstellung in sonstiger angemessener Art und Weise erfolgen.","children":[]},{"type":"subparagraph","label":"(5)","text":"In Telemedienangeboten muss die Gegendarstellung in dem gleichen Telemedium aufgenommen werden. Die Gegendarstellung ist in gleicher Aufmachung wie die Tatsachenbehauptung anzubieten. Die Gegendarstellung ist so lange wie die Tatsachenbehauptung in unmittelbarer Verknüpfung mit ihr anzubieten. Wird die Tatsachenbehauptung nicht mehr angeboten oder endet das Angebot vor Aufnahme der Gegendarstellung, so ist die Gegendarstellung an vergleichbarer Stelle so lange anzubieten, wie die ursprünglich angebotene Tatsachenbehauptung.","children":[]},{"type":"subparagraph","label":"(6)","text":"Die Gegendarstellung wird unentgeltlich verbreitet. Dies gilt nicht, wenn sich die Gegendarstellung gegen eine Tatsachenbehauptung richtet, die in einer Werbesendung verbreitet worden ist.","children":[]},{"type":"subparagraph","label":"(7)","text":"Verweigert der NDR die Verbreitung einer Gegendarstellung, entscheiden auf Antrag des oder der Betroffenen die ordentlichen Gerichte. Die Vorschriften der Zivilprozessordnung über das Verfahren auf Erlass einer einstweiligen Verfügung gelten entsprechend. Eine Gefährdung des Anspruchs braucht nicht glaubhaft gemacht zu werden. Ein Verfahren in der Hauptsache findet nicht statt.","children":[]},{"type":"subparagraph","label":"(8)","text":"Die Absätze 1 bis 7 gelten nicht für wahrheitsgetreue Berichte über öffentliche Sitzungen des Europäischen Parlaments, der gesetzgebenden Organe des Bundes, der Länder und der Vertretungen der kommunalen Gebietskörperschaften, der Gerichte sowie für Sendungen nach den §§ 12 und 16. Zu einer Gegendarstellung kann eine Gegendarstellung nicht verlangt werden.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 14, 0, 1, '{"type":"paragraph","label":"§ 14","title":"Eingaberecht","children":[{"type":"subparagraph","label":"(1)","text":"Jeder oder jede hat das Recht, sich mit Eingaben und Anregungen zu den Angeboten an den Rundfunkrat sowie an den Intendanten oder die Intendantin oder - bezogen auf die Angebote der jeweiligen Landesfunkhäuser - an den jeweiligen Landesrundfunkrat sowie an den jeweiligen Landesfunkhausdirektor oder die jeweilige Landesfunkhausdirektorin zu wenden.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR stellt sicher, dass Beschwerden zu den Angeboten, in denen die Verletzung von Angebotsgrundsätzen behauptet wird, innerhalb angemessener Frist schriftlich beschieden werden. Wird die Beschwerde über ein Angebot in Textform eingelegt, so genügt auch für deren Bescheidung die Textform.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 15, 0, 1, '{"type":"paragraph","label":"§ 15","title":"Beweissicherung","children":[{"type":"subparagraph","label":"(1)","text":"Die Angebote des NDR sind in Ton, Bild und Text vollständig aufzuzeichnen beziehungsweise zu speichern sowie aufzubewahren. Bei Sendungen, die unter Verwendung einer Aufzeichnung oder eines audiovisuellen Beitrags ausgestrahlt werden, ist die Aufzeichnung oder der audiovisuelle Beitrag aufzubewahren, bei Telemedienangeboten die einzelnen Telemedien. Nach Ablauf von drei Monaten seit dem Tag der Verbreitung können Aufzeichnungen, audiovisuelle Beiträge und Telemedien gelöscht beziehungsweise vernichtet werden, soweit keine Beanstandungen mitgeteilt worden sind. Bei einer Beanstandung kann die Aufzeichnung, der audiovisuelle Beitrag oder das Telemedium erst gelöscht beziehungsweise vernichtet werden, wenn die Beanstandung durch rechtskräftige gerichtliche Entscheidung, durch gerichtlichen Vergleich oder auf andere Weise erledigt ist.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Rundfunkrat kann mit der Zustimmung von zwei Dritteln seiner anwesenden Mitglieder Ausnahmen von der Aufzeichnungs- beziehungsweise Speicherungs- und Aufbewahrungspflicht nach Absatz 1 zulassen.","children":[]},{"type":"subparagraph","label":"(3)","text":"Wer schriftlich glaubhaft macht, durch ein Angebot in seinen oder ihren Rechten berührt zu sein, kann Einsicht in die betreffenden Aufzeichnungen, audiovisuellen Beiträge und Telemedien verlangen. Dieser Anspruch ist ausgeschlossen, wenn er nicht innerhalb von drei Monaten seit dem Tag der Verbreitung des beanstandeten Angebotsteils geltend gemacht worden ist. Über das Verlangen ist unverzüglich schriftlich zu entscheiden. Auf Verlangen sind Antragstellenden auf deren Kosten Vervielfältigungen oder Abschriften des beanstandeten Angebotsteils zu übersenden.","children":[]},{"type":"subparagraph","label":"(4)","text":"Jedes Mitglied des Rundfunkrats oder seiner Ausschüsse hat das Recht, die Aufbewahrung einer Aufzeichnung, eines audiovisuellen Beitrags oder eines Telemediums über die Frist des Absatzes 1 hinaus bis zur nächsten Rundfunkratssitzung zu verlangen. Der Rundfunkrat oder einer seiner Ausschüsse entscheidet auf Antrag eines Mitglieds über die Verlängerung der Aufbewahrungsfrist.","children":[]},{"type":"subparagraph","label":"(5)","text":"Der NDR hat auf Verlangen Namen und Dienstanschrift des Intendanten oder der Intendantin und in den Fällen des Absatzes 3 Name und Dienstanschrift des oder der für den beanstandeten Angebotsteil Verantwortlichen bekannt zu geben.","children":[]},{"type":"subparagraph","label":"(6)","text":"Im Rahmen der Rechtsaufsicht nach § 39 kann jedes der Länder Einsicht in Aufzeichnungen, audiovisuelle Beiträge und Telemedien nach Absatz 1 verlangen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 16, 0, 1, '{"type":"paragraph","label":"§ 16","title":"Besondere Sendezeiten","children":[{"type":"subparagraph","label":"(1)","text":"Den Parteien und Vereinigungen, für die in den Ländern ein Wahlvorschlag zu den Landesparlamenten, zum Deutschen Bundestag oder zum Europäischen Parlament zugelassen worden ist, sind angemessene Sendezeiten zur Vorbereitung von Wahlen einzuräumen, soweit sie mit einer Landesliste oder in mindestens der Hälfte der Wahlkreise eines Landes mit eigenen Wahlvorschlägen an der Wahl teilnehmen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Den Kirchen und den anderen über das gesamte Sendegebiet verbreiteten Religionsgemeinschaften des öffentlichen Rechts sind auf Wunsch angemessene Sendezeiten für die Übertragung gottesdienstlicher Handlungen und Feierlichkeiten sowie sonstiger religiöser Sendungen, auch solcher über Fragen ihrer öffentlichen Verantwortung, zu gewähren. Für die Jüdischen Gemeinden gilt Entsprechendes. Dem NDR steht es frei, vergleichbare Bedarfe anderer Religionsgemeinschaften entsprechend ihrer Bedeutung und ihrem Verbreitungsgrad in der Bevölkerung bei seiner Programmgestaltung zu berücksichtigen , sofern sich die jeweilige Religionsgemeinschaft nicht gegen die Grundwerte des Grundgesetzes richtet .","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Vorschriften der allgemeinen Gesetze und die gesetzlichen Bestimmungen zum Schutze der Jugend und des Rechts der persönlichen Ehre sind einzuhalten.","children":[]},{"type":"subparagraph","label":"(4)","text":"Für Inhalt und Gestaltung der Sendungen ist derjenige oder diejenige verantwortlich, dem oder der die Sendezeit zugebilligt worden ist.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 17, 0, 1, '{"type":"paragraph","label":"§ 17","title":"Organe","children":[{"type":"subparagraph","label":"(1)","text":"Organe des NDR sind:","children":[]},{"type":"item","label":"1.","text":"der Rundfunkrat,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"der Verwaltungsrat,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"der Intendant oder die Intendantin,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"die Landesrundfunkräte, bezogen auf die Landesprogramme.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Mitgliedschaft im Rundfunkrat und die Mitgliedschaft im Verwaltungsrat schließen sich gegenseitig aus.","children":[]},{"type":"subparagraph","label":"(3)","text":"Angestellte oder Mitarbeitende des NDR können nicht Mitglied des Rundfunkrats oder des Verwaltungsrats sein.","children":[]},{"type":"subparagraph","label":"(4)","text":"Mitglieder der gesetzgebenden und beschließenden Organe der Europäischen Union, des Europarates, des Bundes oder eines der Länder können dem Rundfunkrat mit Ausnahme seiner Mitglieder nach § 18 Absatz 1 Satz 2 Nummer 1 und dem Verwaltungsrat nicht angehören.","children":[]},{"type":"subparagraph","label":"(5)","text":"Mitglied des Rundfunkrats und des Verwaltungsrats kann nicht sein, wer seinen Hauptwohnsitz außerhalb des Sendegebiets des NDR hat, wer Inhaber oder Inhaberin, Gesellschafter oder Gesellschafterin eines privaten Rundfunkveranstalters ist, wer Organ einer Landesmedienanstalt oder eines privaten Rundfunkveranstalters ist oder einem Organ angehört, in einem Arbeits- oder Dienstverhältnis zu diesen steht oder für diese als arbeitnehmerähnliche Person im Sinne des § 12a des Tarifvertragsgesetzes tätig ist.","children":[]},{"type":"subparagraph","label":"(6)","text":"Kein Mitglied des Rundfunkrats oder des Verwaltungsrats darf als Inhaber oder Inhaberin, Gesellschafter oder Gesellschafterin, Vorstandsmitglied, Angestellter oder Angestellte oder Vertreter oder Vertreterin eines Unternehmens unmittelbar oder mittelbar mit dem NDR für eigene oder fremde Rechnung Rechtsgeschäfte abschließen. Dies gilt auch für Unternehmen, die gemeinnütziger Art sind.","children":[]},{"type":"subparagraph","label":"(7)","text":"Dem Rundfunkrat und dem Verwaltungsrat darf nur angehören, wer zu den Landesparlamenten wählbar ist. Das von dem Niedersächsischen Integrationsrat (NIR) gemäß § 18 Absatz 1 Satz 2 Nummer 15 entsandte Mitglied darf Ausländer oder Ausländerin sein.","children":[]},{"type":"subparagraph","label":"(8)","text":"Die Mitglieder des Rundfunkrats und des Verwaltungsrats sind ehrenamtlich tätig. Die Vorschriften des § 20 Absatz 4 und des § 25 Absatz 4 bleiben unberührt.","children":[]},{"type":"subparagraph","label":"(9)","text":"Die Mitgliedschaft einer Person in den Gremien des NDR ist auf insgesamt drei Amtsperioden und in einem Gremium auf zwei Amtsperioden begrenzt. Die seit dem Jahr 2013 abgeleisteten Amtsperioden sind in die Berechnung mit einzubeziehen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 18, 0, 1, '{"type":"paragraph","label":"§ 18","title":"Zusammensetzung des Rundfunkrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Rundfunkrat besteht aus höchstens 58 Mitgliedern. Von ihnen entsenden","children":[]},{"type":"item","label":"1.","text":"höchstens elf Mitglieder die in den Landesparlamenten der Länder mit Fraktionen vertretenen Parteien, davon","level":0,"numberingStyle":"decimal","children":[{"type":"item","label":"a)","text":"neun Mitglieder die in den gesetzgebenden Körperschaften der Länder vertretenen Parteien, davon drei aus Niedersachsen und je zwei aus Hamburg, Mecklenburg-Vorpommern und Schleswig-Holstein, entsprechend ihrem Stärkeverhältnis nach dem Höchstzahlverfahren d''Hondt, sowie","level":1,"numberingStyle":"lower-latin","children":[]},{"type":"item","label":"b)","text":"je ein Mitglied die nach der Zahl ihrer Wählerinnen und Wähler in den jeweiligen Ländern stärkste und zweitstärkste Fraktion der in den Landesparlamenten vertretenen Parteien, auf die nach dem Höchstzahlverfahren d''Hondt kein Sitz im Rundfunkrat entfallen ist; maßgebend sind die Ergebnisse der Wahlen zu den Landesparlamenten vor dem jeweils ersten Zusammentritt des Rundfunkrats,","level":1,"numberingStyle":"lower-latin","children":[]}]},{"type":"item","label":"2.","text":"zwei Mitglieder die evangelischen Kirchen und zwei Mitglieder die römisch-katholische Kirche, davon je ein Mitglied aus Hamburg, Mecklenburg-Vorpommern, Niedersachsen und Schleswig-Holstein,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"ein Mitglied die Jüdische Gemeinde in Hamburg,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"vier Mitglieder der Deutsche Gewerkschaftsbund, ein Mitglied die Vereinte Dienstleistungsgewerkschaft (Ver.di), ein Mitglied der Deutsche Beamtenbund, davon drei aus Niedersachsen und je eines aus Hamburg, Mecklenburg-Vorpommern und Schleswig-Holstein,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5.","text":"drei Mitglieder die Arbeitgeberverbände, davon zwei aus dem Bereich der Industrie und eines aus dem Bereich des Handels, ein Mitglied die Handwerksverbände, ein Mitglied die Verbände der Freien Berufe, und zwar zwei aus Niedersachsen und je eines aus Hamburg, Mecklenburg-Vorpommern und Schleswig-Holstein, dabei im Falle Hamburgs für Industrie, Handel und Handwerk an Stelle der Landesvereinigungen jeweils die Kammer,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"6.","text":"ein Mitglied der Bauernverband aus Mecklenburg-Vorpommern,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"7.","text":"drei Mitglieder die Landesfrauenräte und Landesarbeitsgemeinschaften, -verbände und -initiativen der Frauen, und zwar je eines aus Hamburg, Niedersachsen und Schleswig-Holstein,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"8.","text":"je ein Mitglied der Landessportbund aus Niedersachsen und der Landessportbund aus Mecklenburg-Vorpommern,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"9.","text":"ein Mitglied die Arbeitsgemeinschaft der kommunalen Spitzenverbände Niedersachsens,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"10.","text":"ein Mitglied der Haus- und Grundeigentümerverein e. V. aus Mecklenburg-Vorpommern, ein Mitglied der Deutsche Mieterbund, Landesverband Schleswig-Holstein e. V., sowie ein Mitglied die in Hamburg mit der Verbraucherberatung betraute Institution,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"11.","text":"ein Mitglied die Landesarbeitsgemeinschaft der Freien Wohlfahrtspflege in Niedersachsen, ein Mitglied die Arbeiterwohlfahrt, Landesverband Schleswig-Holstein e. V., ein Mitglied das Diakonische Werk aus Hamburg und ein Mitglied der Deutsche Caritasverband e. V. aus Mecklenburg-Vorpommern,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"12.","text":"ein Mitglied der Deutsche Kinderschutzbund e. V. aus Schleswig-Holstein, ein Mitglied der Landesjugendring aus Niedersachsen, ein Mitglied der Landeselternrat aus Niedersachsen, ein Mitglied die Erwachsenenbildungsorganisationen aus Niedersachsen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"13.","text":"ein Mitglied Robin Wood e. V. aus Hamburg, ein Mitglied der BUND aus Niedersachsen, ein Mitglied der Landesnaturschutzverband Schleswig-Holstein e. V. und ein Mitglied der Landesverband Bürgerinitiativen Umweltschutz aus Niedersachsen, ein Mitglied der Heimatverband aus Mecklenburg-Vorpommern,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"14.","text":"ein Mitglied die Arbeitsgruppe Bildende Kunst aus Hamburg, ein Mitglied der Verband Deutscher Schriftstellerinnen und Schriftsteller (VS) in Niedersachsen und ein Mitglied der Landesmusikrat Schleswig-Holstein e. V.,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"15.","text":"ein Mitglied der SoVD-Landesverband Niedersachsen e. V., ein Mitglied der Niedersächsische Integrationsrat (NIR) und ein Mitglied der Landesseniorenrat Niedersachsen e. V.,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"16.","text":"ein Mitglied der Verband der Opfer des Stalinismus aus Mecklenburg-Vorpommern und ein Mitglied die Aktion Sühnezeichen aus Niedersachsen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(2)","text":"Bei der Entsendung der Mitglieder sind Frauen und Männer gleichermaßen zu berücksichtigen. Sofern zu Beginn der Amtsperiode ein neues Mitglied entsandt wird, muss einem männlichen Mitglied eine Frau und einem weiblichen Mitglied ein Mann nachfolgen. Wird während der laufenden Amtsperiode ein neues Mitglied entsandt, findet der Wechsel nach Satz 2 nicht statt. Sofern einer Organisation oder einer Gruppe zwei oder mehr Entsenderechte zustehen, sind mindestens je eine Frau und ein Mann zu entsenden. Kann eine Organisation oder Gruppe aufgrund ihrer Zusammensetzung die Anforderungen der Sätze 2 bis 4 nicht erfüllen, ist dies gegenüber dem Vorsitz des Rundfunkrats bei der Benennung des Mitglieds schriftlich zu begründen; der Vorsitz des Rundfunkrats entscheidet, ob auf dieser Grundlage eine Ausnahme zuzulassen ist. Die Entsendung eines diversen Mitglieds ist jederzeit möglich.","children":[]},{"type":"subparagraph","label":"(3)","text":"Kommt zwischen den nach Absatz 1 Satz 2 Nummern 2, 4 und 5 entsendungsberechtigten Organisationen eine Einigung über die Länderzuordnung nicht innerhalb einer Frist von zwei Monaten nach der Aufforderung zur Benennung der Mitglieder zustande, entscheidet darüber das Präsidium des Parlaments des nach § 39 aufsichtsführenden Landes - im Fall einer Einigung zwischen den Verbänden, Initiativen und Arbeitsgemeinschaften des Absatz 1 Satz 2 Nummer 7 entscheidet das Präsidium des Parlaments des jeweils entsendeberechtigten Landes auf der Grundlage von Vorschlägen dieser Organisationen.","children":[]},{"type":"subparagraph","label":"(4)","text":"Die Organisationen und Gruppen entsenden die Mitglieder, auch unter Beachtung von Absatz 2, in eigener Verantwortung. Eine einmalige Wiederentsendung in den Rundfunkrat ist zulässig. Der oder die Vorsitzende des Rundfunkrats fordert neun Monate vor Ablauf der Amtsperiode des Gremiums die in Absatz 1 genannten Organisationen und Gruppen auf, das zu entsendende Mitglied dem Rundfunkratsvorsitz zu benennen. Er oder sie stellt die ordnungsgemäße Entsendung fest.","children":[]},{"type":"subparagraph","label":"(5)","text":"Solange und soweit Mitglieder in den Rundfunkrat nicht entsandt werden, verringert sich die Mitgliederzahl entsprechend. Scheidet ein Mitglied des Rundfunkrats vorzeitig aus, ist für den Rest der Amtsperiode ein Nachfolger oder eine Nachfolgerin nach den für die Entsendung des ausgeschiedenen Mitglieds geltenden Vorschriften zu bestimmen.","children":[]},{"type":"subparagraph","label":"(6)","text":"Kann eine nach Absatz 1 entsendungsberechtigte Organisation oder Gruppe die ihr zugewiesenen Aufgaben im Rundfunkrat aus tatsächlichen oder rechtlichen Gründen auf Dauer nicht mehr wahrnehmen, so entscheidet auf Antrag des Rundfunkrats das Parlament des Landes, in dem diese Organisation oder Gruppe ihren Sitz hat, über die ersatzweise Entsendung. Die Auswahl wird unter Organisationen oder Gruppen mit im Wesentlichen gleichartiger gesellschaftlicher Aufgabenstellung getroffen.","children":[]},{"type":"subparagraph","label":"(7)","text":"Die Landesregierungen überprüfen die Zusammensetzung des Rundfunkrats gemäß Absatz 1 Satz 2 rechtzeitig vor Ablauf jeder Amtsperiode darauf, ob die Zusammensetzung eine sachgerechte, der bestehenden Vielfalt prinzipiell Rechnung tragende Bestimmung und Gewichtung der maßgeblichen gesellschaftlichen Kräfte noch gewährleistet, und legen den Parlamenten einen Vorschlag zur Zusammensetzung für die nächste Amtsperiode vor.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 19, 0, 1, '{"type":"paragraph","label":"§ 19","title":"Aufgaben des Rundfunkrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Rundfunkrat soll die Interessen der Allgemeinheit auf dem Gebiet des öffentlich-rechtlichen Rundfunks vertreten. Dabei berücksichtigt er die Vielfalt der Meinungen der Bürger und Bürgerinnen. Er wirkt darauf hin, dass der NDR seine Aufgabe nach diesem Staatsvertrag erfüllt, soweit dafür nicht der Verwaltungsrat zuständig ist.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Rundfunkrat überwacht die Einhaltung der Anforderungen an die Angebote des NDR (§§ 3, 5, 7 bis 10) und berät den Intendanten oder die Intendantin in allgemeinen Programmangelegenheiten. Er kann feststellen, dass einzelne Sendungen gegen diese Anforderungen verstoßen, und den Intendanten oder die Intendantin anweisen, einen festgestellten Verstoß nicht fortzusetzen oder künftig zu unterlassen. Eine Kontrolle einzelner Sendungen durch den Rundfunkrat vor ihrer Ausstrahlung ist nicht zulässig; die Vorschriften des Jugendmedienschutz-Staatsvertrages bleiben unberührt.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Rundfunkrat hat ferner folgende Aufgaben:","children":[]},{"type":"item","label":"1.","text":"Erlass von Satzungen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Wahl und Abberufung des Intendanten oder der Intendantin und seines oder ihres Stellvertreters oder seiner oder ihrer Stellvertreterin,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Wahl und Abberufung der Mitglieder des Verwaltungsrats,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"Genehmigung des Wirtschaftsplans; dabei kann der Rundfunkrat über den vom Verwaltungsrat festgestellten Gesamtansatz der Aufwendungen nicht hinausgehen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5.","text":"Genehmigung des Jahresabschlusses,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"6.","text":"Entscheidung über die Übernahme von Verpflichtungen im Wert von mehr als 2,5 Millionen Euro bei Verträgen über Herstellung, Erwerb, Veräußerung und Auswertung von Angebotsteilen oder entsprechenden Rechten,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"7.","text":"Zustimmung zur gemeinsamen Produktion und Gestaltung von Teilen der Landesprogramme durch die Landesfunkhäuser im Rahmen von § 3 Absatz 4,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"8.","text":"Zustimmung zur Einrichtung eines weiteren Landesprogramms gemäß § 3 Absatz 1 Satz 4,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"9.","text":"Entscheidung über Beschränkungen und Ausnahmen nach den §§ 8 und 9 Absatz 1 des Jugendmedienschutz-Staatsvertrages ,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"10.","text":"Zustimmung zum Redaktionsstatut gemäß § 42 nach Anhörung des Verwaltungsrats.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(4)","text":"Bei der Wahrnehmung seiner Aufgaben sind dem Rundfunkrat und seinen Ausschüssen von dem Intendanten oder der Intendantin und vom Verwaltungsrat Auskünfte zu erteilen und Einsicht in die Unterlagen des NDR zu gewähren.","children":[]},{"type":"subparagraph","label":"(5)","text":"Die Wahl nach Absatz 3 Nummer 3 findet ein Jahr nach dem ersten Zusammentritt des Rundfunkrats statt. Eine einmalige Wiederwahl von Mitgliedern in den Verwaltungsrat ist zulässig.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 20, 0, 1, '{"type":"paragraph","label":"§ 20","title":"Amtsperiode und Vorsitz des Rundfunkrats","children":[{"type":"subparagraph","label":"(1)","text":"Die Amtsperiode des Rundfunkrats beträgt fünf Jahre und beginnt mit seinem ersten Zusammentritt. Nach Ablauf der Amtsperiode führt der Rundfunkrat die Geschäfte bis zum Zusammentritt des neuen Rundfunkrats. Die Mitgliedschaft im Rundfunkrat endet, wenn ein Ausschließungsgrund nach § 17 Absatz 2 bis Absatz 6 eintritt oder eine persönliche Voraussetzung nach § 17 Absatz 7 fortfällt.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Mitglieder des Rundfunkrats haben bei Wahrnehmung ihrer Aufgaben die Interessen der Allgemeinheit zu vertreten. Sie sind in ihrer Amtsführung an Aufträge oder Weisungen nicht gebunden.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Rundfunkrat wählt jeweils ein Mitglied für die Funktionen Vorsitz sowie erste, zweite und dritte Stellvertretung für die Dauer von 15 Monaten. Die vier Mitglieder müssen jeweils verschiedenen Ländern angehören. Der Vorsitz muss gleichermaßen aus Frauen und Männern bestehen. Der Vorsitz wechselt nach Ländern in der Reihenfolge Schleswig-Holstein - Niedersachsen - Hamburg - Mecklenburg-Vorpommern.","children":[]},{"type":"subparagraph","label":"(4)","text":"Die Mitglieder des Rundfunkrats haben Anspruch auf Ersatz von Reisekosten sowie auf angemessene Tagegelder und Übernachtungskosten nach Maßgabe der Satzung. Mitglieder des Vorstands sowie Vorsitzende von Ausschüssen haben zudem Anspruch auf eine angemessene Aufwandsentschädigung.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 21, 0, 1, '{"type":"paragraph","label":"§ 21","title":"Sitzungen des Rundfunkrats","children":[{"type":"subparagraph","label":"(1)","text":"Die Sitzungen des Rundfunkrats finden nach Maßgabe der Satzung statt.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Mitglieder des Verwaltungsrats sowie der Intendant oder die Intendantin, dessen oder deren Stellvertreter oder Stellvertreterin und die Direktoren oder Direktorinnen (Funkhausdirektoren oder -direktorinnen und andere Direktoren oder Direktorinnen) können an den Sitzungen des Rundfunkrats beratend teilnehmen. Auf Verlangen des Rundfunkrats sind der oder die Vorsitzende des Verwaltungsrats sowie der Intendant oder die Intendantin, dessen oder deren Stellvertreter oder Stellvertreterin und die Direktoren oder Direktorinnen hierzu verpflichtet.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Gesamtpersonalrat kann zu den Sitzungen bis zu drei Mitglieder entsenden. Ihnen wird auf Verlangen zu Angelegenheiten ihres Aufgabenbereichs das Wort erteilt.","children":[]},{"type":"subparagraph","label":"(4)","text":"Die Regierungen der Länder sind in ihrer Funktion als Rechtsaufsicht berechtigt, zu den Sitzungen des Rundfunkrats Vertreter oder Vertreterinnen zu entsenden. Diese Vertreter oder Vertreterinnen sind jederzeit zu hören.","children":[]},{"type":"subparagraph","label":"(5)","text":"Die Sitzungen des Rundfunkrats sind öffentlich. In begründeten Ausnahmefällen kann der Rundfunkrat den Ausschluss der Öffentlichkeit beschließen. Personalangelegenheiten, die aus Gründen des Persönlichkeitsschutzes vertraulich sind, und Angelegenheiten, in welchen die Offenlegung von Betriebs- und Geschäftsgeheimnissen des NDR oder Dritter unvermeidlich ist, sind stets unter Ausschluss der Öffentlichkeit zu behandeln. Die Sitzungen der Ausschüsse nach § 23 sind grundsätzlich nicht öffentlich.","children":[]},{"type":"subparagraph","label":"(6)","text":"Die Öffentlichkeit der Sitzungen kann auch dadurch hergestellt werden, dass die Sitzungen zeitgleich in Bild und Ton in einen öffentlich zugänglichen Raum des NDR oder über allgemein zugängliche Netze übertragen werden.","children":[]},{"type":"subparagraph","label":"(7)","text":"Ist die Durchführung einer Sitzung des Rundfunkrats in unmittelbarer Anwesenheit seiner Mitglieder und der nach Absatz 2 bis Absatz 4 sonst Teilnahmeberechtigten nicht möglich oder durch außergewöhnliche äußere Umstände erheblich erschwert, kann das den Vorsitz führende Mitglied des Rundfunkrats anordnen, dass ohne unmittelbare Anwesenheit stattdessen die Teilnehmenden durch eine synchrone Übertragung von Bild und Ton miteinander verbunden sind (Videokonferenz). Eine Bildübertragung kann bei bis zu einem Drittel der teilnehmenden Mitglieder des Rundfunkrats unterbleiben, soweit diese mit einer ausschließlich durch Tonübertragung gewährleisteten Teilnahme einverstanden sind und kein Zweifel an deren Identität besteht. Durch geeignete technische Hilfsmittel ist sicherzustellen, dass Teilnahme- und Rederechte uneingeschränkt ausgeübt werden können und der Datenschutz gewährleistet bleibt. Die Öffentlichkeit einer Sitzung nach Satz 1 ist durch das Verfahren nach Absatz 6 zu gewährleisten. Die Regelungen über den Ausschluss der Öffentlichkeit gemäß Absatz 5 Satz 2 und Satz 3 sowie über die Beschlussfassung innerhalb einer Videokonferenz gemäß § 22 Absatz 4 bleiben unberührt.","children":[]},{"type":"subparagraph","label":"(8)","text":"Die Zusammensetzung des Rundfunkrats sowie seiner Ausschüsse nach § 23 sind zu veröffentlichen. Die Tagesordnung der Sitzungen des Rundfunkrats und seiner Ausschüsse sind spätestens eine Woche vor den Sitzungen zu veröffentlichen. Im Anschluss an die Sitzungen des Rundfunkrats sind Zusammenfassungen der wesentlichen Ergebnisse der Sitzungen des Rundfunkrats und seiner vorbereitenden Ausschüsse sowie die Anwesenheitslisten zu veröffentlichen. Die Veröffentlichung hat unter Wahrung von Betriebs- und Geschäftsgeheimnissen sowie personenbezogenen Daten der Beschäftigten des NDR zu erfolgen. Berechtigte Interessen Dritter an Geheimhaltung sind zu wahren. Eine Veröffentlichung in elektronischer Form im Online-Angebot des NDR ist ausreichend.","children":[]},{"type":"subparagraph","label":"(9)","text":"Das Nähere regelt die Satzung.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 22, 0, 1, '{"type":"paragraph","label":"§ 22","title":"Beschlüsse des Rundfunkrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Rundfunkrat ist beschlussfähig, wenn alle Mitglieder nach näherer Vorschrift der Satzung geladen wurden und wenn mindestens zwei Drittel seiner Mitglieder anwesend sind. Die Mitglieder des Rundfunkrats gelten auch im Rahmen einer gemäß § 21 Absatz 7 angeordneten Videokonferenz als anwesend.","children":[]},{"type":"subparagraph","label":"(2)","text":"Ohne Rücksicht auf die Anzahl der Erschienenen ist der Rundfunkrat beschlussfähig, wenn zu einer wegen Beschlussunfähigkeit aufgehobenen Sitzung unter ausdrücklichem Hinweis hierauf innerhalb einer angemessenen Frist erneut geladen wird.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Rundfunkrat fasst seine Beschlüsse durch Zustimmung mit der einfachen Mehrheit der anwesenden Mitglieder, soweit dieser Staatsvertrag nichts anderes bestimmt. Dasselbe gilt für Wahlen. Für Beschlüsse und Wahlen nach § 19 Absatz 3 Nummern 1 bis 4 und Nummer 8 ist eine Zustimmung von zwei Dritteln der anwesenden Mitglieder erforderlich; § 29 Absatz 3 bleibt unberührt.","children":[]},{"type":"subparagraph","label":"(4)","text":"Beschlüsse des Rundfunkrats innerhalb einer gemäß § 21 Absatz 7 angeordneten Videokonferenz sind in einem elektronischen oder schriftlichen Verfahren zulässig, wenn in Fällen höherer Gewalt die Beratung und Abstimmung des Rundfunkrats über einen Beschlussgegenstand ausschließlich in einem solchen Rahmen möglich ist, der Gegenstand der Beschlussfassung keinen zeitlichen Aufschub zulässt und nicht die Mehrheit der gesetzlichen Mitglieder des Rundfunkrats dieser Verfahrensweise vorab widersprochen hat. Das Vorliegen des Ausnahmefalls nach Satz 1 stellt das den Vorsitz führende Mitglied des Rundfunkrats fest und begründet dieses. Zur Stimmabgabe sind nur diejenigen Mitglieder des Rundfunkrats berechtigt, die nachweisbar an der Videokonferenz teilnehmen beziehungsweise teilgenommen haben. Durch geeignete technische Hilfsmittel ist sicherzustellen, dass diese Stimmrechte uneingeschränkt ausgeübt werden können. Geheime Abstimmungen dürfen in einer Videokonferenz nicht durchgeführt werden.","children":[]},{"type":"subparagraph","label":"(5)","text":"Das Nähere regelt die Satzung.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 23, 0, 1, '{"type":"paragraph","label":"§ 23","title":"Ausschüsse des Rundfunkrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Rundfunkrat bildet mindestens einen Programmausschuss. Er kann weitere Ausschüsse bilden. In den Ausschüssen sollen Frauen und Männer entsprechend dem Verhältnis im Rundfunkrat vertreten sein. Der Programmausschuss bereitet die Beschlüsse des Rundfunkrats in Programmangelegenheiten vor. Er kann dem Intendanten oder der Intendantin in Programmangelegenheiten Empfehlungen geben, soweit der Rundfunkrat nichts anderes beschließt.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Programmausschuss kann mit der Zustimmung von zwei Dritteln seiner anwesenden Mitglieder in dringenden Programmangelegenheiten, in denen eine Beschlussfassung des Rundfunkrats nicht kurzfristig herbeigeführt werden kann, die zur Einhaltung der Programmanforderungen erforderlichen Beschlüsse nach § 19 Absatz 2 fassen. Der oder die Vorsitzende des Rundfunkrats ist hiervon unverzüglich zu unterrichten. Der Rundfunkrat hat in seiner nächsten Sitzung über die Beschlüsse des Programmausschusses zu entscheiden.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 24, 0, 1, '{"type":"paragraph","label":"§ 24","title":"Landesrundfunkrat","children":[{"type":"subparagraph","label":"(1)","text":"Bei jedem Landesfunkhaus wird ein Landesrundfunkrat gebildet. Dem Landesrundfunkrat gehören die Mitglieder des jeweiligen Landes im Rundfunkrat an. Die Landesrundfunkräte können öffentlich tagen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Landesrundfunkrat überwacht die Einhaltung der Anforderungen an die jeweiligen Landesangebote (§ 3 Absatz 3; §§ 5, 7 bis 10) und berät im Rahmen der Aufgaben, die dem Landesfunkhaus zur Wahrnehmung in eigener Verantwortung nach diesem Staatsvertrag zugewiesen sind, den Landesfunkhausdirektor oder die Landesfunkhausdirektorin in allen Angelegenheiten von grundsätzlicher Bedeutung. Er kann nach erfolgter Ausstrahlung feststellen, dass einzelne Angebote gegen diese Anforderungen verstoßen, und den Intendanten oder die Intendantin anweisen, einen festgestellten Verstoß nicht fortzusetzen oder künftig zu unterlassen. Eine Kontrolle einzelner Angebote durch den Landesrundfunkrat vor ihrer Ausstrahlung ist nicht zulässig; § 9 des Jugendmedienschutz-Staatsvertrages bleibt unberührt. Dem Landesrundfunkrat stehen insbesondere folgende Aufgaben zu:","children":[]},{"type":"item","label":"1.","text":"Stellungnahme zum Entwurf des Wirtschaftsplans des Intendanten oder der Intendantin, soweit das Landesfunkhaus betroffen ist,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Zustimmung zum Vorschlag des Intendanten oder der Intendantin für die Berufung des Landesfunkhausdirektors oder der Landesfunkhausdirektorin,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Erlass einer Geschäftsordnung.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Gesamtverantwortung des Rundfunkrats (§ 19) bleibt unberührt.","children":[]},{"type":"subparagraph","label":"(4)","text":"Die Bestimmungen der §§ 19 Absatz 1 und Absatz 4; 20 Absatz 1 und Absatz 2; 21 Absatz 1, Absatz 2 Satz 1, Absatz 3, Absatz 4 und Absatz 7 Satz 1 bis Satz 3; 22 Absatz 1 bis Absatz 3 Satz 1 und Absatz 4 finden im Rahmen der Zuständigkeit des Landesrundfunkrats entsprechende Anwendung. Die Mitglieder des Landesrundfunkrats haben Anspruch auf Ersatz von Reisekosten sowie auf Tagegelder und Übernachtungsgelder nach Maßgabe der Satzung.","children":[]},{"type":"subparagraph","label":"(5)","text":"Der Landesrundfunkrat wählt jeweils ein Mitglied für die Funktionen Vorsitz und Stellvertretung für die Dauer der Amtszeit des Rundfunkrats.","children":[]},{"type":"subparagraph","label":"(6)","text":"Der oder die Vorsitzende des Landesrundfunkrats oder sein oder ihr Stellvertreter oder seine oder ihre Stellvertreterin sind berechtigt und auf Verlangen eines Drittels der Mitglieder des Rundfunkrats verpflichtet, über Angelegenheiten des jeweiligen Landesrundfunkrats im Rundfunkrat zu berichten.","children":[]},{"type":"subparagraph","label":"(7)","text":"Der oder die Vorsitzende des Rundfunkrats sowie der jeweilige Landesfunkhausdirektor oder die jeweilige Landesfunkhausdirektorin sind berechtigt, an Sitzungen des Landesrundfunkrats teilzunehmen; auf Verlangen des Landesrundfunkrats ist der jeweilige Landesfunkhausdirektor oder die jeweilige Landesfunkhausdirektorin hierzu verpflichtet. Er oder sie kann verlangen, gehört zu werden. Gleiches gilt für den Fall der Stellvertretung.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 25, 0, 1, '{"type":"paragraph","label":"§ 25","title":"Zusammensetzung des Verwaltungsrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Verwaltungsrat besteht aus zwölf Mitgliedern, die vom Rundfunkrat gewählt werden, und zwar sechs Mitgliedern aus Niedersachsen und je zwei Mitgliedern aus Hamburg, Mecklenburg-Vorpommern und Schleswig-Holstein, wovon jeweils die Hälfte Frauen sein sollen. Von den in den Verwaltungsrat gewählten Mitgliedern müssen auf Frauen und Männer jeweils fünfzig vom Hundert entfallen. § 18 Absatz 2 Satz 6 gilt entsprechend.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Mitglieder des Verwaltungsrats müssen über die für die Tätigkeit im Verwaltungsrat erforderliche fachliche Qualifikation verfügen. Hierzu zählen Kenntnisse auf den Gebieten der Finanzwirtschaft oder -wissenschaft, der Medienwirtschaft oder -wissenschaft, der Rechtswissenschaft, des Journalismus oder vergleichbarer, geeigneter Qualifikationen.","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Mitglieder des Verwaltungsrats haben die Interessen des NDR zu fördern. Sie sind bei der Erfüllung ihrer Aufgaben an Aufträge oder Weisungen nicht gebunden; sie dürfen keine Sonderinteressen vertreten.","children":[]},{"type":"subparagraph","label":"(4)","text":"§ 20 Absatz 4 gilt für die Mitglieder des Verwaltungsrats entsprechend mit der Maßgabe, dass Mitglieder des Verwaltungsrats Anspruch auf eine angemessene Aufwandsentschädigung haben.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 26, 0, 1, '{"type":"paragraph","label":"§ 26","title":"Aufgaben des Verwaltungsrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Verwaltungsrat überwacht die Geschäftsführung des Intendanten oder der Intendantin; dies gilt nicht für die inhaltliche Gestaltung der Angebote, die allein der Rundfunkrat und - im Rahmen ihrer Zuständigkeit - die Landesrundfunkräte überwachen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Verwaltungsrat hat ferner folgende Aufgaben:","children":[]},{"type":"item","label":"1.","text":"Feststellung des Wirtschaftsplans und des Jahresabschlusses,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Feststellung des Entwicklungsplans,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Erlass der Finanzordnung,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"Zustimmung zu Rechtsgeschäften und Entscheidungen des Intendanten oder der Intendantin nach § 31,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5.","text":"Vertretung des NDR beim Abschluss von Rechtsgeschäften und in anderen Rechtsangelegenheiten gegenüber dem Intendanten oder der Intendantin,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"6.","text":"Auswahl des Abschlussprüfers oder der Abschlussprüferin,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"7.","text":"Entlastung des Intendanten oder der Intendantin,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"8.","text":"Vorschläge für die Wahl und die Abberufung des Intendanten oder der Intendantin und seines oder ihres Stellvertreters oder seiner oder ihrer Stellvertreterin nach § 29,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"9.","text":"Zustimmung zur Einrichtung eines weiteren Landesprogramms gemäß § 3 Absatz 1 Satz 4.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(3)","text":"Bei der Wahrnehmung seiner Aufgaben sind dem Verwaltungsrat von dem Intendanten oder der Intendantin Auskünfte zu erteilen und Einsicht in die Unterlagen des NDR zu gewähren. Der Verwaltungsrat kann einzelne Vorgänge untersuchen; er kann damit für bestimmte Aufgaben auch besondere Sachverständige beauftragen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 27, 0, 1, '{"type":"paragraph","label":"§ 27","title":"Amtsperiode des Verwaltungsrats","children":[{"type":"subparagraph","label":"(1)","text":"Die Amtsperiode des Verwaltungsrats beträgt fünf Jahre und beginnt mit seinem ersten Zusammentritt. Nach Ablauf der Amtsperiode führt der Verwaltungsrat die Geschäfte bis zum Zusammentritt des neuen Verwaltungsrats. Die Mitgliedschaft im Verwaltungsrat endet bei Abberufung oder dann, wenn ein Ausschließungsgrund nach § 17 Absatz 2 bis Absatz 6 eintritt oder eine persönliche Voraussetzung nach § 17 Absatz 7 fortfällt.","children":[]},{"type":"subparagraph","label":"(2)","text":"Ein Mitglied des Verwaltungsrats kann auf Antrag des Verwaltungsrats vom Rundfunkrat abberufen werden, wenn sein Verbleiben im Amt die Interessen des NDR erheblich schädigen würde. Der Verwaltungsrat und der Rundfunkrat haben dem betroffenen Mitglied Gelegenheit zur Äußerung zu geben. Das betroffene Mitglied ist von der Beratung und Beschlussfassung über den Antrag im Verwaltungsrat ausgeschlossen. Das Nähere regelt die Satzung.","children":[]},{"type":"subparagraph","label":"(3)","text":"Scheidet ein Mitglied des Verwaltungsrats vorzeitig aus, ist innerhalb von zwei Monaten nach dessen Ausscheiden für den Rest der Amtsperiode ein Nachfolger oder eine Nachfolgerin zu wählen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 28, 0, 1, '{"type":"paragraph","label":"§ 28","title":"Sitzungen des Verwaltungsrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Verwaltungsrat tritt in der Regel einmal im Monat, mindestens jedoch einmal im Vierteljahr zusammen. Er wird von seinem oder seiner Vorsitzenden oder, wenn ein Vorsitzender oder eine Vorsitzende nicht vorhanden ist, von dem an Lebensjahren ältesten Mitglied einberufen. Der Verwaltungsrat ist unverzüglich einzuberufen, wenn drei Mitglieder unter Angabe der Gründe es verlangen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Intendant oder die Intendantin, der Stellvertreter oder die Stellvertreterin sowie die Direktoren und Direktorinnen können an den Sitzungen des Verwaltungsrats beratend teilnehmen. Auf Verlangen des Verwaltungsrats sind sie hierzu verpflichtet.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Verwaltungsrat ist beschlussfähig, wenn alle Mitglieder nach näherer Vorschrift der Satzung geladen wurden und wenn mindestens sieben Mitglieder anwesend sind. Ist der Verwaltungsrat beschlussunfähig, sind alle Mitglieder innerhalb einer Woche mit derselben Tagesordnung erneut zu laden. In der darauf stattfindenden Sitzung ist der Verwaltungsrat ohne Rücksicht auf die Anzahl der anwesenden Mitglieder beschlussfähig.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der Verwaltungsrat fasst seine Beschlüsse durch Zustimmung mit einfacher Mehrheit der anwesenden Mitglieder, soweit in diesem Staatsvertrag nichts anderes bestimmt ist; entsprechendes gilt für die Wahl des oder der Vorsitzenden und dessen oder deren Stellvertreter oder Stellvertreterin. Für Beschlüsse nach § 26 Absatz 2 Nummern 1, 2, 8 und 9 ist die Zustimmung von zwei Dritteln der gesetzlichen Mitglieder erforderlich. Kommt eine Mehrheit nicht zustande, ist der Antrag abgelehnt.","children":[]},{"type":"subparagraph","label":"(5)","text":"Ist die Durchführung einer Sitzung des Verwaltungsrats in unmittelbarer Anwesenheit seiner Mitglieder nicht möglich oder durch außergewöhnliche äußere Umstände erheblich erschwert, kann der Verwaltungsrat stattdessen im Wege einer Audio-/Videokonferenz ohne unmittelbare Anwesenheit zusammentreten. In diesem Fall ist eine Beschlussfassung im schriftlichen oder elektronischen Verfahren zulässig. Stimmberechtigt sind diejenigen Mitglieder, die an der Audio-/Videokonferenz teilnehmen beziehungsweise teilgenommen haben.","children":[]},{"type":"subparagraph","label":"(6)","text":"Der Verwaltungsrat wählt seinen Vorsitzenden oder seine Vorsitzende und dessen oder deren Stellvertreter oder Stellvertreterin für die Dauer von 15 Monaten. Der Vorsitz wechselt nach Ländern in der Reihenfolge Niedersachsen - Hamburg - Mecklenburg-Vorpommern - Schleswig-Holstein. Für die Wahl des oder der stellvertretenden Vorsitzenden gilt die umgekehrte Reihenfolge.","children":[]},{"type":"subparagraph","label":"(7)","text":"Die Regierungen der Länder sind in ihrer Funktion als Rechtsaufsicht berechtigt, zu den Sitzungen des Verwaltungsrats je einen Vertreter oder eine Vertreterin zu entsenden. Diese sind jederzeit zu hören. Ihnen sind alle Unterlagen zur Verfügung zu stellen, die auch die Mitglieder des Verwaltungsrats erhalten.","children":[]},{"type":"subparagraph","label":"(8)","text":"Der Gesamtpersonalrat kann zu den Sitzungen bis zu drei Mitglieder entsenden. Ihnen wird auf Verlangen zu Angelegenheiten ihres Aufgabenbereichs das Wort erteilt.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 29, 0, 1, '{"type":"paragraph","label":"§ 29","title":"Wahl und Abberufung des Intendanten oder der Intendantin","children":[{"type":"subparagraph","label":"(1)","text":"Der Intendant oder die Intendantin und der Stellvertreter oder die Stellvertreterin werden vom Rundfunkrat auf Vorschlag des Verwaltungsrats für die Dauer von fünf Jahren gewählt. Die Wahl erfolgt innerhalb der letzten sechs Monate seiner oder ihrer Amtszeit, bei vorzeitigem Ausscheiden unverzüglich, spätestens innerhalb von sechs Monaten. Eine Wiederwahl ist zweimal zulässig.","children":[]},{"type":"subparagraph","label":"(2)","text":"Macht der Verwaltungsrat nicht innerhalb von drei Monaten einen Wahlvorschlag, entfällt das Vorschlagsrecht. Findet ein Wahlvorschlag nicht die erforderliche Zustimmung im Rundfunkrat, ist der Verwaltungsrat berechtigt, jeweils innerhalb eines weiteren Monats einen neuen Wahlvorschlag zu machen; Satz 1 gilt entsprechend.","children":[]},{"type":"subparagraph","label":"(3)","text":"Kommt innerhalb der Frist nach Absatz 1 die Wahl im Rundfunkrat nicht zustande, findet nach Ablauf eines Monats ein weiterer Wahlgang statt. In ihm ist gewählt, wer die Zustimmung der Mehrheit der gesetzlichen Mitglieder des Rundfunkrats erhält.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der Intendant oder die Intendantin und der Stellvertreter oder die Stellvertreterin können vor Ablauf der Amtsperiode, auch auf Vorschlag des Verwaltungsrats, durch Beschluss des Rundfunkrats abberufen werden.","children":[]},{"type":"subparagraph","label":"(5)","text":"Für die Ansprüche aus den Anstellungsverträgen gelten die Vorschriften des bürgerlichen Rechts.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 30, 0, 1, '{"type":"paragraph","label":"§ 30","title":"Intendanz und Direktorium","children":[{"type":"subparagraph","label":"(1)","text":"Der Intendant oder die Intendantin leitet den NDR. Er oder sie berät mit dem Stellvertreter oder der Stellvertreterin sowie mit den Direktoren oder Direktorinnen die wesentlichen Angelegenheiten.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Aufgaben, Befugnisse und Rechtsverhältnisse des Intendanten oder der Intendantin, des Stellvertreters oder der Stellvertreterin und der Direktoren oder Direktorinnen, deren Zahl sowie die Geschäftsverteilung bestimmt die Satzung, soweit dieser Staatsvertrag keine Regelung trifft. Der Stellvertreter oder die Stellvertreterin wird von dem Direktor oder der Direktorin mit der längsten Dienstzeit vertreten. Ist ein Stellvertreter oder eine Stellvertreterin des Intendanten oder der Intendantin nicht bestellt, nimmt der dienstälteste Direktor oder die Direktorin mit der längsten Dienstzeit die Aufgaben des Stellvertreters oder der Stellvertreterin wahr.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Intendant oder die Intendantin vertritt die Anstalt als gesetzlicher Vertreter gerichtlich und außergerichtlich. Die Satzung regelt die Vertretungsbefugnis, insbesondere bestimmt sie die Fälle, in denen der Intendant oder die Intendantin zur Vertretung der Mitzeichnung des Stellvertreters oder der Stellvertreterin oder eines Direktors oder einer Direktorin bedarf.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der Intendant oder die Intendantin legt dem Rundfunkrat und dem Verwaltungsrat den Entwurf des Wirtschaftsplans, den Jahresabschluss und den Geschäftsbericht vor. Die Landesfunkhäuser sind hierbei jeweils gesondert auszuweisen. Beim Aufstellen des Wirtschaftsplans sind die Stellungnahmen der Landesrundfunkräte (§ 24 Absatz 2 Satz 3 Nummer 1) zu berücksichtigen; die Stellungnahmen sind für die Beschlussfassung vorzulegen.","children":[]},{"type":"subparagraph","label":"(5)","text":"Der Intendant oder die Intendantin berichtet dem Verwaltungsrat alle zwei Jahre quantifiziert und detailliert über die Auftrags- und Koproduktionen mit unabhängigen und abhängigen Produzenten.","children":[]},{"type":"subparagraph","label":"(6)","text":"Der Intendant oder die Intendantin hat dafür Sorge zu tragen, dass das Angebot des NDR den Angebotsanforderungen (§ 3 Absatz 3; §§ 5, 7 bis 10) entspricht.","children":[]},{"type":"subparagraph","label":"(7)","text":"Dem Intendanten oder der Intendantin, dem Stellvertreter oder der Stellvertreterin und den Direktoren oder Direktorinnen wird eine begleitende Projekt- und Finanzkontrolle nach Maßgabe der Satzung zugeordnet.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 31, 0, 1, '{"type":"paragraph","label":"§ 31","title":"Zustimmungsbedürftige Angelegenheiten","children":[{"type":"subparagraph","label":"(1)","text":"Der Intendant oder die Intendantin bedarf in folgenden Angelegenheiten der Zustimmung des Verwaltungsrats:","children":[]},{"type":"item","label":"1.","text":"Abschluss und Kündigung von Anstellungsverträgen mit Angestellten, deren Bezüge über der höchsten Tarifgruppe liegen, sowie Bestellung und Abberufung von Direktoren oder Direktorinnen; § 3 Absatz 2 Satz 3 sowie § 24 Absatz 2 Satz 3 Nummer 2 bleiben unberührt,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Abschluss von Dienstvereinbarungen und Tarifverträgen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"grundlegende Veränderungen der Bedingungen der Rundfunkwerbung,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"Abschluss von Vereinbarungen über die Zusammenarbeit mit anderen Rundfunkveranstaltern im Rahmen von § 11,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5.","text":"Erwerb, Veräußerung und Belastung von Grundstücken,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"6.","text":"Erwerb und Veräußerung von Unternehmen sowie unmittelbaren Beteiligungen an ihnen gemäß § 37,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"7.","text":"Erwerb und Veräußerung von mittelbaren Beteiligungen an Unternehmen gemäß § 37, soweit die mittelbare Beteiligung nach dem Erwerb mehr als 50 Prozent oder nach der Veräußerung weniger als 50 Prozent am Grund- oder Stammkapital dieser Unternehmen beträgt,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"8.","text":"Aufnahme von Anleihen und Inanspruchnahme von Krediten, soweit nicht im Wirtschaftsplan vorgesehen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"9.","text":"Übernahme von fremden Verbindlichkeiten, Bürgschaften und Garantien und","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"10.","text":"Übernahme von Verpflichtungen im Wert von mehr als 5 Millionen Euro außer bei Verträgen über Herstellung, Erwerb, Veräußerung oder Auswertung von Programmteilen oder entsprechenden Rechten.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Zustimmung des Verwaltungsrats zu Absatz 1 Nummer 7 ist vor der abschließenden Befassung und Entscheidung des oder der zuständigen Organe des die Beteiligung eingehenden Unternehmens einzuholen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 32, 0, 1, '{"type":"paragraph","label":"§ 32","title":"Wirtschaftsführung","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR hat die zur Erfüllung seiner Aufgaben erforderlichen regelmäßigen Einnahmen vorrangig","children":[]},{"type":"item","label":"1.","text":"aus dem Rundfunkbeitrag,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"aus Werbung und Sponsoring,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"aus laufenden Erträgen seines Vermögens","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"zu beschaffen. Sie dürfen nur für die in diesem Gesetz bestimmten Aufgaben verwendet werden. Die Bestimmungen des § 112 Absatz 2 und Absatz 3 Satz 2 des Medienstaatsvertrages bleiben unberührt."},{"type":"subparagraph","label":"(2)","text":"Der NDR hat bei seiner Wirtschaftsführung die Grundsätze der Wirtschaftlichkeit und Sparsamkeit, der Nachhaltigkeit sowie der Klarheit bei der finanziellen Zuordnung von Einnahmen und Ausgaben zu beachten. Er verwendet seine finanziellen Mittel in der Weise, wie dies zur Erfüllung seiner Aufgaben erforderlich ist. Die Wirtschaftsführung des NDR richtet sich nach der Finanzordnung, einer mehrjährigen Finanzplanung, dem Entwicklungsplan und dem jährlichen Wirtschaftsplan.","children":[]},{"type":"subparagraph","label":"(3)","text":"Mit der mehrjährigen Finanzplanung ist ein Entwicklungsplan aufzustellen und fortzuschreiben, der die Vorstellungen des NDR für die strukturelle Entwicklung der Rundfunkanstalt sowie den Ausbau seiner Einrichtungen, insbesondere für die Versorgung mit Landesprogrammen, enthält.","children":[]},{"type":"subparagraph","label":"(4)","text":"Ist bis zum Schluss eines Geschäftsjahres der Wirtschaftsplan für das folgende Jahr nicht wirksam geworden, ist der Intendant oder die Intendantin bis zum Wirksamwerden ermächtigt, alle Ausgaben zu leisten, die notwendig sind, um","children":[]},{"type":"item","label":"1.","text":"den Betrieb des NDR in seinem bisherigen Umfang zu erhalten,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"die von den Organen des NDR beschlossenen Maßnahmen durchzuführen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Bauten, Beschaffungen und sonstige Leistungen fortzusetzen, sofern durch den Wirtschaftsplan des Vorjahres bereits Beträge bewilligt sind,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"rechtlich begründete Verpflichtungen des NDR zu erfüllen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(5)","text":"Der NDR soll die Ansprüche der Mitarbeitenden aus Versorgungszusagen durch Bildung von Rückstellungen in angemessenem Umfang sicherstellen. Zur Sicherung der Ansprüche sind Finanzmittel in angemessener Höhe einem Sondervermögen zuzuführen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 33, 0, 1, '{"type":"paragraph","label":"§ 33","title":"Jahresabschluss und Geschäftsbericht","children":[{"type":"subparagraph","label":"(1)","text":"Der Intendant oder die Intendantin hat nach Abschluss des Geschäftsjahres den Jahresabschluss, den Lagebericht, den Konzernabschluss und den Konzernlagebericht sowie einen Geschäftsbericht aufzustellen. Der Geschäftsbericht hat einen umfassenden Einblick in die Vermögens- und Ertragsverhältnisse des NDR einschließlich seiner Beziehungen zu Beteiligungsunternehmen zu vermitteln.","children":[]},{"type":"subparagraph","label":"(2)","text":"Jahresabschluss und Lagebericht sowie Konzernabschluss und Konzernlagebericht sind in entsprechender Anwendung der Vorschriften des Dritten Buches des Handelsgesetzbuches für große Kapitalgesellschaften aufzustellen und vor der Feststellung zu prüfen. Getrennt auszuweisen ist insbesondere die Veranstaltung von Hörfunk- und Fernsehprogrammen. Die Kriterien für die Zuordnung von Einnahmen und Ausgaben sind dem Verwaltungsrat zu erläutern. Der Abschlussprüfer oder die Abschlussprüferin ist auch mit den Feststellungen und Berichten nach § 53 Absatz 1 des Haushaltsgrundsätzegesetzes zu beauftragen.","children":[]},{"type":"subparagraph","label":"(3)","text":"Jahresabschluss, Lagebericht, Konzernabschluss, Konzernlagebericht, Prüfungsbericht und Geschäftsbericht werden vom Intendanten oder von der Intendantin den Regierungen und Rechnungshöfen der Länder übermittelt.","children":[]},{"type":"subparagraph","label":"(4)","text":"Nach Genehmigung des Jahresabschlusses durch den Rundfunkrat veröffentlicht der Intendant oder die Intendantin eine Gesamtübersicht über den Jahresabschluss und eine Zusammenfassung der wesentlichen Teile des Geschäftsberichts.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 34, 0, 1, '{"type":"paragraph","label":"§ 34","title":"Information der Landesparlamente","children":[{"type":"paragraphText","text":"Für die Information der Parlamente der Länder gilt § 5a des Rundfunkfinanzierungsstaatsvertrages entsprechend."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 35, 0, 1, '{"type":"paragraph","label":"§ 35","title":"Finanzordnung","children":[{"type":"subparagraph","label":"(1)","text":"Die Finanzordnung wird vom Verwaltungsrat erlassen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Finanzordnung hat von folgenden Grundsätzen auszugehen:","children":[]},{"type":"item","label":"1.","text":"Für jedes Geschäftsjahr ist ein Wirtschaftsplan aufzustellen. § 33 Absatz 2 Satz 2 und Satz 3 gilt entsprechend. Der Wirtschaftsplan dient der Feststellung und Deckung des Finanzbedarfs, der zur Erfüllung der Aufgaben des NDR voraussichtlich notwendig ist;","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"der Wirtschaftsplan ermächtigt den Intendanten oder die Intendantin, Ausgaben zu leisten und Verpflichtungen einzugehen;","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"der Wirtschaftsplan bestimmt, bis zu welcher Höhe der Intendant oder die Intendantin Kredite aufnehmen darf.","level":0,"numberingStyle":"decimal","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 36, 0, 1, '{"type":"paragraph","label":"§ 36","title":"Finanzkontrolle","children":[{"type":"subparagraph","label":"(1)","text":"Die Rechnungshöfe der Länder prüfen die Wirtschaftsführung des NDR gemeinsam. Federführend ist grundsätzlich der Rechnungshof des nach § 39 Aufsicht führenden Landes.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der für die Durchführung zuständige Rechnungshof teilt das Ergebnis der Prüfung des NDR einschließlich deren Beteiligungsunternehmen dem Intendanten oder der Intendantin, dem Direktor oder der Direktorin des jeweiligen Landesfunkhauses, den jeweils zuständigen Aufsichtsgremien und der Geschäftsführung des geprüften Beteiligungsunternehmens sowie der KEF mit. Er gibt dem Intendanten oder der Intendantin, dem Direktor oder der Direktorin des jeweiligen Landesfunkhauses und der Geschäftsführung des Beteiligungsunternehmens Gelegenheit zur Stellungnahme zu dem Ergebnis der Prüfung und berücksichtigt die Stellungnahmen. Den auf dieser Grundlage erstellten abschließenden Bericht über das Ergebnis teilt der zuständige Rechnungshof den Landtagen und den Landesregierungen sowie der KEF mit und veröffentlicht ihn anschließend. Dabei hat der Rechnungshof darauf zu achten, dass die Wettbewerbsfähigkeit des geprüften Beteiligungsunternehmens nicht beeinträchtigt wird und insbesondere Betriebs- und Geschäftsgeheimnisse gewahrt werden.","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Vorschriften der Landeshaushaltsordnungen der Länder über Unternehmen in der Rechtsform einer landesunmittelbaren juristischen Person des öffentlichen Rechts sind in der jeweils geltenden Fassung im Übrigen entsprechend anzuwenden.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 37, 0, 1, '{"type":"paragraph","label":"§ 37","title":"Beteiligungen","children":[{"type":"subparagraph","label":"(1)","text":"An einem Unternehmen, das einen gewerblichen oder sonstigen wirtschaftlichen Zweck zum Gegenstand hat, darf sich der NDR unmittelbar oder mittelbar beteiligen, wenn","children":[]},{"type":"item","label":"1.","text":"dies im Rahmen seiner gesetzlichen Aufgaben steht,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"das Unternehmen die Rechtsform einer juristischen Person besitzt und","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"die Satzung oder der Gesellschaftsvertrag des Unternehmens einen Aufsichtsrat oder ein entsprechendes Organ vorsieht.","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"Die Voraussetzungen nach Satz 1 müssen nicht erfüllt sein, wenn die Beteiligung nur vorübergehend eingegangen wird und unmittelbaren Angebotszwecken dient."},{"type":"subparagraph","label":"(2)","text":"Bei Beteiligungsunternehmen hat sich der NDR in geeigneter Weise den nötigen Einfluss auf die Geschäftsleitung des Unternehmens, insbesondere eine angemessene Vertretung im Aufsichtsgremium, zu sichern. Eine Prüfung der Betätigung der Anstalt bei dem Unternehmen unter Beachtung kaufmännischer Grundsätze durch ein Wirtschaftsprüfungsunternehmen ist auszubedingen; § 36 bleibt unberührt.","children":[]},{"type":"subparagraph","label":"(3)","text":"Absatz 1 und Absatz 2 gelten entsprechend für juristische Personen des Privatrechts, die vom NDR gegründet werden und/oder deren Geschäftsanteile sich ausschließlich in der Hand des NDR befinden.","children":[]},{"type":"subparagraph","label":"(4)","text":"Angehörige des NDR sowie Mitglieder des Rundfunkrats oder des Verwaltungsrats dürfen an Unternehmen, an denen der NDR unmittelbar oder mittelbar beteiligt ist, nicht persönlich beteiligt sein. Die Mitglieder des Verwaltungsrats dürfen nicht den Aufsichtsgremien nach Absatz 1 und Absatz 2 angehören.","children":[]},{"type":"subparagraph","label":"(5)","text":"Der NDR hat sicherzustellen, dass Mitglieder der Geschäftsführung sowie leitende Angestellte von juristischen Personen nach Absatz 1 und Absatz 3 nicht ihrerseits an anderen juristischen Personen dieser Art beteiligt sind.","children":[]},{"type":"subparagraph","label":"(6)","text":"Der NDR hat ein effektives Controlling über seine Beteiligungen einzurichten. Der Intendant oder die Intendantin hat den Verwaltungsrat regelmäßig über die wesentlichen Vorgänge in den Beteiligungsunternehmen, insbesondere über deren finanzielle Entwicklungen, zu unterrichten.","children":[]},{"type":"subparagraph","label":"(7)","text":"Der Intendant oder die Intendantin hat dem Verwaltungsrat jährlich einen Beteiligungsbericht vorzulegen. Dieser Bericht schließt folgende Bereiche ein:","children":[]},{"type":"item","label":"1.","text":"die Darstellung sämtlicher unmittelbarer und mittelbarer Beteiligungen und ihrer wirtschaftlichen Bedeutung für den NDR,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"die gesonderte Darstellung der Beteiligungen mit kommerziellen Tätigkeiten und Nachweis der Erfüllung der staatsvertraglichen Vorgaben für kommerzielle Tätigkeiten und","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"die Darstellung der Kontrolle der Beteiligung einschließlich von Vorgängen mit besonderer Bedeutung.","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"Der Bericht ist den jeweils zuständigen Rechnungshöfen und der rechtsaufsichtsführenden Landesregierung zu übermitteln."},{"type":"subparagraph","label":"(8)","text":"Die für den NDR zuständigen Rechnungshöfe prüfen die Wirtschaftsführung bei solchen Unternehmen des Privatrechts, an denen der NDR unmittelbar, mittelbar, auch zusammen mit anderen Anstalten oder Körperschaften des öffentlichen Rechts, mit Mehrheit beteiligt ist und deren Gesellschaftsvertrag oder Satzung diese Prüfung durch die Rechnungshöfe vorsieht. Der NDR ist verpflichtet, für die Aufnahme der erforderlichen Regelungen in den Gesellschaftsvertrag oder die Satzung des Unternehmens zu sorgen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 38, 0, 1, '{"type":"paragraph","label":"§ 38","title":"Werbung, Zulässiges Sponsoring, Zulässige Produktplatzierung","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR veranstaltet Fernsehwerbung im Gemeinschaftsprogramm der ARD \"Erstes Deutsches Fernsehen (Das Erste)\". Für die Gesamtdauer der Fernsehwerbung gilt § 39 Absatz 1 und Absatz 3 des Medienstaatsvertrages .","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR kann Hörfunkwerbung in einem Hörfunkprogramm veranstalten. Ihre Gesamtdauer und Struktur werden durch Vereinbarung der Länder festgesetzt.","children":[]},{"type":"subparagraph","label":"(3)","text":"Sponsoring ist nach Maßgabe des § 39 des Medienstaatsvertrages zulässig. Umfang und Struktur können durch Vereinbarung der Staatsvertragsländer festgelegt werden.","children":[]},{"type":"subparagraph","label":"(4)","text":"Produktplatzierung ist nach Maßgabe des § 38 des Medienstaatsvertrages zulässig.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 39, 0, 1, '{"type":"paragraph","label":"§ 39","title":"Rechtsaufsicht","children":[{"type":"subparagraph","label":"(1)","text":"Die Regierungen der Länder führen die Aufsicht über den NDR hinsichtlich der Einhaltung der Bestimmungen dieses Staatsvertrages und der allgemeinen Rechtsvorschriften. Sie nehmen diese Aufgabe durch die Regierung eines der Länder im Wechsel von 18 Monaten wahr. Der Wechsel erfolgt in der Reihenfolge Hamburg - Niedersachsen - Schleswig-Holstein - Mecklenburg-Vorpommern. Die jeweils aufsichtsführende Regierung beteiligt die anderen Regierungen vor der Einleitung von Maßnahmen und bemüht sich um ein Einvernehmen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die aufsichtsführende Regierung ist berechtigt, ein von ihr im Einzelfall zu bestimmendes Organ des NDR durch schriftliche Mitteilungen auf Maßnahmen oder Unterlassungen im Betrieb des NDR hinzuweisen, die diesen Staatsvertrag oder die allgemeinen Rechtsvorschriften verletzen, und das Organ aufzufordern, die Rechtsverletzung zu beseitigen.","children":[]},{"type":"subparagraph","label":"(3)","text":"Wird die Rechtsverletzung nicht innerhalb einer von der aufsichtsführenden Regierung zu setzenden angemessenen Frist behoben, weist diese den NDR an, im Einzelnen festgelegte Maßnahmen auf dessen Kosten durchzuführen. In Programmangelegenheiten sind Weisungen unzulässig.","children":[]},{"type":"subparagraph","label":"(4)","text":"Maßnahmen der Rechtsaufsicht gegenüber dem Intendanten oder der Intendantin sind erst dann zulässig, wenn der Rundfunkrat, der Landesrundfunkrat oder der Verwaltungsrat die ihnen zustehende Aufsicht nicht in angemessener Frist wahrnehmen.","children":[]},{"type":"subparagraph","label":"(5)","text":"Die aufsichtsführende Regierung ist zugleich zuständige Behörde nach § 16 Absatz 1 des Medienstaatsvertrages .","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 40, 0, 1, '{"type":"paragraph","label":"§ 40","title":"Gleichstellung von Frauen und Männern","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR hat durch Dienstvereinbarung die berufliche Gleichstellung von Frauen und Männern im NDR zu fördern. Frauen führen die jeweilige Funktionsbezeichnung für ihre Tätigkeit im NDR in der weiblichen Form.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Intendant oder die Intendantin legt dem Verwaltungsrat jährlich einen Bericht über den Stand der Gleichstellung von Frauen und Männern vor.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 41, 0, 1, '{"type":"paragraph","label":"§ 41","title":"Personalvertretung","children":[{"type":"subparagraph","label":"(1)","text":"Für den NDR finden das Bundespersonalvertretungsgesetz und die dazu ergangenen Rechtsverordnungen nach Maßgabe der für die Rundfunkanstalten des Bundesrechts geltenden Vorschriften entsprechende Anwendung. Das gilt auch für rechtsfähige Gemeinschaftseinrichtungen der Rundfunkanstalten, an denen der NDR beteiligt ist und die ihren Sitz in einem der vier Länder haben.","children":[]},{"type":"subparagraph","label":"(2)","text":"In den Fällen des § 71 Absatz 1 Satz 4 des Bundespersonalvertretungsgesetzes bestellt der Präsident oder die Präsidentin des Oberverwaltungsgerichts des nach § 39 aufsichtführenden Landes nach Anhörung der Präsidenten oder Präsidentinnen der Oberverwaltungsgerichte der übrigen Länder den Vorsitzenden oder die Vorsitzende der Einigungsstelle.","children":[]},{"type":"subparagraph","label":"(3)","text":"Arbeitnehmerähnliche Personen im Sinne des § 12a Tarifvertragsgesetz gelten als Beschäftigte im Sinne des § 4 Absatz 3 Bundespersonalvertretungsgesetzes . Für sie gelten die gleichen Personalvertretungsrechte wie für Beschäftigte, soweit ihr Vertrag mit dem NDR entsprechende Verpflichtungen enthält und die gesetzlichen Vorgaben Anwendung finden können.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 42, 0, 1, '{"type":"paragraph","label":"§ 42","title":"Statut für die Programmmitarbeitenden","children":[{"type":"subparagraph","label":"(1)","text":"Die Mitwirkungsrechte der redaktionellen Mitarbeitenden in Programmangelegenheiten richten sich nach dem Redaktionsstatut.","children":[]},{"type":"subparagraph","label":"(2)","text":"Das Redaktionsstatut tritt außer Kraft, sobald sich der Intendant oder die Intendantin und die redaktionellen Mitarbeitenden auf ein neues Redaktionsstatut verständigt haben, das die derzeit beim NDR geltenden Beteiligungsrechte wahrt und auch ständigen freien Programmmitarbeitenden angemessene Repräsentanz in der Redaktionsversammlung und im Redaktionsausschuss verschafft. Das neue Redaktionsstatut enthält insbesondere folgende Regelungen:","children":[]},{"type":"item","label":"1.","text":"Der Redaktionsausschuss behält vor allem die Aufgabe, sich nach Maßgabe des Redaktionsstatuts um eine Einigung bei Konflikten zu bemühen, die in Programmfragen zwischen Programmmitarbeitenden und ihren Vorgesetzten entstehen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Kann ein Konflikt in Programmfragen zwischen Intendant oder Intendantin und Redaktionsausschuss nicht beigelegt werden, so tritt auf Antrag ein Schlichtungsausschuss zusammen. Dieser besteht aus einem oder einer unparteiischen Vorsitzenden, einem Stellvertreter oder einer Stellvertreterin und aus Beisitzern, die für drei Jahre je zur Hälfte von dem Intendanten oder der Intendantin bestellt und vom Redaktionsausschuss entsandt werden. Der Schlichtungsausschuss beschließt eine Empfehlung an den Intendanten oder die Intendantin. Folgt der Intendant oder die Intendantin der Empfehlung nicht, hat er seine oder hat sie ihre Entscheidung gegenüber dem Schlichtungsausschuss zu begründen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(3)","text":"Änderungen des Redaktionsstatuts bedürfen der Zustimmung des Rundfunkrats.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 43, 0, 1, '{"type":"paragraph","label":"§ 43","title":"Datenverarbeitung zu journalistisch-redaktionellen Zwecken, Medienprivileg","children":[{"type":"subparagraph","label":"(1)","text":"Soweit der NDR personenbezogene Daten zu journalistischen Zwecken verarbeitet, ist es den hiermit befassten Personen untersagt, diese personenbezogenen Daten zu anderen Zwecken zu verarbeiten (Datengeheimnis). Diese Personen sind bei der Aufnahme ihrer Tätigkeit auf das Datengeheimnis zu verpflichten. Das Datengeheimnis besteht auch nach Beendigung ihrer Tätigkeit fort. Im Übrigen finden für die Datenverarbeitung zu journalistischen Zwecken von der Verordnung (EU) 2016/679 des Europäischen Parlaments und des Rates vom 27. April 2016 zum Schutz natürlicher Personen bei der Verarbeitung personenbezogener Daten, zum freien Datenverkehr und zur Aufhebung der Richtlinie 95/46/EG (Datenschutz-Grundverordnung) (ABl. EU 2016 Nr. L 119 S. 1, L 314 S. 72, 2018 Nr. L 127 S. 2) außer den Kapiteln I, VIII, X und XI nur die Artikel 5 Absatz 1 Buchstabe f in Verbindung mit Absatz 2, Artikel 24 und Artikel 32 Anwendung. Die Artikel 82 und 83 der Verordnung (EU) 2016/679 gelten mit der Maßgabe, dass nur für eine Verletzung des Datengeheimnisses gemäß den Sätzen 1 bis 3 sowie für unzureichende Maßnahmen nach Artikel 5 Absatz 1 Buchstabe f , Artikel 24 und 32 der Verordnung (EU) 2016/679 gehaftet wird. Die Sätze 1 bis 5 gelten entsprechend für die Datenverarbeitung zu journalistischen Zwecken der Hilfs- und Beteiligungsunternehmen des NDR. Der NDR kann sich einen Verhaltenskodex geben, der in einem transparenten Verfahren erlassen und veröffentlicht wird. Den betroffenen Personen stehen nur die in den Absätzen 2 und 3 genannten Rechte zu.","children":[]},{"type":"subparagraph","label":"(2)","text":"Führt die journalistische Verarbeitung personenbezogener Daten zur Verbreitung von Gegendarstellungen der betroffenen Person oder zu Verpflichtungserklärungen, Beschlüssen oder Urteilen über die Unterlassung der Verbreitung oder über den Widerruf des Inhalts der Daten, so sind diese Gegendarstellungen, Verpflichtungserklärungen und Widerrufe zu den gespeicherten Daten zu nehmen und dort für dieselbe Zeitdauer aufzubewahren wie die Daten selbst sowie bei einer Übermittlung der Daten gemeinsam mit diesen zu übermitteln.","children":[]},{"type":"subparagraph","label":"(3)","text":"Wird jemand durch eine Berichterstattung in seinem Persönlichkeitsrecht beeinträchtigt, kann die betroffene Person Auskunft über die der Berichterstattung zugrundeliegenden zu ihrer Person gespeicherten Daten verlangen. Die Auskunft kann nach Abwägung der schutzwürdigen Interessen der Beteiligten verweigert werden, soweit","children":[]},{"type":"item","label":"1.","text":"aus den Daten auf Personen, die bei der Vorbereitung, Herstellung oder Verbreitung von Rundfunksendungen mitwirken oder mitgewirkt haben, geschlossen werden kann,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"aus den Daten auf die Person des Einsenders oder des Gewährsträgers von Beiträgen, Unterlagen und Mitteilungen für den redaktionellen Teil geschlossen werden kann oder","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"durch die Mitteilung der recherchierten oder sonst erlangten Daten die journalistische Aufgabe durch Ausforschung des Informationsbestandes beeinträchtigt würde.","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"Die betroffene Person kann die unverzügliche Berichtigung unrichtiger personenbezogener Daten im Datensatz oder die Hinzufügung einer eigenen Darstellung von angemessenem Umfang verlangen. Die weitere Speicherung der personenbezogenen Daten ist rechtmäßig, wenn dies für die Ausübung des Rechts auf freie Meinungsäußerung und Information oder zur Wahrnehmung berechtigter Interessen erforderlich ist."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 44, 0, 1, '{"type":"paragraph","label":"§ 44","title":"Ernennung des oder der Rundfunkdatenschutzbeauftragten","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR ernennt einen Beauftragten oder eine Beauftragte für den Datenschutz beim NDR (Rundfunkdatenschutzbeauftragter oder Rundfunkdatenschutzbeauftragte), der oder die zuständige Aufsichtsbehörde im Sinne des Artikels 51 der Verordnung (EU) 2016/679 ist. Die Ernennung erfolgt durch den Rundfunkrat auf Vorschlag des Verwaltungsrats für die Dauer von vier Jahren. Eine dreimalige Wiederernennung ist zulässig. Der oder die Rundfunkdatenschutzbeauftragte muss über die für die Erfüllung seiner oder ihrer Aufgaben und Ausübung seiner oder ihrer Befugnisse erforderliche Qualifikation, Erfahrung und Sachkunde insbesondere im Bereich des Schutzes personenbezogener Daten verfügen. Das Amt des oder der Rundfunkdatenschutzbeauftragten kann nicht neben anderen Aufgaben innerhalb des NDR und seiner Beteiligungs- und Hilfsunternehmen wahrgenommen werden. Sonstige Aufgaben müssen mit dem Amt des oder der Rundfunkdatenschutzbeauftragten zu vereinbaren sein und dürfen seine oder ihre Unabhängigkeit nicht gefährden.","children":[]},{"type":"subparagraph","label":"(2)","text":"Das Amt endet mit Ablauf der Amtszeit, mit Rücktritt vom Amt oder mit Erreichen des gesetzlichen Renteneintrittsalters. Tarifvertragliche Regelungen bleiben unberührt. Der oder die Rundfunkdatenschutzbeauftragte kann seines oder ihres Amtes nur enthoben werden, wenn er oder sie eine schwere Verfehlung begangen hat oder die Voraussetzungen für die Wahrnehmung seiner oder ihrer Aufgaben nicht mehr erfüllt. Dies geschieht durch Beschluss des Verwaltungsrates auf Vorschlag des Rundfunkrates; der oder die Rundfunkdatenschutzbeauftragte ist vor der Entscheidung zu hören.","children":[]},{"type":"subparagraph","label":"(3)","text":"Das Nähere, insbesondere die Grundsätze der Vergütung, beschließt der Verwaltungsrat mit Zustimmung des Rundfunkrats in einer Satzung.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 45, 0, 1, '{"type":"paragraph","label":"§ 45","title":"Unabhängigkeit des oder der Rundfunkdatenschutzbeauftragten","children":[{"type":"subparagraph","label":"(1)","text":"Der oder die Rundfunkdatenschutzbeauftragte ist in Ausübung seines oder ihres Amtes unabhängig und nur dem Gesetz unterworfen. Er oder sie unterliegt keiner Rechts- oder Fachaufsicht. Der Dienstaufsicht des Verwaltungsrates untersteht er oder sie nur insoweit, als seine oder ihre Unabhängigkeit bei der Ausübung seines oder ihres Amtes dadurch nicht beeinträchtigt wird.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Dienststelle des oder der Rundfunkdatenschutzbeauftragten wird bei der Geschäftsstelle von Rundfunkrat und Verwaltungsrat eingerichtet. Dem oder der Rundfunkdatenschutzbeauftragten ist die für die Erfüllung seiner oder ihrer Aufgaben und Befugnisse notwendige Personal-, Finanz- und Sachausstattung zur Verfügung zu stellen. Die erforderlichen Mittel sind jährlich, öffentlich und gesondert im Haushaltsplan des NDR auszuweisen und dem oder der Rundfunkdatenschutzbeauftragten im Haushaltsvollzug zuzuweisen. Einer Finanzkontrolle durch den Verwaltungsrat unterliegt der oder die Rundfunkdatenschutzbeauftragte nur insoweit, als seine oder ihre Unabhängigkeit bei der Ausübung seines oder ihres Amtes dadurch nicht beeinträchtigt wird.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der oder die Rundfunkdatenschutzbeauftragte ist in der Wahl seiner oder ihrer Mitarbeitenden frei. Sie unterstehen allein seiner oder ihrer Leitung.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 46, 0, 1, '{"type":"paragraph","label":"§ 46","title":"Aufgaben des oder der Rundfunkdatenschutzbeauftragten","children":[{"type":"subparagraph","label":"(1)","text":"Der oder die Rundfunkdatenschutzbeauftragte überwacht die Einhaltung der Datenschutzvorschriften dieses Staatsvertrages, des Medienstaatsvertrages, der Verordnung (EU) 2016/679 und anderer Vorschriften über den Datenschutz bei der gesamten Tätigkeit des NDR und seiner Beteiligungsunternehmen im Sinne des § 42 Absatz 3 Satz 1 des Medienstaatsvertrages . Er oder sie hat die Aufgaben und Befugnisse entsprechend der Artikel 57 und 58 Absatz 1 bis Absatz 5 der Verordnung (EU) 2016/679 . Bei der Zusammenarbeit mit anderen Aufsichtsbehörden hat er oder sie, soweit die Datenverarbeitung zu journalistischen Zwecken betroffen ist, den Informantenschutz zu wahren. Er oder sie kann gegenüber dem NDR keine Geldbußen verhängen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Stellt der oder die Rundfunkdatenschutzbeauftragte Verstöße gegen Vorschriften über den Datenschutz oder sonstige Mängel bei der Verarbeitung personenbezogener Daten fest, so beanstandet er oder sie dies gegenüber dem Intendanten oder der Intendantin und fordert ihn oder sie zur Stellungnahme innerhalb einer angemessenen Frist auf. Gleichzeitig unterrichtet er oder sie den Verwaltungsrat. Von einer Beanstandung und Unterrichtung kann abgesehen werden, wenn es sich um unerhebliche Mängel handelt oder wenn ihre unverzügliche Behebung sichergestellt ist.","children":[]},{"type":"subparagraph","label":"(3)","text":"Die von dem Intendanten oder der Intendantin nach Absatz 2 Satz 1 abzugebende Stellungnahme soll auch eine Darstellung der Maßnahmen enthalten, die aufgrund der Beanstandung des oder der Rundfunkdatenschutzbeauftragten getroffen worden sind. Der Intendant oder die Intendantin leitet dem Verwaltungsrat gleichzeitig eine Abschrift der Stellungnahme gegenüber dem oder der Rundfunkdatenschutzbeauftragten zu.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der oder die Rundfunkdatenschutzbeauftragte erstattet jährlich auch den Organen des NDR den schriftlichen Bericht im Sinne des Artikels 59 der Verordnung (EU) 2016/679 über seine oder ihre Tätigkeit. Der Bericht wird veröffentlicht, wobei eine Veröffentlichung im Online-Angebot des NDR ausreichend ist.","children":[]},{"type":"subparagraph","label":"(5)","text":"Jedermann hat das Recht, sich unmittelbar an den Rundfunkdatenschutzbeauftragten oder die Rundfunkdatenschutzbeauftragte zu wenden, wenn er der Ansicht ist, bei der Verarbeitung seiner personenbezogenen Daten durch den NDR oder seiner Beteiligungsunternehmen im Sinne des Absatz 1 Satz 1 in seinen schutzwürdigen Belangen verletzt zu sein.","children":[]},{"type":"subparagraph","label":"(6)","text":"Der oder die Rundfunkdatenschutzbeauftragte ist sowohl während als auch nach Beendigung seiner oder ihrer Tätigkeit verpflichtet, über die ihm oder ihr während seiner oder ihrer Dienstzeit bekannt gewordenen Angelegenheiten und vertraulichen Informationen Verschwiegenheit zu bewahren.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 47, 0, 1, '{"type":"paragraph","label":"§ 47","title":"Informationszugang","children":[{"type":"subparagraph","label":"(1)","text":"Jede natürliche oder juristische Person mit Sitz in Deutschland hat nach Maßgabe dieser Bestimmung einen Anspruch auf freien Zugang zu den Informationen, über die der NDR als informationspflichtige Stelle verfügt. Von diesem Anspruch sind Informationen, über die der NDR zu journalistisch-redaktionellen Zwecken verfügt, ausgeschlossen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Begriffsbestimmungen:","children":[]},{"type":"item","label":"1.","text":"Informationen sind alle in Schrift-, Bild-, Ton- oder Datenverarbeitungsform oder auf sonstigen Informationsträgern bei informationspflichtigen Stellen vorhandene Zahlen, Daten, Fakten, Erkenntnisse oder sonstige Auskünfte.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Informationsträger sind alle Medien, die Informationen in Schrift-, Bild-, Ton- oder Datenverarbeitungsform oder in sonstiger Form speichern können.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Die Informationspflicht ist die Pflicht, Informationen auf Antrag nach Maßgabe dieser Regelung zugänglich zu machen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"Der NDR verfügt über Informationen, wenn diese bei ihm vorhanden sind oder an anderer Stelle für ihn bereitgehalten werden. Ein Bereithalten liegt vor, wenn der NDR einen Anspruch auf Übermittlung der Informationen hat.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(3)","text":"Informationen werden auf Antrag zugänglich gemacht. Der Antrag kann nur in Textform gestellt werden. Im Antrag sind die beanspruchten Informationen zu bezeichnen. Ist der Antrag zu unbestimmt, so ist der oder die Antragstellende unverzüglich, spätestens innerhalb eines Monats, aufzufordern, den Antrag zu präzisieren. Nach Eingang des präzisierten Antrags beim NDR beginnt die Frist zur Beantwortung des Antrags erneut. Der NDR unterstützt Antragstellende bei der Stellung und Präzisierung von Anträgen.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der NDR hat dem oder der Antragstellenden Auskunft zu erteilen, Akteneinsicht zu gewähren, Kopien, auch durch Versendung, zur Verfügung zu stellen oder die Informationsträger zugänglich zu machen, die die begehrten Informationen enthalten. Wird eine bestimmte Art des Informationszugangs begehrt, so darf diese nur aus wichtigem Grund auf andere Art gewährt werden. In den übrigen Fällen soll die kostengünstigste Form gewählt werden. Sind die Informationen bereits öffentlich zugänglich, kann der NDR darauf verweisen. Handelt es sich um Dokumente, die nur vorübergehend von einer anderen Stelle beigezogen worden sind, so weist der NDR darauf hin und nennt die für die Entscheidung über die Akteneinsicht zuständige Stelle.","children":[]},{"type":"subparagraph","label":"(5)","text":"Liegen die Voraussetzungen des Auskunftsanspruchs vor, sind die Informationen der oder dem Antragstellenden zeitnah, spätestens jedoch binnen eines Monats nach Eingang des Antrags beim NDR zugänglich zu machen. In begründeten Fällen kann die Frist auf höchstens zwei Monate verlängert werden. Der oder die Antragstellende ist unter Angabe der Gründe unverzüglich auf die Fristverlängerung hinzuweisen.","children":[]},{"type":"subparagraph","label":"(6)","text":"Wird der Antrag ganz oder teilweise abgelehnt, ist dies dem oder der Antragstellenden innerhalb der Fristen nach Absatz 5 unter Angabe der Gründe mitzuteilen. Eine Ablehnung liegt auch dann vor, wenn der Informationszugang anders als beantragt gewährt wird. Die Ablehnung kann auf dieselbe Weise mitgeteilt werden, wie der Antrag gestellt wurde. Liegt ein Ablehnungsgrund nach den Absätzen 8 und 9 vor, sind die hiervon nicht betroffenen Informationen zugänglich zu machen, soweit sie ausgesondert werden können. Der oder die Antragstellende ist im Falle einer vollständigen oder teilweisen Ablehnung eines Antrages über die Rechtsschutzmöglichkeiten gegen diese Entscheidung sowie darüber zu belehren, bei welcher Stelle und innerhalb welcher Frist um Rechtsschutz nachgesucht werden kann.","children":[]},{"type":"subparagraph","label":"(7)","text":"Für Streitigkeiten nach dieser Vorschrift ist der Verwaltungsrechtsweg gegeben. Ein Widerspruchsverfahren ist nicht durchzuführen.","children":[]},{"type":"subparagraph","label":"(8)","text":"Soweit die Bekanntgabe der Informationen nachteilige Auswirkungen auf","children":[]},{"type":"item","label":"1.","text":"die Vertraulichkeit der Beratungen der Gremien des NDR oder","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"die Durchführung eines laufenden Gerichtsverfahrens, eines Ermittlungsverfahrens, eines Ordnungswidrigkeitenverfahrens oder eines Disziplinarverfahrens hätte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"ist der Antrag abzulehnen, wenn das schutzwürdige Interesse des NDR an der Geheimhaltung gegenüber dem öffentlichen Bekanntgabeinteresse überwiegt. Der Antrag ist auch abzulehnen, wenn der Antrag offensichtlich missbräuchlich gestellt wurde."},{"type":"subparagraph","label":"(9)","text":"Soweit durch die Bekanntgabe der Information","children":[]},{"type":"item","label":"1.","text":"personenbezogene Daten offenbart würden, deren Vertraulichkeit durch Rechtsvorschrift vorgesehen ist,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Rechte am geistigen Eigentum, insbesondere Urheberrechte, verletzt würden,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Betriebs- oder Geschäftsgeheimnisse zugänglich gemacht würden oder Informationen dem Steuer- oder Statistikgeheimnis unterliegen oder","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"die Interessen einer Person beeinträchtigt würden, die die beantragte Information, ohne rechtlich hierzu verpflichtet werden zu können, dem NDR freiwillig zur Verfügung gestellt hat","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"und das aus den Nummern 1 bis 4 jeweils folgende schutzwürdige Interesse an der Geheimhaltung gegenüber dem öffentlichen Bekanntgabeinteresse überwiegt, ist der Antrag abzulehnen, es sei denn, die jeweils Betroffenen haben zugestimmt. Die Betroffenen sind vor der Entscheidung über die Offenbarung anzuhören."},{"type":"subparagraph","label":"(10)","text":"Für die Bereitstellung von Informationen nach dieser Vorschrift werden Kosten (Gebühren und Auslagen) erhoben. Gebühren werden nicht erhoben für","children":[]},{"type":"item","label":"1.","text":"die Erteilung mündlicher, einfacher schriftlicher und einfacher elektronischer Auskünfte und","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"die Einsichtnahme vor Ort.","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"Die Gebühren sind auch unter Berücksichtigung des Verwaltungsaufwandes so zu bemessen, dass das Recht auf Zugang zu Informationen wirksam in Anspruch genommen werden kann. Das Nähere regelt die Satzung."},{"type":"subparagraph","label":"(11)","text":"Antragstellende, die der Ansicht sind, dass der Informationsanspruch zu Unrecht abgelehnt oder nicht beachtet worden ist oder dass nur eine unzulängliche Antwort gegeben worden ist, können den Rundfunkdatenschutzbeauftragten oder die Rundfunkdatenschutzbeauftragte des NDR anrufen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 48, 0, 1, '{"type":"paragraph","label":"§ 48","title":"Archivierung","children":[{"type":"paragraphText","text":"Der NDR entscheidet in eigener Zuständigkeit, ob Unterlagen dem Staatsarchiv Hamburg angeboten und übergeben oder in eigener Verantwortung archiviert werden."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 49, 0, 1, '{"type":"paragraph","label":"§ 49","title":"Kündigung","children":[{"type":"subparagraph","label":"(1)","text":"Dieser Staatsvertrag kann von jedem Land frühestens zum 31. August 2026 gekündigt werden. Die Kündigungsfrist beträgt zwei Jahre. Wird der Staatsvertrag nicht gekündigt, verlängert er sich stillschweigend um jeweils fünf Jahre. Kündigt ein Land, kann jedes andere innerhalb von drei Monaten nach Zugang der Kündigung erklären, dass es sich dieser anschließt; zwischen den übrigen Ländern bleibt der Staatsvertrag in Kraft. Im Falle der Kündigung durch mindestens drei Länder tritt der Staatsvertrag nach Ablauf der Kündigungsfrist außer Kraft und der NDR als Rundfunkanstalt ist aufgelöst.","children":[]},{"type":"subparagraph","label":"(2)","text":"Nach einer Kündigung oder Auflösung des NDR durch Vereinbarung schließen die Länder einen Staatsvertrag über die Auseinandersetzung.","children":[]},{"type":"subparagraph","label":"(3)","text":"Für den Fall, dass ein Staatsvertrag über die Auseinandersetzung nicht innerhalb eines Jahres abgeschlossen wird, entscheidet ein Schiedsgericht über die Auseinandersetzung. Das Schiedsgericht kann auch eine einstweilige Regelung treffen.","children":[]},{"type":"subparagraph","label":"(4)","text":"Einigen sich die Länder nicht über die Zusammensetzung des Schiedsgerichts, ernennen die Präsidenten oder Präsidentinnen der Oberverwaltungsgerichte der Freien und Hansestadt Hamburg und der Länder Mecklenburg-Vorpommern, Niedersachsen und Schleswig-Holstein gemeinsam ein aus vier Mitgliedern bestehendes Schiedsgericht. Die Schiedsrichter oder die Schiedsrichterinnen müssen die Befähigung zum Richteramt besitzen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 50, 0, 1, '{"type":"paragraph","label":"§ 50","title":"Beitritt","children":[{"type":"paragraphText","text":"Andere Länder können diesem Staatsvertrag beitreten. Der Beitritt bedarf eines Staatsvertrages der beteiligten Länder."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 51, 0, 1, '{"type":"paragraph","label":"§ 51","title":"Übergangsbestimmung","children":[{"type":"paragraphText","text":"Die Zusammensetzung sowie die Rechte und Pflichten der Mitglieder des Rundfunkrats, des Verwaltungsrats und ihrer jeweiligen Ausschüsse, bleiben bis zum Ablauf der zum Zeitpunkt des Inkrafttretens dieses Staatsvertrages laufenden Amtsperioden unberührt."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 52, 0, 1, '{"type":"paragraph","label":"§ 52","title":"Inkrafttreten, Außerkrafttreten","children":[{"type":"subparagraph","label":"(1)","text":"Dieser Staatsvertrag tritt am 1. September 2021 in Kraft. Sind bis zum 31. August 2021 nicht alle Ratifikationsurkunden bei der Senatskanzlei der Freien und Hansestadt Hamburg hinterlegt, wird der Staatsvertrag gegenstandslos.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Senatskanzlei der Freien und Hansestadt Hamburg teilt den übrigen Ländern die Hinterlegung der Ratifikationsurkunden mit.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Staatsvertrag über den Norddeutschen Rundfunk (NDR) vom 17./18. November 1991, der Staatsvertrag über den Datenschutz beim Norddeutschen Rundfunk (NDR-Datenschutz-Staatsvertrag) vom 7. bis 15. Dezember 2017 und der Staatsvertrag über die Veranstaltung von digitalen terrestrischen Hörfunkprogrammen durch den Norddeutschen Rundfunk (NDR-Digitalradio-Staatsvertrag) vom 1./2. Februar 2012, jeweils in der geltenden Fassung, treten zum Zeitpunkt des Inkrafttretens dieses Staatsvertrages außer Kraft.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 53, 0, 1, '{"type":"annex","label":"Anhang","title":"Protokollerklärung aller Länder zum NDR-Staatsvertrag","children":[{"type":"paragraphText","text":"Die Länder bewerten die Integration der arbeitnehmerähnlichen Personen in die Personalvertretung des NDR als einen wichtigen Schritt für die Mitbestimmung im NDR ( § 41 NDR-Staatsvertrag ). Sie nehmen in Aussicht, zeitnah das Mitbestimmungsrecht des NDR insgesamt daraufhin zu überprüfen, ob der Verweis auf das Bundespersonalvertretungsgesetz durch eine für den NDR spezifische Regelung ersetzt werden kann und dabei auch weitere Möglichkeiten der Einbindung der arbeitnehmerähnlichen Personen in das Personalvertretungsregime beim NDR staatsvertraglich zu regeln."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 54, 0, 1, '{"type":"signature","title":"Für den Senat der Freien und Hansestadt Hamburg","text":"Hamburg, den 4. März 2021, gez. Dr. Peter Tschentscher"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 55, 0, 1, '{"type":"signature","title":"Für das Land Mecklenburg-Vorpommern","text":"Schwerin, den 9. März 2021, gez. Manuela Schwesig"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 56, 0, 1, '{"type":"signature","title":"Für das Land Niedersachsen","text":"Hannover, den 5. März 2021, gez. Stephan Weil"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2021-09-01', 57, 0, 1, '{"type":"signature","title":"Für das Land Schleswig-Holstein","text":"Kiel, den 8. März 2021, gez. Daniel Günther"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 0, 0, 1, '{"type":"paragraphText","text":"Das Land Niedersachsen-Holstein, vertreten durch den Ministerpräsidenten, vertreten durch den Ministerpräsidenten, – zusammen in diesem Staatsvertrag „die Länder“ genannt – schließt vorbehaltlich der Zustimmung seiner verfassungsmäßig berufenen Organe den nachstehenden Staatsvertrag:"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 1, 0, 1, '{"type":"paragraph","label":"§ 1","title":"Aufgabe und Rechtsform","children":[{"type":"subparagraph","label":"(1)","text":"Der Norddeutsche Rundfunk (NDR) ist eine gemeinnützige, rechtsfähige Anstalt des öffentlichen Rechts zur Herstellung und Verbreitung von Rundfunkprogrammen und Telemedien in der ehemaligen Freien und Hansestadt Hamburg und den ehemaligen Ländern Niedersachsen und Schleswig-Holstein (Sendegebiet).","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR hat das Recht der Selbstverwaltung. Er gibt sich eine Satzung.","children":[]},{"type":"subparagraph","label":"(3)","text":"Ein Insolvenzverfahren über das Vermögen des NDR findet nicht statt.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 2, 0, 1, '{"type":"paragraph","label":"§ 2","title":"Sitz und regionale Gliederung","children":[{"type":"subparagraph","label":"(1)","text":"Sitz des NDR ist Hamburg.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR unterhält Funkhäuser in Hamburg, Hannover und Kiel (Landesfunkhäuser) sowie Regionalstudios in Niedersachsen und Schleswig-Holstein. Die Regionalstudios sind dem Funkhaus des Landes zugeordnet, in dem sie betrieben werden.","children":[]},{"type":"subparagraph","label":"(3)","text":"Einzelne Verwaltungs-, Produktions- und Programmeinrichtungen sowie redaktionelle Schwerpunktbildungen sollen in allen Ländern vorgesehen werden. Wirtschaftlichkeit und Programmverträglichkeit sind dabei angemessen zu berücksichtigen; dabei sind unternehmerisch sinnvolle Entscheidungen zu treffen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 3, 0, 1, '{"type":"paragraph","label":"§ 3","title":"Landesprogramme","children":[{"type":"subparagraph","label":"(1)","text":"Landesprogramme sind getrennte Programme der Landesfunkhäuser, die für die jeweiligen Länder bestimmt sind. Als Landesprogramme gestalten die Landesfunkhäuser jeweils ein ganztägiges Hörfunkprogramm und ein Regionalprogramm im Fernsehen außerhalb der für die Gemeinschaftsprogramme vorgesehenen Zeiten; Umfang und Struktur dieser Programme müssen den inhaltlichen Anforderungen des Absatzes 3 entsprechen. Für regionale Verbreitungsgebiete kann das jeweilige Landesfunkhaus innerhalb eines Landesprogramms regionale Sendungen verbreiten. Mit Zustimmung des Rundfunkrats, des Verwaltungsrats und des Intendanten oder der Intendantin kann das jeweilige Landesfunkhaus innerhalb eines gemeinschaftlichen Hörfunkprogramms ein weiteres Landesprogramm senden (Landesfenster).","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Landesfunkhäuser gestalten die Landesprogramme jeweils in eigener Verantwortung; der Direktor oder die Direktorin des jeweiligen Landesfunkhauses ist für die Landesprogramme verantwortlich. Der Intendant oder die Intendantin bleibt für die Einhaltung der Programmanforderungen (§§ 5, 7 bis 10) verantwortlich. Die Einstellung und Entlassung von Mitarbeitenden des Landesfunkhauses erfolgt unbeschadet der Gesamtverantwortung des Intendanten oder der Intendantin grundsätzlich in eigener Zuständigkeit. Bei Angestellten in leitender Funktion sowie bei Programmmitarbeitenden erfolgt die Einstellung und Entlassung auf Vorschlag des Intendanten oder der Intendantin mit Zustimmung des Direktors oder der Direktorin; entsprechendes gilt für Mitarbeitende des Landesfunkhauses, die den zentralen Fachdirektionen unterstellt sind.","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Landesprogramme der Landesfunkhäuser sollen das öffentliche Geschehen, die politischen Ereignisse sowie das kulturelle und soziale Leben insbesondere in dem jeweiligen Land darstellen.","children":[]},{"type":"subparagraph","label":"(4)","text":"Die Landesfunkhäuser können die gemeinsame Gestaltung von Teilen der Landesprogramme vereinbaren. Soweit dies nicht nur für einzelne Sendungen erfolgen soll, ist dafür die Zustimmung des Rundfunkrats erforderlich.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 4, 0, 1, '{"type":"paragraph","label":"§ 4","title":"Freiheit und öffentliche Verantwortung des Rundfunks","children":[{"type":"paragraphText","text":"Der NDR veranstaltet und verbreitet Rundfunk als Medium und Faktor des Prozesses freier, individueller und öffentlicher Meinungsbildung und als Sache der Allgemeinheit. Die im Sendegebiet bedeutsamen politischen, weltanschaulichen und gesellschaftlichen Kräfte und Gruppen tragen dazu bei, dass der NDR seine Aufgaben eigenverantwortlich im Rahmen des geltenden Rechts und auf der Grundlage der verfassungsrechtlich garantierten Rundfunkfreiheit erfüllt."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 5, 0, 1, '{"type":"paragraph","label":"§ 5","title":"Angebotsauftrag","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR hat den Rundfunkteilnehmern und Rundfunkteilnehmerinnen einen objektiven und umfassenden Überblick über das internationale, europäische, nationale und länderbezogene Geschehen in allen wesentlichen Lebensbereichen zu geben. Seine Angebote haben der Information, Bildung, Beratung und Unterhaltung zu dienen. Er hat Beiträge insbesondere zur Kultur anzubieten und ist berechtigt, sich an Filmförderungen zu beteiligen. Er kann auch Spartenprogramme veranstalten.","children":[]},{"type":"subparagraph","label":"(2)","text":"Norddeutschland und die Vielfalt seiner Regionen, ihre Kultur sowie ihre Regional- und Minderheitensprachen sind in den Angeboten des NDR regelmäßig und angemessen zu berücksichtigen. Der NDR soll zu diesem Zweck und zur Erhaltung kultureller Identität sein Angebot grundsätzlich in den vier Ländern seines Sendegebiets herstellen.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der NDR erlässt Richtlinien zur näheren Ausgestaltung seines Angebotsauftrags. Die Richtlinien sind in geeigneter Art und Weise zu veröffentlichen. Der NDR veröffentlicht alle zwei Jahre einen Bericht über die Erfüllung seines Angebotsauftrags, über die Qualität und Quantität seiner Angebote sowie die geplanten Schwerpunkte der jeweils anstehenden programmlichen Leistungen.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der NDR ist mit der Erbringung von Dienstleistungen von allgemeinem wirtschaftlichem Interesse im Sinne des Artikels 106 Absatz 2 des Vertrages über die Arbeitsweise der Europäischen Union (ABl. EU Nr. C 202 S. 47) auch betraut, soweit er zur Erfüllung seines Auftrags gemäß Absatz 1 bei der Herstellung und Verbreitung von Angeboten im Sinne des § 6 Absatz 1 mit anderen öffentlich-rechtlichen Rundfunkanstalten zusammenarbeitet. Die Betrauung gilt insbesondere für die Bereiche Produktion, Produktionsstandards, Programmrechteerwerb, Programmaustausch, Verbreitung und Weiterverbreitung von Angeboten, Beschaffungswesen, Sendernetzbetrieb, informationstechnische und sonstige Infrastrukturen, Vereinheitlichung von Geschäftsprozessen, Beitragsservice und allgemeine Verwaltung. Von der Betrauung nicht umfasst sind kommerzielle Tätigkeiten. Kommerzielle Tätigkeiten sind Betätigungen, bei denen Leistungen auch für Dritte im Wettbewerb angeboten werden, insbesondere Werbung und Sponsoring, Verwertungsaktivitäten, Merchandising, Produktion für Dritte und die Vermietung von Senderstandorten an Dritte.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 6, 0, 1, '{"type":"paragraph","label":"§ 6","title":"Wahrnehmung des Angebotsauftrags, Sendekapazitäten","children":[{"type":"subparagraph","label":"(1)","text":"Angebote des NDR sind Rundfunkprogramme (Hörfunk- und Fernsehprogramme) und Telemedienangebote. Die ihm bisher eingeräumten Sendekapazitäten (Frequenzen und Kanäle) stehen ihm weiterhin zur Verfügung. Der NDR kann bei Fortfall einzelner ihm zustehender Sendekapazitäten gleichwertigen Ersatz verlangen. Er darf nicht ohne die Zustimmung des oder der jeweils betroffenen Länder die Nutzung eigener Sendekapazitäten anderen Rundfunkveranstaltern überlassen oder zu deren Gunsten auf sie verzichten.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR veranstaltet bis zu drei Hörfunkprogramme, die terrestrisch in digitaler Technik verbreitet werden. Die Programme haben die folgenden Schwerpunkte:","children":[]},{"type":"item","label":"1.","text":"Ein ergänzendes Musikprogramm sowie musikjournalistische Beiträge mit Berücksichtigung der norddeutschen Musikszene,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Liveübertragungen von Veranstaltungen, Seewetterberichte sowie Sendungen für Menschen mit Migrationshintergrund,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"ein ergänzendes Musikprogramm mit dem Schwerpunkt Schlager und ähnliche deutschsprachige Produktionen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"Die Schwerpunkte aus den Nummern 1 und 2 können in einem gemeinsamen Programm bei Aufgabe eines Programms zusammengelegt werden. Die Programme nach den Nummern 1 bis 3 sind werbefrei. Der NDR ist berechtigt, in Wahrnehmung seiner Angebote nach § 5 dieses Staatsvertrages und unter den Voraussetzungen des § 29 Absatz 2 Satz 3 des Medienstaatsvertrages den Schwerpunkt nach Absatz 2 Satz 1 Nummer 3 nach Zustimmung des Rundfunkrats gegen einen anderen Schwerpunkt oder auch gegen ein Kooperationsprogramm auszutauschen, das terrestrisch in digitaler Technik verbreitet wird. Für diese Entscheidung ist dem Rundfunkrat ein Programmkonzept vorzulegen. Der NDR informiert die nach § 39 Absatz 1 aufsichtsführende Regierung rechtzeitig über einen geplanten Austausch und das Vorliegen der Voraussetzungen für einen Austausch nach diesem Absatz und veröffentlicht mindestens ein halbes Jahr vor dem Start des neuen Programms Informationen zum geplanten Programmschwerpunkt auf den Internetseiten des NDR."},{"type":"subparagraph","label":"(3)","text":"Der NDR kann bei der Wahrnehmung seiner Aufgaben in sendetechnischer, programmlicher und finanzieller Hinsicht ebenso wie die anderen Rundfunkunternehmen im Geltungsbereich des Grundgesetzes alle für Rundfunkunternehmen zur Verfügung stehenden Möglichkeiten nutzen. Eingeräumte Übertragungskapazitäten sind, soweit möglich, nach den Grundsätzen der Wirtschaftlichkeit und Sparsamkeit einzusetzen. Dabei sollen Doppel- und Mehrfachnutzungen vermieden werden.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der NDR hat sicherzustellen, dass sein Sendegebiet gleichwertig versorgt wird. Die Sendekapazitäten, die der NDR für die Grundversorgung mit Rundfunk im Umfang der bestehenden Programme benötigt, sind im Rahmen der technischen Möglichkeiten bereitzustellen. Die Zuweisung von Satellitenkanälen für weitere Hörfunk- und Fernsehprogramme erfolgt auf der Grundlage einer Vereinbarung der Länder; die Zuweisung von terrestrischen Sendekapazitäten für weitere Hörfunk- und Fernsehprogramme erfolgt nach Maßgabe der jeweiligen landesrechtlichen Bestimmungen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 7, 0, 1, '{"type":"paragraph","label":"§ 7","title":"Angebotsgrundsätze","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR ist in seinen Angeboten an die verfassungsmäßige Ordnung gebunden. Er trägt zur Verwirklichung der freiheitlichen demokratischen Grundordnung bei.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR hat in seinen Angeboten die Würde des Menschen zu achten und zu schützen. Er soll dazu beitragen, die Achtung vor Leben, Freiheit und körperlicher Unversehrtheit, vor Glauben und Meinung anderer zu stärken und sich für die Erhaltung von Natur und Umwelt sowie die Grundsätze der Nachhaltigkeit einzusetzen. Das Angebot des NDR soll die Zusammengehörigkeit innerhalb Deutschlands und Europas sowie die internationale Verständigung fördern, für die Friedenssicherung und den Minderheitenschutz eintreten, die Gleichstellung von Frau und Mann unterstützen und zur sozialen Gerechtigkeit beitragen. Die sittlichen und religiösen Überzeugungen der Bevölkerung sind zu achten.","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Vorschriften der allgemeinen Gesetze und die gesetzlichen Bestimmungen zum Schutze der Jugend und des Rechts der persönlichen Ehre sind einzuhalten.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 8, 0, 1, '{"type":"paragraph","label":"§ 8","title":"Gestaltung des Angebots","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR ist in seinen Angeboten zur Wahrheit verpflichtet. Er hat sicherzustellen, dass","children":[]},{"type":"item","label":"1.","text":"die bedeutsamen politischen, weltanschaulichen und gesellschaftlichen Kräfte und Gruppen aus dem Sendegebiet in den Angeboten angemessen zu Wort kommen können,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"das Angebot nicht einseitig einer Partei oder Gruppe, einer Interessengemeinschaft, einem Bekenntnis oder einer Weltanschauung dient und","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"in seiner Berichterstattung die Auffassungen der wesentlich betroffenen Personen, Gruppen oder Stellen angemessen und fair berücksichtigt werden. Wertende und analysierende Einzelbeiträge haben dem Gebot journalistischer Fairness und in ihrer Gesamtheit der Vielfalt der Meinungen zu entsprechen. Ziel aller Informationssendungen ist es, sachlich und umfassend zu unterrichten und damit zur selbständigen Urteilsbildung der Bürger und Bürgerinnen beizutragen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(2)","text":"Berichterstattung und Informationssendungen haben den anerkannten journalistischen Grundsätzen, auch beim Einsatz virtueller Elemente, zu entsprechen. Sie müssen unabhängig und sachlich sein. Nachrichten sind vor ihrer Verbreitung mit der nach den Umständen gebotenen Sorgfalt auf Wahrheit und Herkunft zu prüfen. Kommentare sind von der Berichterstattung deutlich zu trennen und unter Nennung des Verfassers oder der Verfasserin als solche zu kennzeichnen.","children":[]},{"type":"subparagraph","label":"(3)","text":"Soweit der NDR Meinungsumfragen wiedergibt, ist ausdrücklich anzugeben, ob sie repräsentativ sind.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 9, 0, 1, '{"type":"paragraph","label":"§ 9","title":"Kurzberichterstattung","children":[{"type":"paragraphText","text":"§ 14 des Medienstaatsvertrages findet entsprechend Anwendung."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 10, 0, 1, '{"type":"paragraph","label":"§ 10","title":"Unzulässige Angebote, Jugendschutz","children":[{"type":"paragraphText","text":"Die für den öffentlich-rechtlichen Rundfunk geltenden Bestimmungen des Jugendmedienschutz-Staatsvertrages finden Anwendung."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 11, 0, 1, '{"type":"paragraph","label":"§ 11","title":"Zusammenarbeit, Druckwerke","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR kann im Rahmen seiner Aufgaben Vereinbarungen mit anderen Rundfunkveranstaltern zum Zweck gemeinsamer Angebotsgestaltung oder der gemeinsamen Durchführung bestimmter Aufgaben abschließen. Er kann sich an internationalen, insbesondere europäischen Angeboten beteiligen; diese Beteiligung bedarf einer Vereinbarung der Länder.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR kann zur Veranstaltung und Verbreitung von Angeboten mit Dritten zusammenarbeiten und sich zu diesem Zweck an Unternehmen beteiligen (§ 37). Die Bestimmungen der §§ 7 bis 10 sowie des § 3 Absatz 3 sind dabei besonders zu beachten. Insbesondere ist sicherzustellen, dass die Mitwirkung des NDR jeweils in einem abgrenzbaren und ihm zurechenbaren Anteil an dem jeweiligen Gemeinschaftsangebot besteht.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der NDR kann zur Erfüllung seiner Aufgaben angebotsbegleitend Druckwerke mit angebotsbezogenem Inhalt anbieten.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 12, 0, 1, '{"type":"paragraph","label":"§ 12","title":"Verlautbarungsrecht","children":[{"type":"paragraphText","text":"Der NDR hat der Bundesregierung und den Regierungen der Länder für amtliche Verlautbarungen angemessene Sendezeit unverzüglich und unentgeltlich einzuräumen. Für Inhalt und Gestaltung der Sendungen ist diejenige Regierung verantwortlich, der die Sendezeit zugebilligt worden ist."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 13, 0, 1, '{"type":"paragraph","label":"§ 13","title":"Gegendarstellung","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR ist verpflichtet, eine Gegendarstellung der Person, Gruppe oder Stelle zu verbreiten, die durch eine in einem Angebot aufgestellte Tatsachenbehauptung betroffen ist. Die Pflicht zur Verbreitung einer Gegendarstellung besteht nicht, wenn die betroffene Person, Gruppe oder Stelle kein berechtigtes Interesse an der Verbreitung hat oder wenn die Gegendarstellung ihrem Umfang nach nicht angemessen ist. Überschreitet die Gegendarstellung nicht den Umfang des beanstandeten Angebotsteils, gilt sie als angemessen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Gegendarstellung muss unverzüglich, bei beanstandeten Sendungen spätestens innerhalb von zwei Monaten beziehungsweise drei Monaten nach der erstmaligen Einstellung des Telemediums, schriftlich verlangt werden und von dem oder der Betroffenen oder seinem oder ihrem gesetzlichen Vertreter oder Vertreterin unterzeichnet sein. Die Gegendarstellung muss das beanstandete Angebot und die Tatsachenbehauptung bezeichnen, sich auf tatsächliche Angaben beschränken und darf keinen strafbaren Inhalt haben.","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Gegendarstellung muss unverzüglich innerhalb desselben Angebots verbreitet werden, in welchem die beanstandete Tatsachenbehauptung erfolgt ist. Die Verbreitung erfolgt ohne Einschaltungen und Weglassungen. Eine Erwiderung auf die verbreitete Gegendarstellung muss sich auf tatsächliche Angaben beschränken.","children":[]},{"type":"subparagraph","label":"(4)","text":"Im Fernsehen und Hörfunk muss die Gegendarstellung innerhalb desselben Programms und desselben Sendungsangebots wie die beanstandete Tatsachenbehauptung sowie zur gleichen Tageszeit verbreitet werden. Ist dies nicht möglich, ist die Gegendarstellung in einer vergleichbaren Sendung sowie zu einer angemessenen Sendezeit zu verbreiten. Ist dies ebenfalls nicht möglich, muss die Gegendarstellung in sonstiger angemessener Art und Weise erfolgen.","children":[]},{"type":"subparagraph","label":"(5)","text":"In Telemedienangeboten muss die Gegendarstellung in dem gleichen Telemedium aufgenommen werden. Die Gegendarstellung ist in gleicher Aufmachung wie die Tatsachenbehauptung anzubieten. Die Gegendarstellung ist so lange wie die Tatsachenbehauptung in unmittelbarer Verknüpfung mit ihr anzubieten. Wird die Tatsachenbehauptung nicht mehr angeboten oder endet das Angebot vor Aufnahme der Gegendarstellung, so ist die Gegendarstellung an vergleichbarer Stelle so lange anzubieten, wie die ursprünglich angebotene Tatsachenbehauptung.","children":[]},{"type":"subparagraph","label":"(6)","text":"Die Gegendarstellung wird unentgeltlich verbreitet. Dies gilt nicht, wenn sich die Gegendarstellung gegen eine Tatsachenbehauptung richtet, die in einer Werbesendung verbreitet worden ist.","children":[]},{"type":"subparagraph","label":"(7)","text":"Verweigert der NDR die Verbreitung einer Gegendarstellung, entscheiden auf Antrag des oder der Betroffenen die ordentlichen Gerichte. Die Vorschriften der Zivilprozessordnung über das Verfahren auf Erlass einer einstweiligen Verfügung gelten entsprechend. Eine Gefährdung des Anspruchs braucht nicht glaubhaft gemacht zu werden. Ein Verfahren in der Hauptsache findet nicht statt.","children":[]},{"type":"subparagraph","label":"(8)","text":"Die Absätze 1 bis 7 gelten nicht für wahrheitsgetreue Berichte über öffentliche Sitzungen des Europäischen Parlaments, der gesetzgebenden Organe des Bundes, der Länder und der Vertretungen der kommunalen Gebietskörperschaften, der Gerichte sowie für Sendungen nach den §§ 12 und 16. Zu einer Gegendarstellung kann eine Gegendarstellung nicht verlangt werden.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 14, 0, 1, '{"type":"paragraph","label":"§ 14","title":"Eingaberecht","children":[{"type":"subparagraph","label":"(1)","text":"Jeder oder jede hat das Recht, sich mit Eingaben und Anregungen zu den Angeboten an den Rundfunkrat sowie an den Intendanten oder die Intendantin oder - bezogen auf die Angebote der jeweiligen Landesfunkhäuser - an den jeweiligen Landesrundfunkrat sowie an den jeweiligen Landesfunkhausdirektor oder die jeweilige Landesfunkhausdirektorin zu wenden.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR stellt sicher, dass Beschwerden zu den Angeboten, in denen die Verletzung von Angebotsgrundsätzen behauptet wird, innerhalb angemessener Frist schriftlich beschieden werden. Wird die Beschwerde über ein Angebot in Textform eingelegt, so genügt auch für deren Bescheidung die Textform.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 15, 0, 1, '{"type":"paragraph","label":"§ 15","title":"Beweissicherung","children":[{"type":"subparagraph","label":"(1)","text":"Die Angebote des NDR sind in Ton, Bild und Text vollständig aufzuzeichnen beziehungsweise zu speichern sowie aufzubewahren. Bei Sendungen, die unter Verwendung einer Aufzeichnung oder eines audiovisuellen Beitrags ausgestrahlt werden, ist die Aufzeichnung oder der audiovisuelle Beitrag aufzubewahren, bei Telemedienangeboten die einzelnen Telemedien. Nach Ablauf von drei Monaten seit dem Tag der Verbreitung können Aufzeichnungen, audiovisuelle Beiträge und Telemedien gelöscht beziehungsweise vernichtet werden, soweit keine Beanstandungen mitgeteilt worden sind. Bei einer Beanstandung kann die Aufzeichnung, der audiovisuelle Beitrag oder das Telemedium erst gelöscht beziehungsweise vernichtet werden, wenn die Beanstandung durch rechtskräftige gerichtliche Entscheidung, durch gerichtlichen Vergleich oder auf andere Weise erledigt ist.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Rundfunkrat kann mit der Zustimmung von zwei Dritteln seiner anwesenden Mitglieder Ausnahmen von der Aufzeichnungs- beziehungsweise Speicherungs- und Aufbewahrungspflicht nach Absatz 1 zulassen.","children":[]},{"type":"subparagraph","label":"(3)","text":"Wer schriftlich glaubhaft macht, durch ein Angebot in seinen oder ihren Rechten berührt zu sein, kann Einsicht in die betreffenden Aufzeichnungen, audiovisuellen Beiträge und Telemedien verlangen. Dieser Anspruch ist ausgeschlossen, wenn er nicht innerhalb von drei Monaten seit dem Tag der Verbreitung des beanstandeten Angebotsteils geltend gemacht worden ist. Über das Verlangen ist unverzüglich schriftlich zu entscheiden. Auf Verlangen sind Antragstellenden auf deren Kosten Vervielfältigungen oder Abschriften des beanstandeten Angebotsteils zu übersenden.","children":[]},{"type":"subparagraph","label":"(4)","text":"Jedes Mitglied des Rundfunkrats oder seiner Ausschüsse hat das Recht, die Aufbewahrung einer Aufzeichnung, eines audiovisuellen Beitrags oder eines Telemediums über die Frist des Absatzes 1 hinaus bis zur nächsten Rundfunkratssitzung zu verlangen. Der Rundfunkrat oder einer seiner Ausschüsse entscheidet auf Antrag eines Mitglieds über die Verlängerung der Aufbewahrungsfrist.","children":[]},{"type":"subparagraph","label":"(5)","text":"Der NDR hat auf Verlangen Namen und Dienstanschrift des Intendanten oder der Intendantin und in den Fällen des Absatzes 3 Name und Dienstanschrift des oder der für den beanstandeten Angebotsteil Verantwortlichen bekannt zu geben.","children":[]},{"type":"subparagraph","label":"(6)","text":"Im Rahmen der Rechtsaufsicht nach § 39 kann jedes der Länder Einsicht in Aufzeichnungen, audiovisuelle Beiträge und Telemedien nach Absatz 1 verlangen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 16, 0, 1, '{"type":"paragraph","label":"§ 16","title":"Besondere Sendezeiten","children":[{"type":"subparagraph","label":"(1)","text":"Den Parteien und Vereinigungen, für die in den Ländern ein Wahlvorschlag zu den Landesparlamenten, zum Deutschen Bundestag oder zum Europäischen Parlament zugelassen worden ist, sind angemessene Sendezeiten zur Vorbereitung von Wahlen einzuräumen, soweit sie mit einer Landesliste oder in mindestens der Hälfte der Wahlkreise eines Landes mit eigenen Wahlvorschlägen an der Wahl teilnehmen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Den Kirchen und den anderen über das gesamte Sendegebiet verbreiteten Religionsgemeinschaften des öffentlichen Rechts sind auf Wunsch angemessene Sendezeiten für die Übertragung gottesdienstlicher Handlungen und Feierlichkeiten sowie sonstiger religiöser Sendungen, auch solcher über Fragen ihrer öffentlichen Verantwortung, zu gewähren. Für die Jüdischen Gemeinden gilt Entsprechendes. Dem NDR steht es frei, vergleichbare Bedarfe anderer Religionsgemeinschaften entsprechend ihrer Bedeutung und ihrem Verbreitungsgrad in der Bevölkerung bei seiner Programmgestaltung zu berücksichtigen , sofern sich die jeweilige Religionsgemeinschaft nicht gegen die Grundwerte des Grundgesetzes richtet .","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Vorschriften der allgemeinen Gesetze und die gesetzlichen Bestimmungen zum Schutze der Jugend und des Rechts der persönlichen Ehre sind einzuhalten.","children":[]},{"type":"subparagraph","label":"(4)","text":"Für Inhalt und Gestaltung der Sendungen ist derjenige oder diejenige verantwortlich, dem oder der die Sendezeit zugebilligt worden ist.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 17, 0, 1, '{"type":"paragraph","label":"§ 17","title":"Organe","children":[{"type":"subparagraph","label":"(1)","text":"Organe des NDR sind:","children":[]},{"type":"item","label":"1.","text":"der Rundfunkrat,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"der Verwaltungsrat,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"der Intendant oder die Intendantin,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"die Landesrundfunkräte, bezogen auf die Landesprogramme.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Mitgliedschaft im Rundfunkrat und die Mitgliedschaft im Verwaltungsrat schließen sich gegenseitig aus.","children":[]},{"type":"subparagraph","label":"(3)","text":"Angestellte oder Mitarbeitende des NDR können nicht Mitglied des Rundfunkrats oder des Verwaltungsrats sein.","children":[]},{"type":"subparagraph","label":"(4)","text":"Mitglieder der gesetzgebenden und beschließenden Organe der Europäischen Union, des Europarates, des Bundes oder eines der Länder können dem Rundfunkrat mit Ausnahme seiner Mitglieder nach § 18 Absatz 1 Satz 2 Nummer 1 und dem Verwaltungsrat nicht angehören.","children":[]},{"type":"subparagraph","label":"(5)","text":"Mitglied des Rundfunkrats und des Verwaltungsrats kann nicht sein, wer seinen Hauptwohnsitz außerhalb des Sendegebiets des NDR hat, wer Inhaber oder Inhaberin, Gesellschafter oder Gesellschafterin eines privaten Rundfunkveranstalters ist, wer Organ einer Landesmedienanstalt oder eines privaten Rundfunkveranstalters ist oder einem Organ angehört, in einem Arbeits- oder Dienstverhältnis zu diesen steht oder für diese als arbeitnehmerähnliche Person im Sinne des § 12a des Tarifvertragsgesetzes tätig ist.","children":[]},{"type":"subparagraph","label":"(6)","text":"Kein Mitglied des Rundfunkrats oder des Verwaltungsrats darf als Inhaber oder Inhaberin, Gesellschafter oder Gesellschafterin, Vorstandsmitglied, Angestellter oder Angestellte oder Vertreter oder Vertreterin eines Unternehmens unmittelbar oder mittelbar mit dem NDR für eigene oder fremde Rechnung Rechtsgeschäfte abschließen. Dies gilt auch für Unternehmen, die gemeinnütziger Art sind.","children":[]},{"type":"subparagraph","label":"(7)","text":"Dem Rundfunkrat und dem Verwaltungsrat darf nur angehören, wer zu den Landesparlamenten wählbar ist. Das von dem Niedersächsischen Integrationsrat (NIR) gemäß § 18 Absatz 1 Satz 2 Nummer 15 entsandte Mitglied darf Ausländer oder Ausländerin sein.","children":[]},{"type":"subparagraph","label":"(8)","text":"Die Mitglieder des Rundfunkrats und des Verwaltungsrats sind ehrenamtlich tätig. Die Vorschriften des § 20 Absatz 4 und des § 25 Absatz 4 bleiben unberührt.","children":[]},{"type":"subparagraph","label":"(9)","text":"Die Mitgliedschaft einer Person in den Gremien des NDR ist auf insgesamt drei Amtsperioden und in einem Gremium auf zwei Amtsperioden begrenzt. Die seit dem Jahr 2013 abgeleisteten Amtsperioden sind in die Berechnung mit einzubeziehen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 18, 0, 1, '{"type":"paragraph","label":"§ 18","title":"Zusammensetzung des Rundfunkrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Rundfunkrat besteht aus höchstens 58 Mitgliedern. Von ihnen entsenden","children":[]},{"type":"item","label":"1.","text":"höchstens elf Mitglieder die in den Landesparlamenten der Länder mit Fraktionen vertretenen Parteien, davon","level":0,"numberingStyle":"decimal","children":[{"type":"item","label":"a)","text":"neun Mitglieder die in den gesetzgebenden Körperschaften der Länder vertretenen Parteien, davon vier aus Niedersachsen, zwei aus Hamburg und drei aus Schleswig-Holstein, entsprechend ihrem Stärkeverhältnis nach dem Höchstzahlverfahren d’Hondt, sowie","level":1,"numberingStyle":"lower-latin","children":[]},{"type":"item","label":"b)","text":"je ein Mitglied die nach der Zahl ihrer Wählerinnen und Wähler in den jeweiligen Ländern stärkste und zweitstärkste Fraktion der in den Landesparlamenten vertretenen Parteien, auf die nach dem Höchstzahlverfahren d''Hondt kein Sitz im Rundfunkrat entfallen ist; maßgebend sind die Ergebnisse der Wahlen zu den Landesparlamenten vor dem jeweils ersten Zusammentritt des Rundfunkrats,","level":1,"numberingStyle":"lower-latin","children":[]}]},{"type":"item","label":"2.","text":"zwei Mitglieder die evangelischen Kirchen und zwei Mitglieder die römisch-katholische Kirche, davon ein Mitglied aus Hamburg, zwei Mitglieder aus Niedersachsen und ein Mitglied aus Schleswig-Holstein,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"ein Mitglied die Jüdische Gemeinde in Hamburg,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"vier Mitglieder der Deutsche Gewerkschaftsbund, ein Mitglied die Vereinte Dienstleistungsgewerkschaft (Ver.di), ein Mitglied der Deutsche Beamtenbund, davon vier aus Niedersachsen und je eines aus Hamburg und Schleswig-Holstein,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5.","text":"drei Mitglieder die Arbeitgeberverbände, davon zwei aus dem Bereich der Industrie und eines aus dem Bereich des Handels, ein Mitglied die Handwerksverbände, ein Mitglied die Verbände der Freien Berufe, und zwar drei aus Niedersachsen und je eines aus Hamburg und Schleswig-Holstein, dabei im Falle Hamburgs für Industrie, Handel und Handwerk an Stelle der Landesvereinigungen jeweils die Kammer,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"6.","text":"ein Mitglied ein Bauernverband aus Niedersachsen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"7.","text":"drei Mitglieder die Landesfrauenräte und Landesarbeitsgemeinschaften, -verbände und -initiativen der Frauen, und zwar je eines aus Hamburg, Niedersachsen und Schleswig-Holstein,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"8.","text":"je ein Mitglied der Landessportbund aus Niedersachsen und der Landessportbund aus Schleswig-Holstein,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"9.","text":"ein Mitglied die Arbeitsgemeinschaft der kommunalen Spitzenverbände Niedersachsens,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"10.","text":"ein Mitglied ein Haus- und Grundeigentümerverein e. V. aus Niedersachsen, ein Mitglied der Deutsche Mieterbund, Landesverband Schleswig-Holstein e. V., sowie ein Mitglied die in Hamburg mit der Verbraucherberatung betraute Institution,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"11.","text":"ein Mitglied die Landesarbeitsgemeinschaft der Freien Wohlfahrtspflege in Niedersachsen, ein Mitglied die Arbeiterwohlfahrt, Landesverband Schleswig-Holstein e. V., ein Mitglied das Diakonische Werk aus Hamburg und ein Mitglied der Deutsche Caritasverband e. V. aus Niedersachsen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"12.","text":"ein Mitglied der Deutsche Kinderschutzbund e. V. aus Schleswig-Holstein, ein Mitglied der Landesjugendring aus Niedersachsen, ein Mitglied der Landeselternrat aus Niedersachsen, ein Mitglied die Erwachsenenbildungsorganisationen aus Niedersachsen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"13.","text":"ein Mitglied Robin Wood e. V. aus Hamburg, ein Mitglied der BUND aus Niedersachsen, ein Mitglied der Landesnaturschutzverband Schleswig-Holstein e. V. und ein Mitglied der Landesverband Bürgerinitiativen Umweltschutz aus Niedersachsen, ein Mitglied ein Heimatverband aus Schleswig-Holstein,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"14.","text":"ein Mitglied die Arbeitsgruppe Bildende Kunst aus Hamburg, ein Mitglied der Verband Deutscher Schriftstellerinnen und Schriftsteller (VS) in Niedersachsen und ein Mitglied der Landesmusikrat Schleswig-Holstein e. V.,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"15.","text":"ein Mitglied der SoVD-Landesverband Niedersachsen e. V., ein Mitglied der Niedersächsische Integrationsrat (NIR) und ein Mitglied der Landesseniorenrat Niedersachsen e. V.,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"16.","text":"ein Mitglied der Verband der Opfer des Stalinismus aus Niedersachsen und ein Mitglied die Aktion Sühnezeichen aus Niedersachsen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(2)","text":"Bei der Entsendung der Mitglieder sind Frauen und Männer gleichermaßen zu berücksichtigen. Sofern zu Beginn der Amtsperiode ein neues Mitglied entsandt wird, muss einem männlichen Mitglied eine Frau und einem weiblichen Mitglied ein Mann nachfolgen. Wird während der laufenden Amtsperiode ein neues Mitglied entsandt, findet der Wechsel nach Satz 2 nicht statt. Sofern einer Organisation oder einer Gruppe zwei oder mehr Entsenderechte zustehen, sind mindestens je eine Frau und ein Mann zu entsenden. Kann eine Organisation oder Gruppe aufgrund ihrer Zusammensetzung die Anforderungen der Sätze 2 bis 4 nicht erfüllen, ist dies gegenüber dem Vorsitz des Rundfunkrats bei der Benennung des Mitglieds schriftlich zu begründen; der Vorsitz des Rundfunkrats entscheidet, ob auf dieser Grundlage eine Ausnahme zuzulassen ist. Die Entsendung eines diversen Mitglieds ist jederzeit möglich.","children":[]},{"type":"subparagraph","label":"(3)","text":"Kommt zwischen den nach Absatz 1 Satz 2 Nummern 2, 4 und 5 entsendungsberechtigten Organisationen eine Einigung über die Länderzuordnung nicht innerhalb einer Frist von zwei Monaten nach der Aufforderung zur Benennung der Mitglieder zustande, entscheidet darüber das Präsidium des Parlaments des nach § 39 aufsichtsführenden Landes - im Fall einer Einigung zwischen den Verbänden, Initiativen und Arbeitsgemeinschaften des Absatz 1 Satz 2 Nummer 7 entscheidet das Präsidium des Parlaments des jeweils entsendeberechtigten Landes auf der Grundlage von Vorschlägen dieser Organisationen.","children":[]},{"type":"subparagraph","label":"(4)","text":"Die Organisationen und Gruppen entsenden die Mitglieder, auch unter Beachtung von Absatz 2, in eigener Verantwortung. Eine einmalige Wiederentsendung in den Rundfunkrat ist zulässig. Der oder die Vorsitzende des Rundfunkrats fordert neun Monate vor Ablauf der Amtsperiode des Gremiums die in Absatz 1 genannten Organisationen und Gruppen auf, das zu entsendende Mitglied dem Rundfunkratsvorsitz zu benennen. Er oder sie stellt die ordnungsgemäße Entsendung fest.","children":[]},{"type":"subparagraph","label":"(5)","text":"Solange und soweit Mitglieder in den Rundfunkrat nicht entsandt werden, verringert sich die Mitgliederzahl entsprechend. Scheidet ein Mitglied des Rundfunkrats vorzeitig aus, ist für den Rest der Amtsperiode ein Nachfolger oder eine Nachfolgerin nach den für die Entsendung des ausgeschiedenen Mitglieds geltenden Vorschriften zu bestimmen.","children":[]},{"type":"subparagraph","label":"(6)","text":"Kann eine nach Absatz 1 entsendungsberechtigte Organisation oder Gruppe die ihr zugewiesenen Aufgaben im Rundfunkrat aus tatsächlichen oder rechtlichen Gründen auf Dauer nicht mehr wahrnehmen, so entscheidet auf Antrag des Rundfunkrats das Parlament des Landes, in dem diese Organisation oder Gruppe ihren Sitz hat, über die ersatzweise Entsendung. Die Auswahl wird unter Organisationen oder Gruppen mit im Wesentlichen gleichartiger gesellschaftlicher Aufgabenstellung getroffen.","children":[]},{"type":"subparagraph","label":"(7)","text":"Die Landesregierungen überprüfen die Zusammensetzung des Rundfunkrats gemäß Absatz 1 Satz 2 rechtzeitig vor Ablauf jeder Amtsperiode darauf, ob die Zusammensetzung eine sachgerechte, der bestehenden Vielfalt prinzipiell Rechnung tragende Bestimmung und Gewichtung der maßgeblichen gesellschaftlichen Kräfte noch gewährleistet, und legen den Parlamenten einen Vorschlag zur Zusammensetzung für die nächste Amtsperiode vor.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 19, 0, 1, '{"type":"paragraph","label":"§ 19","title":"Aufgaben des Rundfunkrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Rundfunkrat soll die Interessen der Allgemeinheit auf dem Gebiet des öffentlich-rechtlichen Rundfunks vertreten. Dabei berücksichtigt er die Vielfalt der Meinungen der Bürger und Bürgerinnen. Er wirkt darauf hin, dass der NDR seine Aufgabe nach diesem Staatsvertrag erfüllt, soweit dafür nicht der Verwaltungsrat zuständig ist.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Rundfunkrat überwacht die Einhaltung der Anforderungen an die Angebote des NDR (§§ 3, 5, 7 bis 10) und berät den Intendanten oder die Intendantin in allgemeinen Programmangelegenheiten. Er kann feststellen, dass einzelne Sendungen gegen diese Anforderungen verstoßen, und den Intendanten oder die Intendantin anweisen, einen festgestellten Verstoß nicht fortzusetzen oder künftig zu unterlassen. Eine Kontrolle einzelner Sendungen durch den Rundfunkrat vor ihrer Ausstrahlung ist nicht zulässig; die Vorschriften des Jugendmedienschutz-Staatsvertrages bleiben unberührt.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Rundfunkrat hat ferner folgende Aufgaben:","children":[]},{"type":"item","label":"1.","text":"Erlass von Satzungen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Wahl und Abberufung des Intendanten oder der Intendantin und seines oder ihres Stellvertreters oder seiner oder ihrer Stellvertreterin,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Wahl und Abberufung der Mitglieder des Verwaltungsrats,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"Genehmigung des Wirtschaftsplans; dabei kann der Rundfunkrat über den vom Verwaltungsrat festgestellten Gesamtansatz der Aufwendungen nicht hinausgehen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5.","text":"Genehmigung des Jahresabschlusses,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"6.","text":"Entscheidung über die Übernahme von Verpflichtungen im Wert von mehr als 2,5 Millionen Euro bei Verträgen über Herstellung, Erwerb, Veräußerung und Auswertung von Angebotsteilen oder entsprechenden Rechten,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"7.","text":"Zustimmung zur gemeinsamen Produktion und Gestaltung von Teilen der Landesprogramme durch die Landesfunkhäuser im Rahmen von § 3 Absatz 4,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"8.","text":"Zustimmung zur Einrichtung eines weiteren Landesprogramms gemäß § 3 Absatz 1 Satz 4,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"9.","text":"Entscheidung über Beschränkungen und Ausnahmen nach den §§ 8 und 9 Absatz 1 des Jugendmedienschutz-Staatsvertrages ,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"10.","text":"Zustimmung zum Redaktionsstatut gemäß § 42 nach Anhörung des Verwaltungsrats.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(4)","text":"Bei der Wahrnehmung seiner Aufgaben sind dem Rundfunkrat und seinen Ausschüssen von dem Intendanten oder der Intendantin und vom Verwaltungsrat Auskünfte zu erteilen und Einsicht in die Unterlagen des NDR zu gewähren.","children":[]},{"type":"subparagraph","label":"(5)","text":"Die Wahl nach Absatz 3 Nummer 3 findet ein Jahr nach dem ersten Zusammentritt des Rundfunkrats statt. Eine einmalige Wiederwahl von Mitgliedern in den Verwaltungsrat ist zulässig.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 20, 0, 1, '{"type":"paragraph","label":"§ 20","title":"Amtsperiode und Vorsitz des Rundfunkrats","children":[{"type":"subparagraph","label":"(1)","text":"Die Amtsperiode des Rundfunkrats beträgt fünf Jahre und beginnt mit seinem ersten Zusammentritt. Nach Ablauf der Amtsperiode führt der Rundfunkrat die Geschäfte bis zum Zusammentritt des neuen Rundfunkrats. Die Mitgliedschaft im Rundfunkrat endet, wenn ein Ausschließungsgrund nach § 17 Absatz 2 bis Absatz 6 eintritt oder eine persönliche Voraussetzung nach § 17 Absatz 7 fortfällt.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Mitglieder des Rundfunkrats haben bei Wahrnehmung ihrer Aufgaben die Interessen der Allgemeinheit zu vertreten. Sie sind in ihrer Amtsführung an Aufträge oder Weisungen nicht gebunden.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Rundfunkrat wählt jeweils ein Mitglied für die Funktionen Vorsitz sowie erste, zweite und dritte Stellvertretung für die Dauer von 15 Monaten. Die Mitglieder sollen möglichst verschiedenen Ländern angehören; dabei darf kein Land mit mehr als zwei Funktionen vertreten sein. Der Vorsitz muss gleichermaßen aus Frauen und Männern bestehen. Der Vorsitz wechselt nach Ländern in der Reihenfolge Schleswig-Holstein – Niedersachsen – Hamburg.","children":[]},{"type":"subparagraph","label":"(4)","text":"Die Mitglieder des Rundfunkrats haben Anspruch auf Ersatz von Reisekosten sowie auf angemessene Tagegelder und Übernachtungskosten nach Maßgabe der Satzung. Mitglieder des Vorstands sowie Vorsitzende von Ausschüssen haben zudem Anspruch auf eine angemessene Aufwandsentschädigung.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 21, 0, 1, '{"type":"paragraph","label":"§ 21","title":"Sitzungen des Rundfunkrats","children":[{"type":"subparagraph","label":"(1)","text":"Die Sitzungen des Rundfunkrats finden nach Maßgabe der Satzung statt.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Mitglieder des Verwaltungsrats sowie der Intendant oder die Intendantin, dessen oder deren Stellvertreter oder Stellvertreterin und die Direktoren oder Direktorinnen (Funkhausdirektoren oder -direktorinnen und andere Direktoren oder Direktorinnen) können an den Sitzungen des Rundfunkrats beratend teilnehmen. Auf Verlangen des Rundfunkrats sind der oder die Vorsitzende des Verwaltungsrats sowie der Intendant oder die Intendantin, dessen oder deren Stellvertreter oder Stellvertreterin und die Direktoren oder Direktorinnen hierzu verpflichtet.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Gesamtpersonalrat kann zu den Sitzungen bis zu drei Mitglieder entsenden. Ihnen wird auf Verlangen zu Angelegenheiten ihres Aufgabenbereichs das Wort erteilt.","children":[]},{"type":"subparagraph","label":"(4)","text":"Die Regierungen der Länder sind in ihrer Funktion als Rechtsaufsicht berechtigt, zu den Sitzungen des Rundfunkrats Vertreter oder Vertreterinnen zu entsenden. Diese Vertreter oder Vertreterinnen sind jederzeit zu hören.","children":[]},{"type":"subparagraph","label":"(5)","text":"Die Sitzungen des Rundfunkrats sind öffentlich. In begründeten Ausnahmefällen kann der Rundfunkrat den Ausschluss der Öffentlichkeit beschließen. Personalangelegenheiten, die aus Gründen des Persönlichkeitsschutzes vertraulich sind, und Angelegenheiten, in welchen die Offenlegung von Betriebs- und Geschäftsgeheimnissen des NDR oder Dritter unvermeidlich ist, sind stets unter Ausschluss der Öffentlichkeit zu behandeln. Die Sitzungen der Ausschüsse nach § 23 sind grundsätzlich nicht öffentlich.","children":[]},{"type":"subparagraph","label":"(6)","text":"Die Öffentlichkeit der Sitzungen kann auch dadurch hergestellt werden, dass die Sitzungen zeitgleich in Bild und Ton in einen öffentlich zugänglichen Raum des NDR oder über allgemein zugängliche Netze übertragen werden.","children":[]},{"type":"subparagraph","label":"(7)","text":"Ist die Durchführung einer Sitzung des Rundfunkrats in unmittelbarer Anwesenheit seiner Mitglieder und der nach Absatz 2 bis Absatz 4 sonst Teilnahmeberechtigten nicht möglich oder durch außergewöhnliche äußere Umstände erheblich erschwert, kann das den Vorsitz führende Mitglied des Rundfunkrats anordnen, dass ohne unmittelbare Anwesenheit stattdessen die Teilnehmenden durch eine synchrone Übertragung von Bild und Ton miteinander verbunden sind (Videokonferenz). Eine Bildübertragung kann bei bis zu einem Drittel der teilnehmenden Mitglieder des Rundfunkrats unterbleiben, soweit diese mit einer ausschließlich durch Tonübertragung gewährleisteten Teilnahme einverstanden sind und kein Zweifel an deren Identität besteht. Durch geeignete technische Hilfsmittel ist sicherzustellen, dass Teilnahme- und Rederechte uneingeschränkt ausgeübt werden können und der Datenschutz gewährleistet bleibt. Die Öffentlichkeit einer Sitzung nach Satz 1 ist durch das Verfahren nach Absatz 6 zu gewährleisten. Die Regelungen über den Ausschluss der Öffentlichkeit gemäß Absatz 5 Satz 2 und Satz 3 sowie über die Beschlussfassung innerhalb einer Videokonferenz gemäß § 22 Absatz 4 bleiben unberührt.","children":[]},{"type":"subparagraph","label":"(8)","text":"Die Zusammensetzung des Rundfunkrats sowie seiner Ausschüsse nach § 23 sind zu veröffentlichen. Die Tagesordnung der Sitzungen des Rundfunkrats und seiner Ausschüsse sind spätestens eine Woche vor den Sitzungen zu veröffentlichen. Im Anschluss an die Sitzungen des Rundfunkrats sind Zusammenfassungen der wesentlichen Ergebnisse der Sitzungen des Rundfunkrats und seiner vorbereitenden Ausschüsse sowie die Anwesenheitslisten zu veröffentlichen. Die Veröffentlichung hat unter Wahrung von Betriebs- und Geschäftsgeheimnissen sowie personenbezogenen Daten der Beschäftigten des NDR zu erfolgen. Berechtigte Interessen Dritter an Geheimhaltung sind zu wahren. Eine Veröffentlichung in elektronischer Form im Online-Angebot des NDR ist ausreichend.","children":[]},{"type":"subparagraph","label":"(9)","text":"Das Nähere regelt die Satzung.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 22, 0, 1, '{"type":"paragraph","label":"§ 22","title":"Beschlüsse des Rundfunkrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Rundfunkrat ist beschlussfähig, wenn alle Mitglieder nach näherer Vorschrift der Satzung geladen wurden und wenn mindestens zwei Drittel seiner Mitglieder anwesend sind. Die Mitglieder des Rundfunkrats gelten auch im Rahmen einer gemäß § 21 Absatz 7 angeordneten Videokonferenz als anwesend.","children":[]},{"type":"subparagraph","label":"(2)","text":"Ohne Rücksicht auf die Anzahl der Erschienenen ist der Rundfunkrat beschlussfähig, wenn zu einer wegen Beschlussunfähigkeit aufgehobenen Sitzung unter ausdrücklichem Hinweis hierauf innerhalb einer angemessenen Frist erneut geladen wird.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Rundfunkrat fasst seine Beschlüsse durch Zustimmung mit der einfachen Mehrheit der anwesenden Mitglieder, soweit dieser Staatsvertrag nichts anderes bestimmt. Dasselbe gilt für Wahlen. Für Beschlüsse und Wahlen nach § 19 Absatz 3 Nummern 1 bis 4 und Nummer 8 ist eine Zustimmung von zwei Dritteln der anwesenden Mitglieder erforderlich; § 29 Absatz 3 bleibt unberührt.","children":[]},{"type":"subparagraph","label":"(4)","text":"Beschlüsse des Rundfunkrats innerhalb einer gemäß § 21 Absatz 7 angeordneten Videokonferenz sind in einem elektronischen oder schriftlichen Verfahren zulässig, wenn in Fällen höherer Gewalt die Beratung und Abstimmung des Rundfunkrats über einen Beschlussgegenstand ausschließlich in einem solchen Rahmen möglich ist, der Gegenstand der Beschlussfassung keinen zeitlichen Aufschub zulässt und nicht die Mehrheit der gesetzlichen Mitglieder des Rundfunkrats dieser Verfahrensweise vorab widersprochen hat. Das Vorliegen des Ausnahmefalls nach Satz 1 stellt das den Vorsitz führende Mitglied des Rundfunkrats fest und begründet dieses. Zur Stimmabgabe sind nur diejenigen Mitglieder des Rundfunkrats berechtigt, die nachweisbar an der Videokonferenz teilnehmen beziehungsweise teilgenommen haben. Durch geeignete technische Hilfsmittel ist sicherzustellen, dass diese Stimmrechte uneingeschränkt ausgeübt werden können. Geheime Abstimmungen dürfen in einer Videokonferenz nicht durchgeführt werden.","children":[]},{"type":"subparagraph","label":"(5)","text":"Das Nähere regelt die Satzung.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 23, 0, 1, '{"type":"paragraph","label":"§ 23","title":"Ausschüsse des Rundfunkrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Rundfunkrat bildet mindestens einen Programmausschuss. Er kann weitere Ausschüsse bilden. In den Ausschüssen sollen Frauen und Männer entsprechend dem Verhältnis im Rundfunkrat vertreten sein. Der Programmausschuss bereitet die Beschlüsse des Rundfunkrats in Programmangelegenheiten vor. Er kann dem Intendanten oder der Intendantin in Programmangelegenheiten Empfehlungen geben, soweit der Rundfunkrat nichts anderes beschließt.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Programmausschuss kann mit der Zustimmung von zwei Dritteln seiner anwesenden Mitglieder in dringenden Programmangelegenheiten, in denen eine Beschlussfassung des Rundfunkrats nicht kurzfristig herbeigeführt werden kann, die zur Einhaltung der Programmanforderungen erforderlichen Beschlüsse nach § 19 Absatz 2 fassen. Der oder die Vorsitzende des Rundfunkrats ist hiervon unverzüglich zu unterrichten. Der Rundfunkrat hat in seiner nächsten Sitzung über die Beschlüsse des Programmausschusses zu entscheiden.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 24, 0, 1, '{"type":"paragraph","label":"§ 24","title":"Landesrundfunkrat","children":[{"type":"subparagraph","label":"(1)","text":"Bei jedem Landesfunkhaus wird ein Landesrundfunkrat gebildet. Dem Landesrundfunkrat gehören die Mitglieder des jeweiligen Landes im Rundfunkrat an. Die Landesrundfunkräte können öffentlich tagen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Landesrundfunkrat überwacht die Einhaltung der Anforderungen an die jeweiligen Landesangebote (§ 3 Absatz 3; §§ 5, 7 bis 10) und berät im Rahmen der Aufgaben, die dem Landesfunkhaus zur Wahrnehmung in eigener Verantwortung nach diesem Staatsvertrag zugewiesen sind, den Landesfunkhausdirektor oder die Landesfunkhausdirektorin in allen Angelegenheiten von grundsätzlicher Bedeutung. Er kann nach erfolgter Ausstrahlung feststellen, dass einzelne Angebote gegen diese Anforderungen verstoßen, und den Intendanten oder die Intendantin anweisen, einen festgestellten Verstoß nicht fortzusetzen oder künftig zu unterlassen. Eine Kontrolle einzelner Angebote durch den Landesrundfunkrat vor ihrer Ausstrahlung ist nicht zulässig; § 9 des Jugendmedienschutz-Staatsvertrages bleibt unberührt. Dem Landesrundfunkrat stehen insbesondere folgende Aufgaben zu:","children":[]},{"type":"item","label":"1.","text":"Stellungnahme zum Entwurf des Wirtschaftsplans des Intendanten oder der Intendantin, soweit das Landesfunkhaus betroffen ist,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Zustimmung zum Vorschlag des Intendanten oder der Intendantin für die Berufung des Landesfunkhausdirektors oder der Landesfunkhausdirektorin,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Erlass einer Geschäftsordnung.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Gesamtverantwortung des Rundfunkrats (§ 19) bleibt unberührt.","children":[]},{"type":"subparagraph","label":"(4)","text":"Die Bestimmungen der §§ 19 Absatz 1 und Absatz 4; 20 Absatz 1 und Absatz 2; 21 Absatz 1, Absatz 2 Satz 1, Absatz 3, Absatz 4 und Absatz 7 Satz 1 bis Satz 3; 22 Absatz 1 bis Absatz 3 Satz 1 und Absatz 4 finden im Rahmen der Zuständigkeit des Landesrundfunkrats entsprechende Anwendung. Die Mitglieder des Landesrundfunkrats haben Anspruch auf Ersatz von Reisekosten sowie auf Tagegelder und Übernachtungsgelder nach Maßgabe der Satzung.","children":[]},{"type":"subparagraph","label":"(5)","text":"Der Landesrundfunkrat wählt jeweils ein Mitglied für die Funktionen Vorsitz und Stellvertretung für die Dauer der Amtszeit des Rundfunkrats.","children":[]},{"type":"subparagraph","label":"(6)","text":"Der oder die Vorsitzende des Landesrundfunkrats oder sein oder ihr Stellvertreter oder seine oder ihre Stellvertreterin sind berechtigt und auf Verlangen eines Drittels der Mitglieder des Rundfunkrats verpflichtet, über Angelegenheiten des jeweiligen Landesrundfunkrats im Rundfunkrat zu berichten.","children":[]},{"type":"subparagraph","label":"(7)","text":"Der oder die Vorsitzende des Rundfunkrats sowie der jeweilige Landesfunkhausdirektor oder die jeweilige Landesfunkhausdirektorin sind berechtigt, an Sitzungen des Landesrundfunkrats teilzunehmen; auf Verlangen des Landesrundfunkrats ist der jeweilige Landesfunkhausdirektor oder die jeweilige Landesfunkhausdirektorin hierzu verpflichtet. Er oder sie kann verlangen, gehört zu werden. Gleiches gilt für den Fall der Stellvertretung.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 25, 0, 1, '{"type":"paragraph","label":"§ 25","title":"Zusammensetzung des Verwaltungsrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Verwaltungsrat besteht aus zwölf Mitgliedern, die vom Rundfunkrat gewählt werden, und zwar sieben Mitgliedern aus Niedersachsen, zwei Mitgliedern aus Hamburg und drei Mitgliedern aus Schleswig-Holstein, wovon jeweils die Hälfte Frauen sein sollen. Von den in den Verwaltungsrat gewählten Mitgliedern müssen auf Frauen und Männer jeweils fünfzig vom Hundert entfallen. § 18 Absatz 2 Satz 6 gilt entsprechend.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Mitglieder des Verwaltungsrats müssen über die für die Tätigkeit im Verwaltungsrat erforderliche fachliche Qualifikation verfügen. Hierzu zählen Kenntnisse auf den Gebieten der Finanzwirtschaft oder -wissenschaft, der Medienwirtschaft oder -wissenschaft, der Rechtswissenschaft, des Journalismus oder vergleichbarer, geeigneter Qualifikationen.","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Mitglieder des Verwaltungsrats haben die Interessen des NDR zu fördern. Sie sind bei der Erfüllung ihrer Aufgaben an Aufträge oder Weisungen nicht gebunden; sie dürfen keine Sonderinteressen vertreten.","children":[]},{"type":"subparagraph","label":"(4)","text":"§ 20 Absatz 4 gilt für die Mitglieder des Verwaltungsrats entsprechend mit der Maßgabe, dass Mitglieder des Verwaltungsrats Anspruch auf eine angemessene Aufwandsentschädigung haben.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 26, 0, 1, '{"type":"paragraph","label":"§ 26","title":"Aufgaben des Verwaltungsrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Verwaltungsrat überwacht die Geschäftsführung des Intendanten oder der Intendantin; dies gilt nicht für die inhaltliche Gestaltung der Angebote, die allein der Rundfunkrat und - im Rahmen ihrer Zuständigkeit - die Landesrundfunkräte überwachen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Verwaltungsrat hat ferner folgende Aufgaben:","children":[]},{"type":"item","label":"1.","text":"Feststellung des Wirtschaftsplans und des Jahresabschlusses,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Feststellung des Entwicklungsplans,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Erlass der Finanzordnung,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"Zustimmung zu Rechtsgeschäften und Entscheidungen des Intendanten oder der Intendantin nach § 31,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5.","text":"Vertretung des NDR beim Abschluss von Rechtsgeschäften und in anderen Rechtsangelegenheiten gegenüber dem Intendanten oder der Intendantin,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"6.","text":"Auswahl des Abschlussprüfers oder der Abschlussprüferin,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"7.","text":"Entlastung des Intendanten oder der Intendantin,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"8.","text":"Vorschläge für die Wahl und die Abberufung des Intendanten oder der Intendantin und seines oder ihres Stellvertreters oder seiner oder ihrer Stellvertreterin nach § 29,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"9.","text":"Zustimmung zur Einrichtung eines weiteren Landesprogramms gemäß § 3 Absatz 1 Satz 4.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(3)","text":"Bei der Wahrnehmung seiner Aufgaben sind dem Verwaltungsrat von dem Intendanten oder der Intendantin Auskünfte zu erteilen und Einsicht in die Unterlagen des NDR zu gewähren. Der Verwaltungsrat kann einzelne Vorgänge untersuchen; er kann damit für bestimmte Aufgaben auch besondere Sachverständige beauftragen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 27, 0, 1, '{"type":"paragraph","label":"§ 27","title":"Amtsperiode des Verwaltungsrats","children":[{"type":"subparagraph","label":"(1)","text":"Die Amtsperiode des Verwaltungsrats beträgt fünf Jahre und beginnt mit seinem ersten Zusammentritt. Nach Ablauf der Amtsperiode führt der Verwaltungsrat die Geschäfte bis zum Zusammentritt des neuen Verwaltungsrats. Die Mitgliedschaft im Verwaltungsrat endet bei Abberufung oder dann, wenn ein Ausschließungsgrund nach § 17 Absatz 2 bis Absatz 6 eintritt oder eine persönliche Voraussetzung nach § 17 Absatz 7 fortfällt.","children":[]},{"type":"subparagraph","label":"(2)","text":"Ein Mitglied des Verwaltungsrats kann auf Antrag des Verwaltungsrats vom Rundfunkrat abberufen werden, wenn sein Verbleiben im Amt die Interessen des NDR erheblich schädigen würde. Der Verwaltungsrat und der Rundfunkrat haben dem betroffenen Mitglied Gelegenheit zur Äußerung zu geben. Das betroffene Mitglied ist von der Beratung und Beschlussfassung über den Antrag im Verwaltungsrat ausgeschlossen. Das Nähere regelt die Satzung.","children":[]},{"type":"subparagraph","label":"(3)","text":"Scheidet ein Mitglied des Verwaltungsrats vorzeitig aus, ist innerhalb von zwei Monaten nach dessen Ausscheiden für den Rest der Amtsperiode ein Nachfolger oder eine Nachfolgerin zu wählen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 28, 0, 1, '{"type":"paragraph","label":"§ 28","title":"Sitzungen des Verwaltungsrats","children":[{"type":"subparagraph","label":"(1)","text":"Der Verwaltungsrat tritt in der Regel einmal im Monat, mindestens jedoch einmal im Vierteljahr zusammen. Er wird von seinem oder seiner Vorsitzenden oder, wenn ein Vorsitzender oder eine Vorsitzende nicht vorhanden ist, von dem an Lebensjahren ältesten Mitglied einberufen. Der Verwaltungsrat ist unverzüglich einzuberufen, wenn drei Mitglieder unter Angabe der Gründe es verlangen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Intendant oder die Intendantin, der Stellvertreter oder die Stellvertreterin sowie die Direktoren und Direktorinnen können an den Sitzungen des Verwaltungsrats beratend teilnehmen. Auf Verlangen des Verwaltungsrats sind sie hierzu verpflichtet.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Verwaltungsrat ist beschlussfähig, wenn alle Mitglieder nach näherer Vorschrift der Satzung geladen wurden und wenn mindestens sieben Mitglieder anwesend sind. Ist der Verwaltungsrat beschlussunfähig, sind alle Mitglieder innerhalb einer Woche mit derselben Tagesordnung erneut zu laden. In der darauf stattfindenden Sitzung ist der Verwaltungsrat ohne Rücksicht auf die Anzahl der anwesenden Mitglieder beschlussfähig.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der Verwaltungsrat fasst seine Beschlüsse durch Zustimmung mit einfacher Mehrheit der anwesenden Mitglieder, soweit in diesem Staatsvertrag nichts anderes bestimmt ist; entsprechendes gilt für die Wahl des oder der Vorsitzenden und dessen oder deren Stellvertreter oder Stellvertreterin. Für Beschlüsse nach § 26 Absatz 2 Nummern 1, 2, 8 und 9 ist die Zustimmung von zwei Dritteln der gesetzlichen Mitglieder erforderlich. Kommt eine Mehrheit nicht zustande, ist der Antrag abgelehnt.","children":[]},{"type":"subparagraph","label":"(5)","text":"Ist die Durchführung einer Sitzung des Verwaltungsrats in unmittelbarer Anwesenheit seiner Mitglieder nicht möglich oder durch außergewöhnliche äußere Umstände erheblich erschwert, kann der Verwaltungsrat stattdessen im Wege einer Audio-/Videokonferenz ohne unmittelbare Anwesenheit zusammentreten. In diesem Fall ist eine Beschlussfassung im schriftlichen oder elektronischen Verfahren zulässig. Stimmberechtigt sind diejenigen Mitglieder, die an der Audio-/Videokonferenz teilnehmen beziehungsweise teilgenommen haben.","children":[]},{"type":"subparagraph","label":"(6)","text":"Der Verwaltungsrat wählt seinen Vorsitzenden oder seine Vorsitzende und dessen oder deren Stellvertreter oder Stellvertreterin für die Dauer von 15 Monaten. Der Vorsitz wechselt nach Ländern in der Reihenfolge Niedersachsen – Hamburg – Schleswig-Holstein. Für die Wahl des oder der stellvertretenden Vorsitzenden gilt die umgekehrte Reihenfolge.","children":[]},{"type":"subparagraph","label":"(7)","text":"Die Regierungen der Länder sind in ihrer Funktion als Rechtsaufsicht berechtigt, zu den Sitzungen des Verwaltungsrats je einen Vertreter oder eine Vertreterin zu entsenden. Diese sind jederzeit zu hören. Ihnen sind alle Unterlagen zur Verfügung zu stellen, die auch die Mitglieder des Verwaltungsrats erhalten.","children":[]},{"type":"subparagraph","label":"(8)","text":"Der Gesamtpersonalrat kann zu den Sitzungen bis zu drei Mitglieder entsenden. Ihnen wird auf Verlangen zu Angelegenheiten ihres Aufgabenbereichs das Wort erteilt.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 29, 0, 1, '{"type":"paragraph","label":"§ 29","title":"Wahl und Abberufung des Intendanten oder der Intendantin","children":[{"type":"subparagraph","label":"(1)","text":"Der Intendant oder die Intendantin und der Stellvertreter oder die Stellvertreterin werden vom Rundfunkrat auf Vorschlag des Verwaltungsrats für die Dauer von fünf Jahren gewählt. Die Wahl erfolgt innerhalb der letzten sechs Monate seiner oder ihrer Amtszeit, bei vorzeitigem Ausscheiden unverzüglich, spätestens innerhalb von sechs Monaten. Eine Wiederwahl ist zweimal zulässig.","children":[]},{"type":"subparagraph","label":"(2)","text":"Macht der Verwaltungsrat nicht innerhalb von drei Monaten einen Wahlvorschlag, entfällt das Vorschlagsrecht. Findet ein Wahlvorschlag nicht die erforderliche Zustimmung im Rundfunkrat, ist der Verwaltungsrat berechtigt, jeweils innerhalb eines weiteren Monats einen neuen Wahlvorschlag zu machen; Satz 1 gilt entsprechend.","children":[]},{"type":"subparagraph","label":"(3)","text":"Kommt innerhalb der Frist nach Absatz 1 die Wahl im Rundfunkrat nicht zustande, findet nach Ablauf eines Monats ein weiterer Wahlgang statt. In ihm ist gewählt, wer die Zustimmung der Mehrheit der gesetzlichen Mitglieder des Rundfunkrats erhält.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der Intendant oder die Intendantin und der Stellvertreter oder die Stellvertreterin können vor Ablauf der Amtsperiode, auch auf Vorschlag des Verwaltungsrats, durch Beschluss des Rundfunkrats abberufen werden.","children":[]},{"type":"subparagraph","label":"(5)","text":"Für die Ansprüche aus den Anstellungsverträgen gelten die Vorschriften des bürgerlichen Rechts.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 30, 0, 1, '{"type":"paragraph","label":"§ 30","title":"Intendanz und Direktorium","children":[{"type":"subparagraph","label":"(1)","text":"Der Intendant oder die Intendantin leitet den NDR. Er oder sie berät mit dem Stellvertreter oder der Stellvertreterin sowie mit den Direktoren oder Direktorinnen die wesentlichen Angelegenheiten.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Aufgaben, Befugnisse und Rechtsverhältnisse des Intendanten oder der Intendantin, des Stellvertreters oder der Stellvertreterin und der Direktoren oder Direktorinnen, deren Zahl sowie die Geschäftsverteilung bestimmt die Satzung, soweit dieser Staatsvertrag keine Regelung trifft. Der Stellvertreter oder die Stellvertreterin wird von dem Direktor oder der Direktorin mit der längsten Dienstzeit vertreten. Ist ein Stellvertreter oder eine Stellvertreterin des Intendanten oder der Intendantin nicht bestellt, nimmt der dienstälteste Direktor oder die Direktorin mit der längsten Dienstzeit die Aufgaben des Stellvertreters oder der Stellvertreterin wahr.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Intendant oder die Intendantin vertritt die Anstalt als gesetzlicher Vertreter gerichtlich und außergerichtlich. Die Satzung regelt die Vertretungsbefugnis, insbesondere bestimmt sie die Fälle, in denen der Intendant oder die Intendantin zur Vertretung der Mitzeichnung des Stellvertreters oder der Stellvertreterin oder eines Direktors oder einer Direktorin bedarf.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der Intendant oder die Intendantin legt dem Rundfunkrat und dem Verwaltungsrat den Entwurf des Wirtschaftsplans, den Jahresabschluss und den Geschäftsbericht vor. Die Landesfunkhäuser sind hierbei jeweils gesondert auszuweisen. Beim Aufstellen des Wirtschaftsplans sind die Stellungnahmen der Landesrundfunkräte (§ 24 Absatz 2 Satz 3 Nummer 1) zu berücksichtigen; die Stellungnahmen sind für die Beschlussfassung vorzulegen.","children":[]},{"type":"subparagraph","label":"(5)","text":"Der Intendant oder die Intendantin berichtet dem Verwaltungsrat alle zwei Jahre quantifiziert und detailliert über die Auftrags- und Koproduktionen mit unabhängigen und abhängigen Produzenten.","children":[]},{"type":"subparagraph","label":"(6)","text":"Der Intendant oder die Intendantin hat dafür Sorge zu tragen, dass das Angebot des NDR den Angebotsanforderungen (§ 3 Absatz 3; §§ 5, 7 bis 10) entspricht.","children":[]},{"type":"subparagraph","label":"(7)","text":"Dem Intendanten oder der Intendantin, dem Stellvertreter oder der Stellvertreterin und den Direktoren oder Direktorinnen wird eine begleitende Projekt- und Finanzkontrolle nach Maßgabe der Satzung zugeordnet.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 31, 0, 1, '{"type":"paragraph","label":"§ 31","title":"Zustimmungsbedürftige Angelegenheiten","children":[{"type":"subparagraph","label":"(1)","text":"Der Intendant oder die Intendantin bedarf in folgenden Angelegenheiten der Zustimmung des Verwaltungsrats:","children":[]},{"type":"item","label":"1.","text":"Abschluss und Kündigung von Anstellungsverträgen mit Angestellten, deren Bezüge über der höchsten Tarifgruppe liegen, sowie Bestellung und Abberufung von Direktoren oder Direktorinnen; § 3 Absatz 2 Satz 3 sowie § 24 Absatz 2 Satz 3 Nummer 2 bleiben unberührt,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Abschluss von Dienstvereinbarungen und Tarifverträgen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"grundlegende Veränderungen der Bedingungen der Rundfunkwerbung,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"Abschluss von Vereinbarungen über die Zusammenarbeit mit anderen Rundfunkveranstaltern im Rahmen von § 11,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5.","text":"Erwerb, Veräußerung und Belastung von Grundstücken,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"6.","text":"Erwerb und Veräußerung von Unternehmen sowie unmittelbaren Beteiligungen an ihnen gemäß § 37,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"7.","text":"Erwerb und Veräußerung von mittelbaren Beteiligungen an Unternehmen gemäß § 37, soweit die mittelbare Beteiligung nach dem Erwerb mehr als 50 Prozent oder nach der Veräußerung weniger als 50 Prozent am Grund- oder Stammkapital dieser Unternehmen beträgt,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"8.","text":"Aufnahme von Anleihen und Inanspruchnahme von Krediten, soweit nicht im Wirtschaftsplan vorgesehen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"9.","text":"Übernahme von fremden Verbindlichkeiten, Bürgschaften und Garantien und","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"10.","text":"Übernahme von Verpflichtungen im Wert von mehr als 5 Millionen Euro außer bei Verträgen über Herstellung, Erwerb, Veräußerung oder Auswertung von Programmteilen oder entsprechenden Rechten.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Zustimmung des Verwaltungsrats zu Absatz 1 Nummer 7 ist vor der abschließenden Befassung und Entscheidung des oder der zuständigen Organe des die Beteiligung eingehenden Unternehmens einzuholen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 32, 0, 1, '{"type":"paragraph","label":"§ 32","title":"Wirtschaftsführung","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR hat die zur Erfüllung seiner Aufgaben erforderlichen regelmäßigen Einnahmen vorrangig","children":[]},{"type":"item","label":"1.","text":"aus dem Rundfunkbeitrag,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"aus Werbung und Sponsoring,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"aus laufenden Erträgen seines Vermögens","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"zu beschaffen. Sie dürfen nur für die in diesem Gesetz bestimmten Aufgaben verwendet werden. Die Bestimmungen des § 112 Absatz 2 und Absatz 3 Satz 2 des Medienstaatsvertrages bleiben unberührt."},{"type":"subparagraph","label":"(2)","text":"Der NDR hat bei seiner Wirtschaftsführung die Grundsätze der Wirtschaftlichkeit und Sparsamkeit, der Nachhaltigkeit sowie der Klarheit bei der finanziellen Zuordnung von Einnahmen und Ausgaben zu beachten. Er verwendet seine finanziellen Mittel in der Weise, wie dies zur Erfüllung seiner Aufgaben erforderlich ist. Die Wirtschaftsführung des NDR richtet sich nach der Finanzordnung, einer mehrjährigen Finanzplanung, dem Entwicklungsplan und dem jährlichen Wirtschaftsplan.","children":[]},{"type":"subparagraph","label":"(3)","text":"Mit der mehrjährigen Finanzplanung ist ein Entwicklungsplan aufzustellen und fortzuschreiben, der die Vorstellungen des NDR für die strukturelle Entwicklung der Rundfunkanstalt sowie den Ausbau seiner Einrichtungen, insbesondere für die Versorgung mit Landesprogrammen, enthält.","children":[]},{"type":"subparagraph","label":"(4)","text":"Ist bis zum Schluss eines Geschäftsjahres der Wirtschaftsplan für das folgende Jahr nicht wirksam geworden, ist der Intendant oder die Intendantin bis zum Wirksamwerden ermächtigt, alle Ausgaben zu leisten, die notwendig sind, um","children":[]},{"type":"item","label":"1.","text":"den Betrieb des NDR in seinem bisherigen Umfang zu erhalten,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"die von den Organen des NDR beschlossenen Maßnahmen durchzuführen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Bauten, Beschaffungen und sonstige Leistungen fortzusetzen, sofern durch den Wirtschaftsplan des Vorjahres bereits Beträge bewilligt sind,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"rechtlich begründete Verpflichtungen des NDR zu erfüllen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(5)","text":"Der NDR soll die Ansprüche der Mitarbeitenden aus Versorgungszusagen durch Bildung von Rückstellungen in angemessenem Umfang sicherstellen. Zur Sicherung der Ansprüche sind Finanzmittel in angemessener Höhe einem Sondervermögen zuzuführen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 33, 0, 1, '{"type":"paragraph","label":"§ 33","title":"Jahresabschluss und Geschäftsbericht","children":[{"type":"subparagraph","label":"(1)","text":"Der Intendant oder die Intendantin hat nach Abschluss des Geschäftsjahres den Jahresabschluss, den Lagebericht, den Konzernabschluss und den Konzernlagebericht sowie einen Geschäftsbericht aufzustellen. Der Geschäftsbericht hat einen umfassenden Einblick in die Vermögens- und Ertragsverhältnisse des NDR einschließlich seiner Beziehungen zu Beteiligungsunternehmen zu vermitteln.","children":[]},{"type":"subparagraph","label":"(2)","text":"Jahresabschluss und Lagebericht sowie Konzernabschluss und Konzernlagebericht sind in entsprechender Anwendung der Vorschriften des Dritten Buches des Handelsgesetzbuches für große Kapitalgesellschaften aufzustellen und vor der Feststellung zu prüfen. Getrennt auszuweisen ist insbesondere die Veranstaltung von Hörfunk- und Fernsehprogrammen. Die Kriterien für die Zuordnung von Einnahmen und Ausgaben sind dem Verwaltungsrat zu erläutern. Der Abschlussprüfer oder die Abschlussprüferin ist auch mit den Feststellungen und Berichten nach § 53 Absatz 1 des Haushaltsgrundsätzegesetzes zu beauftragen.","children":[]},{"type":"subparagraph","label":"(3)","text":"Jahresabschluss, Lagebericht, Konzernabschluss, Konzernlagebericht, Prüfungsbericht und Geschäftsbericht werden vom Intendanten oder von der Intendantin den Regierungen und Rechnungshöfen der Länder übermittelt.","children":[]},{"type":"subparagraph","label":"(4)","text":"Nach Genehmigung des Jahresabschlusses durch den Rundfunkrat veröffentlicht der Intendant oder die Intendantin eine Gesamtübersicht über den Jahresabschluss und eine Zusammenfassung der wesentlichen Teile des Geschäftsberichts.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 34, 0, 1, '{"type":"paragraph","label":"§ 34","title":"Information der Landesparlamente","children":[{"type":"paragraphText","text":"Für die Information der Parlamente der Länder gilt § 5a des Rundfunkfinanzierungsstaatsvertrages entsprechend."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 35, 0, 1, '{"type":"paragraph","label":"§ 35","title":"Finanzordnung","children":[{"type":"subparagraph","label":"(1)","text":"Die Finanzordnung wird vom Verwaltungsrat erlassen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Finanzordnung hat von folgenden Grundsätzen auszugehen:","children":[]},{"type":"item","label":"1.","text":"Für jedes Geschäftsjahr ist ein Wirtschaftsplan aufzustellen. § 33 Absatz 2 Satz 2 und Satz 3 gilt entsprechend. Der Wirtschaftsplan dient der Feststellung und Deckung des Finanzbedarfs, der zur Erfüllung der Aufgaben des NDR voraussichtlich notwendig ist;","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"der Wirtschaftsplan ermächtigt den Intendanten oder die Intendantin, Ausgaben zu leisten und Verpflichtungen einzugehen;","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"der Wirtschaftsplan bestimmt, bis zu welcher Höhe der Intendant oder die Intendantin Kredite aufnehmen darf.","level":0,"numberingStyle":"decimal","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 36, 0, 1, '{"type":"paragraph","label":"§ 36","title":"Finanzkontrolle","children":[{"type":"subparagraph","label":"(1)","text":"Die Rechnungshöfe der Länder prüfen die Wirtschaftsführung des NDR gemeinsam. Federführend ist grundsätzlich der Rechnungshof des nach § 39 Aufsicht führenden Landes.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der für die Durchführung zuständige Rechnungshof teilt das Ergebnis der Prüfung des NDR einschließlich deren Beteiligungsunternehmen dem Intendanten oder der Intendantin, dem Direktor oder der Direktorin des jeweiligen Landesfunkhauses, den jeweils zuständigen Aufsichtsgremien und der Geschäftsführung des geprüften Beteiligungsunternehmens sowie der KEF mit. Er gibt dem Intendanten oder der Intendantin, dem Direktor oder der Direktorin des jeweiligen Landesfunkhauses und der Geschäftsführung des Beteiligungsunternehmens Gelegenheit zur Stellungnahme zu dem Ergebnis der Prüfung und berücksichtigt die Stellungnahmen. Den auf dieser Grundlage erstellten abschließenden Bericht über das Ergebnis teilt der zuständige Rechnungshof den Landtagen und den Landesregierungen sowie der KEF mit und veröffentlicht ihn anschließend. Dabei hat der Rechnungshof darauf zu achten, dass die Wettbewerbsfähigkeit des geprüften Beteiligungsunternehmens nicht beeinträchtigt wird und insbesondere Betriebs- und Geschäftsgeheimnisse gewahrt werden.","children":[]},{"type":"subparagraph","label":"(3)","text":"Die Vorschriften der Landeshaushaltsordnungen der Länder über Unternehmen in der Rechtsform einer landesunmittelbaren juristischen Person des öffentlichen Rechts sind in der jeweils geltenden Fassung im Übrigen entsprechend anzuwenden.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 37, 0, 1, '{"type":"paragraph","label":"§ 37","title":"Beteiligungen","children":[{"type":"subparagraph","label":"(1)","text":"An einem Unternehmen, das einen gewerblichen oder sonstigen wirtschaftlichen Zweck zum Gegenstand hat, darf sich der NDR unmittelbar oder mittelbar beteiligen, wenn","children":[]},{"type":"item","label":"1.","text":"dies im Rahmen seiner gesetzlichen Aufgaben steht,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"das Unternehmen die Rechtsform einer juristischen Person besitzt und","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"die Satzung oder der Gesellschaftsvertrag des Unternehmens einen Aufsichtsrat oder ein entsprechendes Organ vorsieht.","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"Die Voraussetzungen nach Satz 1 müssen nicht erfüllt sein, wenn die Beteiligung nur vorübergehend eingegangen wird und unmittelbaren Angebotszwecken dient."},{"type":"subparagraph","label":"(2)","text":"Bei Beteiligungsunternehmen hat sich der NDR in geeigneter Weise den nötigen Einfluss auf die Geschäftsleitung des Unternehmens, insbesondere eine angemessene Vertretung im Aufsichtsgremium, zu sichern. Eine Prüfung der Betätigung der Anstalt bei dem Unternehmen unter Beachtung kaufmännischer Grundsätze durch ein Wirtschaftsprüfungsunternehmen ist auszubedingen; § 36 bleibt unberührt.","children":[]},{"type":"subparagraph","label":"(3)","text":"Absatz 1 und Absatz 2 gelten entsprechend für juristische Personen des Privatrechts, die vom NDR gegründet werden und/oder deren Geschäftsanteile sich ausschließlich in der Hand des NDR befinden.","children":[]},{"type":"subparagraph","label":"(4)","text":"Angehörige des NDR sowie Mitglieder des Rundfunkrats oder des Verwaltungsrats dürfen an Unternehmen, an denen der NDR unmittelbar oder mittelbar beteiligt ist, nicht persönlich beteiligt sein. Die Mitglieder des Verwaltungsrats dürfen nicht den Aufsichtsgremien nach Absatz 1 und Absatz 2 angehören.","children":[]},{"type":"subparagraph","label":"(5)","text":"Der NDR hat sicherzustellen, dass Mitglieder der Geschäftsführung sowie leitende Angestellte von juristischen Personen nach Absatz 1 und Absatz 3 nicht ihrerseits an anderen juristischen Personen dieser Art beteiligt sind.","children":[]},{"type":"subparagraph","label":"(6)","text":"Der NDR hat ein effektives Controlling über seine Beteiligungen einzurichten. Der Intendant oder die Intendantin hat den Verwaltungsrat regelmäßig über die wesentlichen Vorgänge in den Beteiligungsunternehmen, insbesondere über deren finanzielle Entwicklungen, zu unterrichten.","children":[]},{"type":"subparagraph","label":"(7)","text":"Der Intendant oder die Intendantin hat dem Verwaltungsrat jährlich einen Beteiligungsbericht vorzulegen. Dieser Bericht schließt folgende Bereiche ein:","children":[]},{"type":"item","label":"1.","text":"die Darstellung sämtlicher unmittelbarer und mittelbarer Beteiligungen und ihrer wirtschaftlichen Bedeutung für den NDR,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"die gesonderte Darstellung der Beteiligungen mit kommerziellen Tätigkeiten und Nachweis der Erfüllung der staatsvertraglichen Vorgaben für kommerzielle Tätigkeiten und","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"die Darstellung der Kontrolle der Beteiligung einschließlich von Vorgängen mit besonderer Bedeutung.","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"Der Bericht ist den jeweils zuständigen Rechnungshöfen und der rechtsaufsichtsführenden Landesregierung zu übermitteln."},{"type":"subparagraph","label":"(8)","text":"Die für den NDR zuständigen Rechnungshöfe prüfen die Wirtschaftsführung bei solchen Unternehmen des Privatrechts, an denen der NDR unmittelbar, mittelbar, auch zusammen mit anderen Anstalten oder Körperschaften des öffentlichen Rechts, mit Mehrheit beteiligt ist und deren Gesellschaftsvertrag oder Satzung diese Prüfung durch die Rechnungshöfe vorsieht. Der NDR ist verpflichtet, für die Aufnahme der erforderlichen Regelungen in den Gesellschaftsvertrag oder die Satzung des Unternehmens zu sorgen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 38, 0, 1, '{"type":"paragraph","label":"§ 38","title":"Werbung, Zulässiges Sponsoring, Zulässige Produktplatzierung","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR veranstaltet Fernsehwerbung im Gemeinschaftsprogramm der ARD \"Erstes Deutsches Fernsehen (Das Erste)\". Für die Gesamtdauer der Fernsehwerbung gilt § 39 Absatz 1 und Absatz 3 des Medienstaatsvertrages .","children":[]},{"type":"subparagraph","label":"(2)","text":"Der NDR kann Hörfunkwerbung in einem Hörfunkprogramm veranstalten. Ihre Gesamtdauer und Struktur werden durch Vereinbarung der Länder festgesetzt.","children":[]},{"type":"subparagraph","label":"(3)","text":"Sponsoring ist nach Maßgabe des § 39 des Medienstaatsvertrages zulässig. Umfang und Struktur können durch Vereinbarung der Staatsvertragsländer festgelegt werden.","children":[]},{"type":"subparagraph","label":"(4)","text":"Produktplatzierung ist nach Maßgabe des § 38 des Medienstaatsvertrages zulässig.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 39, 0, 1, '{"type":"paragraph","label":"§ 39","title":"Rechtsaufsicht","children":[{"type":"subparagraph","label":"(1)","text":"Die Regierungen der Länder führen die Aufsicht über den NDR hinsichtlich der Einhaltung der Bestimmungen dieses Staatsvertrages und der allgemeinen Rechtsvorschriften. Sie nehmen diese Aufgabe durch die Regierung eines der Länder im Wechsel von 18 Monaten wahr. Der Wechsel erfolgt in der Reihenfolge Hamburg – Niedersachsen – Schleswig-Holstein. Die jeweils aufsichtsführende Regierung beteiligt die anderen Regierungen vor der Einleitung von Maßnahmen und bemüht sich um ein Einvernehmen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die aufsichtsführende Regierung ist berechtigt, ein von ihr im Einzelfall zu bestimmendes Organ des NDR durch schriftliche Mitteilungen auf Maßnahmen oder Unterlassungen im Betrieb des NDR hinzuweisen, die diesen Staatsvertrag oder die allgemeinen Rechtsvorschriften verletzen, und das Organ aufzufordern, die Rechtsverletzung zu beseitigen.","children":[]},{"type":"subparagraph","label":"(3)","text":"Wird die Rechtsverletzung nicht innerhalb einer von der aufsichtsführenden Regierung zu setzenden angemessenen Frist behoben, weist diese den NDR an, im Einzelnen festgelegte Maßnahmen auf dessen Kosten durchzuführen. In Programmangelegenheiten sind Weisungen unzulässig.","children":[]},{"type":"subparagraph","label":"(4)","text":"Maßnahmen der Rechtsaufsicht gegenüber dem Intendanten oder der Intendantin sind erst dann zulässig, wenn der Rundfunkrat, der Landesrundfunkrat oder der Verwaltungsrat die ihnen zustehende Aufsicht nicht in angemessener Frist wahrnehmen.","children":[]},{"type":"subparagraph","label":"(5)","text":"Die aufsichtsführende Regierung ist zugleich zuständige Behörde nach § 16 Absatz 1 des Medienstaatsvertrages .","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 40, 0, 1, '{"type":"paragraph","label":"§ 40","title":"Gleichstellung von Frauen und Männern","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR hat durch Dienstvereinbarung die berufliche Gleichstellung von Frauen und Männern im NDR zu fördern. Frauen führen die jeweilige Funktionsbezeichnung für ihre Tätigkeit im NDR in der weiblichen Form.","children":[]},{"type":"subparagraph","label":"(2)","text":"Der Intendant oder die Intendantin legt dem Verwaltungsrat jährlich einen Bericht über den Stand der Gleichstellung von Frauen und Männern vor.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 41, 0, 1, '{"type":"paragraph","label":"§ 41","title":"Personalvertretung","children":[{"type":"subparagraph","label":"(1)","text":"Für den NDR finden das Bundespersonalvertretungsgesetz und die dazu ergangenen Rechtsverordnungen nach Maßgabe der für die Rundfunkanstalten des Bundesrechts geltenden Vorschriften entsprechende Anwendung. Das gilt auch für rechtsfähige Gemeinschaftseinrichtungen der Rundfunkanstalten, an denen der NDR beteiligt ist und die ihren Sitz in einem der vier Länder haben.","children":[]},{"type":"subparagraph","label":"(2)","text":"In den Fällen des § 71 Absatz 1 Satz 4 des Bundespersonalvertretungsgesetzes bestellt der Präsident oder die Präsidentin des Oberverwaltungsgerichts des nach § 39 aufsichtführenden Landes nach Anhörung der Präsidenten oder Präsidentinnen der Oberverwaltungsgerichte der übrigen Länder den Vorsitzenden oder die Vorsitzende der Einigungsstelle.","children":[]},{"type":"subparagraph","label":"(3)","text":"Arbeitnehmerähnliche Personen im Sinne des § 12a Tarifvertragsgesetz gelten als Beschäftigte im Sinne des § 4 Absatz 3 Bundespersonalvertretungsgesetzes . Für sie gelten die gleichen Personalvertretungsrechte wie für Beschäftigte, soweit ihr Vertrag mit dem NDR entsprechende Verpflichtungen enthält und die gesetzlichen Vorgaben Anwendung finden können.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 42, 0, 1, '{"type":"paragraph","label":"§ 42","title":"Statut für die Programmmitarbeitenden","children":[{"type":"subparagraph","label":"(1)","text":"Die Mitwirkungsrechte der redaktionellen Mitarbeitenden in Programmangelegenheiten richten sich nach dem Redaktionsstatut.","children":[]},{"type":"subparagraph","label":"(2)","text":"Das Redaktionsstatut tritt außer Kraft, sobald sich der Intendant oder die Intendantin und die redaktionellen Mitarbeitenden auf ein neues Redaktionsstatut verständigt haben, das die derzeit beim NDR geltenden Beteiligungsrechte wahrt und auch ständigen freien Programmmitarbeitenden angemessene Repräsentanz in der Redaktionsversammlung und im Redaktionsausschuss verschafft. Das neue Redaktionsstatut enthält insbesondere folgende Regelungen:","children":[]},{"type":"item","label":"1.","text":"Der Redaktionsausschuss behält vor allem die Aufgabe, sich nach Maßgabe des Redaktionsstatuts um eine Einigung bei Konflikten zu bemühen, die in Programmfragen zwischen Programmmitarbeitenden und ihren Vorgesetzten entstehen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Kann ein Konflikt in Programmfragen zwischen Intendant oder Intendantin und Redaktionsausschuss nicht beigelegt werden, so tritt auf Antrag ein Schlichtungsausschuss zusammen. Dieser besteht aus einem oder einer unparteiischen Vorsitzenden, einem Stellvertreter oder einer Stellvertreterin und aus Beisitzern, die für drei Jahre je zur Hälfte von dem Intendanten oder der Intendantin bestellt und vom Redaktionsausschuss entsandt werden. Der Schlichtungsausschuss beschließt eine Empfehlung an den Intendanten oder die Intendantin. Folgt der Intendant oder die Intendantin der Empfehlung nicht, hat er seine oder hat sie ihre Entscheidung gegenüber dem Schlichtungsausschuss zu begründen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(3)","text":"Änderungen des Redaktionsstatuts bedürfen der Zustimmung des Rundfunkrats.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 43, 0, 1, '{"type":"paragraph","label":"§ 43","title":"Datenverarbeitung zu journalistisch-redaktionellen Zwecken, Medienprivileg","children":[{"type":"subparagraph","label":"(1)","text":"Soweit der NDR personenbezogene Daten zu journalistischen Zwecken verarbeitet, ist es den hiermit befassten Personen untersagt, diese personenbezogenen Daten zu anderen Zwecken zu verarbeiten (Datengeheimnis). Diese Personen sind bei der Aufnahme ihrer Tätigkeit auf das Datengeheimnis zu verpflichten. Das Datengeheimnis besteht auch nach Beendigung ihrer Tätigkeit fort. Im Übrigen finden für die Datenverarbeitung zu journalistischen Zwecken von der Verordnung (EU) 2016/679 des Europäischen Parlaments und des Rates vom 27. April 2016 zum Schutz natürlicher Personen bei der Verarbeitung personenbezogener Daten, zum freien Datenverkehr und zur Aufhebung der Richtlinie 95/46/EG (Datenschutz-Grundverordnung) (ABl. EU 2016 Nr. L 119 S. 1, L 314 S. 72, 2018 Nr. L 127 S. 2) außer den Kapiteln I, VIII, X und XI nur die Artikel 5 Absatz 1 Buchstabe f in Verbindung mit Absatz 2, Artikel 24 und Artikel 32 Anwendung. Die Artikel 82 und 83 der Verordnung (EU) 2016/679 gelten mit der Maßgabe, dass nur für eine Verletzung des Datengeheimnisses gemäß den Sätzen 1 bis 3 sowie für unzureichende Maßnahmen nach Artikel 5 Absatz 1 Buchstabe f , Artikel 24 und 32 der Verordnung (EU) 2016/679 gehaftet wird. Die Sätze 1 bis 5 gelten entsprechend für die Datenverarbeitung zu journalistischen Zwecken der Hilfs- und Beteiligungsunternehmen des NDR. Der NDR kann sich einen Verhaltenskodex geben, der in einem transparenten Verfahren erlassen und veröffentlicht wird. Den betroffenen Personen stehen nur die in den Absätzen 2 und 3 genannten Rechte zu.","children":[]},{"type":"subparagraph","label":"(2)","text":"Führt die journalistische Verarbeitung personenbezogener Daten zur Verbreitung von Gegendarstellungen der betroffenen Person oder zu Verpflichtungserklärungen, Beschlüssen oder Urteilen über die Unterlassung der Verbreitung oder über den Widerruf des Inhalts der Daten, so sind diese Gegendarstellungen, Verpflichtungserklärungen und Widerrufe zu den gespeicherten Daten zu nehmen und dort für dieselbe Zeitdauer aufzubewahren wie die Daten selbst sowie bei einer Übermittlung der Daten gemeinsam mit diesen zu übermitteln.","children":[]},{"type":"subparagraph","label":"(3)","text":"Wird jemand durch eine Berichterstattung in seinem Persönlichkeitsrecht beeinträchtigt, kann die betroffene Person Auskunft über die der Berichterstattung zugrundeliegenden zu ihrer Person gespeicherten Daten verlangen. Die Auskunft kann nach Abwägung der schutzwürdigen Interessen der Beteiligten verweigert werden, soweit","children":[]},{"type":"item","label":"1.","text":"aus den Daten auf Personen, die bei der Vorbereitung, Herstellung oder Verbreitung von Rundfunksendungen mitwirken oder mitgewirkt haben, geschlossen werden kann,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"aus den Daten auf die Person des Einsenders oder des Gewährsträgers von Beiträgen, Unterlagen und Mitteilungen für den redaktionellen Teil geschlossen werden kann oder","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"durch die Mitteilung der recherchierten oder sonst erlangten Daten die journalistische Aufgabe durch Ausforschung des Informationsbestandes beeinträchtigt würde.","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"Die betroffene Person kann die unverzügliche Berichtigung unrichtiger personenbezogener Daten im Datensatz oder die Hinzufügung einer eigenen Darstellung von angemessenem Umfang verlangen. Die weitere Speicherung der personenbezogenen Daten ist rechtmäßig, wenn dies für die Ausübung des Rechts auf freie Meinungsäußerung und Information oder zur Wahrnehmung berechtigter Interessen erforderlich ist."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 44, 0, 1, '{"type":"paragraph","label":"§ 44","title":"Ernennung des oder der Rundfunkdatenschutzbeauftragten","children":[{"type":"subparagraph","label":"(1)","text":"Der NDR ernennt einen Beauftragten oder eine Beauftragte für den Datenschutz beim NDR (Rundfunkdatenschutzbeauftragter oder Rundfunkdatenschutzbeauftragte), der oder die zuständige Aufsichtsbehörde im Sinne des Artikels 51 der Verordnung (EU) 2016/679 ist. Die Ernennung erfolgt durch den Rundfunkrat auf Vorschlag des Verwaltungsrats für die Dauer von vier Jahren. Eine dreimalige Wiederernennung ist zulässig. Der oder die Rundfunkdatenschutzbeauftragte muss über die für die Erfüllung seiner oder ihrer Aufgaben und Ausübung seiner oder ihrer Befugnisse erforderliche Qualifikation, Erfahrung und Sachkunde insbesondere im Bereich des Schutzes personenbezogener Daten verfügen. Das Amt des oder der Rundfunkdatenschutzbeauftragten kann nicht neben anderen Aufgaben innerhalb des NDR und seiner Beteiligungs- und Hilfsunternehmen wahrgenommen werden. Sonstige Aufgaben müssen mit dem Amt des oder der Rundfunkdatenschutzbeauftragten zu vereinbaren sein und dürfen seine oder ihre Unabhängigkeit nicht gefährden.","children":[]},{"type":"subparagraph","label":"(2)","text":"Das Amt endet mit Ablauf der Amtszeit, mit Rücktritt vom Amt oder mit Erreichen des gesetzlichen Renteneintrittsalters. Tarifvertragliche Regelungen bleiben unberührt. Der oder die Rundfunkdatenschutzbeauftragte kann seines oder ihres Amtes nur enthoben werden, wenn er oder sie eine schwere Verfehlung begangen hat oder die Voraussetzungen für die Wahrnehmung seiner oder ihrer Aufgaben nicht mehr erfüllt. Dies geschieht durch Beschluss des Verwaltungsrates auf Vorschlag des Rundfunkrates; der oder die Rundfunkdatenschutzbeauftragte ist vor der Entscheidung zu hören.","children":[]},{"type":"subparagraph","label":"(3)","text":"Das Nähere, insbesondere die Grundsätze der Vergütung, beschließt der Verwaltungsrat mit Zustimmung des Rundfunkrats in einer Satzung.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 45, 0, 1, '{"type":"paragraph","label":"§ 45","title":"Unabhängigkeit des oder der Rundfunkdatenschutzbeauftragten","children":[{"type":"subparagraph","label":"(1)","text":"Der oder die Rundfunkdatenschutzbeauftragte ist in Ausübung seines oder ihres Amtes unabhängig und nur dem Gesetz unterworfen. Er oder sie unterliegt keiner Rechts- oder Fachaufsicht. Der Dienstaufsicht des Verwaltungsrates untersteht er oder sie nur insoweit, als seine oder ihre Unabhängigkeit bei der Ausübung seines oder ihres Amtes dadurch nicht beeinträchtigt wird.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Dienststelle des oder der Rundfunkdatenschutzbeauftragten wird bei der Geschäftsstelle von Rundfunkrat und Verwaltungsrat eingerichtet. Dem oder der Rundfunkdatenschutzbeauftragten ist die für die Erfüllung seiner oder ihrer Aufgaben und Befugnisse notwendige Personal-, Finanz- und Sachausstattung zur Verfügung zu stellen. Die erforderlichen Mittel sind jährlich, öffentlich und gesondert im Haushaltsplan des NDR auszuweisen und dem oder der Rundfunkdatenschutzbeauftragten im Haushaltsvollzug zuzuweisen. Einer Finanzkontrolle durch den Verwaltungsrat unterliegt der oder die Rundfunkdatenschutzbeauftragte nur insoweit, als seine oder ihre Unabhängigkeit bei der Ausübung seines oder ihres Amtes dadurch nicht beeinträchtigt wird.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der oder die Rundfunkdatenschutzbeauftragte ist in der Wahl seiner oder ihrer Mitarbeitenden frei. Sie unterstehen allein seiner oder ihrer Leitung.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 46, 0, 1, '{"type":"paragraph","label":"§ 46","title":"Aufgaben des oder der Rundfunkdatenschutzbeauftragten","children":[{"type":"subparagraph","label":"(1)","text":"Der oder die Rundfunkdatenschutzbeauftragte überwacht die Einhaltung der Datenschutzvorschriften dieses Staatsvertrages, des Medienstaatsvertrages, der Verordnung (EU) 2016/679 und anderer Vorschriften über den Datenschutz bei der gesamten Tätigkeit des NDR und seiner Beteiligungsunternehmen im Sinne des § 42 Absatz 3 Satz 1 des Medienstaatsvertrages . Er oder sie hat die Aufgaben und Befugnisse entsprechend der Artikel 57 und 58 Absatz 1 bis Absatz 5 der Verordnung (EU) 2016/679 . Bei der Zusammenarbeit mit anderen Aufsichtsbehörden hat er oder sie, soweit die Datenverarbeitung zu journalistischen Zwecken betroffen ist, den Informantenschutz zu wahren. Er oder sie kann gegenüber dem NDR keine Geldbußen verhängen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Stellt der oder die Rundfunkdatenschutzbeauftragte Verstöße gegen Vorschriften über den Datenschutz oder sonstige Mängel bei der Verarbeitung personenbezogener Daten fest, so beanstandet er oder sie dies gegenüber dem Intendanten oder der Intendantin und fordert ihn oder sie zur Stellungnahme innerhalb einer angemessenen Frist auf. Gleichzeitig unterrichtet er oder sie den Verwaltungsrat. Von einer Beanstandung und Unterrichtung kann abgesehen werden, wenn es sich um unerhebliche Mängel handelt oder wenn ihre unverzügliche Behebung sichergestellt ist.","children":[]},{"type":"subparagraph","label":"(3)","text":"Die von dem Intendanten oder der Intendantin nach Absatz 2 Satz 1 abzugebende Stellungnahme soll auch eine Darstellung der Maßnahmen enthalten, die aufgrund der Beanstandung des oder der Rundfunkdatenschutzbeauftragten getroffen worden sind. Der Intendant oder die Intendantin leitet dem Verwaltungsrat gleichzeitig eine Abschrift der Stellungnahme gegenüber dem oder der Rundfunkdatenschutzbeauftragten zu.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der oder die Rundfunkdatenschutzbeauftragte erstattet jährlich auch den Organen des NDR den schriftlichen Bericht im Sinne des Artikels 59 der Verordnung (EU) 2016/679 über seine oder ihre Tätigkeit. Der Bericht wird veröffentlicht, wobei eine Veröffentlichung im Online-Angebot des NDR ausreichend ist.","children":[]},{"type":"subparagraph","label":"(5)","text":"Jedermann hat das Recht, sich unmittelbar an den Rundfunkdatenschutzbeauftragten oder die Rundfunkdatenschutzbeauftragte zu wenden, wenn er der Ansicht ist, bei der Verarbeitung seiner personenbezogenen Daten durch den NDR oder seiner Beteiligungsunternehmen im Sinne des Absatz 1 Satz 1 in seinen schutzwürdigen Belangen verletzt zu sein.","children":[]},{"type":"subparagraph","label":"(6)","text":"Der oder die Rundfunkdatenschutzbeauftragte ist sowohl während als auch nach Beendigung seiner oder ihrer Tätigkeit verpflichtet, über die ihm oder ihr während seiner oder ihrer Dienstzeit bekannt gewordenen Angelegenheiten und vertraulichen Informationen Verschwiegenheit zu bewahren.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 47, 0, 1, '{"type":"paragraph","label":"§ 47","title":"Informationszugang","children":[{"type":"subparagraph","label":"(1)","text":"Jede natürliche oder juristische Person mit Sitz in Deutschland hat nach Maßgabe dieser Bestimmung einen Anspruch auf freien Zugang zu den Informationen, über die der NDR als informationspflichtige Stelle verfügt. Von diesem Anspruch sind Informationen, über die der NDR zu journalistisch-redaktionellen Zwecken verfügt, ausgeschlossen.","children":[]},{"type":"subparagraph","label":"(2)","text":"Begriffsbestimmungen:","children":[]},{"type":"item","label":"1.","text":"Informationen sind alle in Schrift-, Bild-, Ton- oder Datenverarbeitungsform oder auf sonstigen Informationsträgern bei informationspflichtigen Stellen vorhandene Zahlen, Daten, Fakten, Erkenntnisse oder sonstige Auskünfte.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Informationsträger sind alle Medien, die Informationen in Schrift-, Bild-, Ton- oder Datenverarbeitungsform oder in sonstiger Form speichern können.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Die Informationspflicht ist die Pflicht, Informationen auf Antrag nach Maßgabe dieser Regelung zugänglich zu machen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"Der NDR verfügt über Informationen, wenn diese bei ihm vorhanden sind oder an anderer Stelle für ihn bereitgehalten werden. Ein Bereithalten liegt vor, wenn der NDR einen Anspruch auf Übermittlung der Informationen hat.","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(3)","text":"Informationen werden auf Antrag zugänglich gemacht. Der Antrag kann nur in Textform gestellt werden. Im Antrag sind die beanspruchten Informationen zu bezeichnen. Ist der Antrag zu unbestimmt, so ist der oder die Antragstellende unverzüglich, spätestens innerhalb eines Monats, aufzufordern, den Antrag zu präzisieren. Nach Eingang des präzisierten Antrags beim NDR beginnt die Frist zur Beantwortung des Antrags erneut. Der NDR unterstützt Antragstellende bei der Stellung und Präzisierung von Anträgen.","children":[]},{"type":"subparagraph","label":"(4)","text":"Der NDR hat dem oder der Antragstellenden Auskunft zu erteilen, Akteneinsicht zu gewähren, Kopien, auch durch Versendung, zur Verfügung zu stellen oder die Informationsträger zugänglich zu machen, die die begehrten Informationen enthalten. Wird eine bestimmte Art des Informationszugangs begehrt, so darf diese nur aus wichtigem Grund auf andere Art gewährt werden. In den übrigen Fällen soll die kostengünstigste Form gewählt werden. Sind die Informationen bereits öffentlich zugänglich, kann der NDR darauf verweisen. Handelt es sich um Dokumente, die nur vorübergehend von einer anderen Stelle beigezogen worden sind, so weist der NDR darauf hin und nennt die für die Entscheidung über die Akteneinsicht zuständige Stelle.","children":[]},{"type":"subparagraph","label":"(5)","text":"Liegen die Voraussetzungen des Auskunftsanspruchs vor, sind die Informationen der oder dem Antragstellenden zeitnah, spätestens jedoch binnen eines Monats nach Eingang des Antrags beim NDR zugänglich zu machen. In begründeten Fällen kann die Frist auf höchstens zwei Monate verlängert werden. Der oder die Antragstellende ist unter Angabe der Gründe unverzüglich auf die Fristverlängerung hinzuweisen.","children":[]},{"type":"subparagraph","label":"(6)","text":"Wird der Antrag ganz oder teilweise abgelehnt, ist dies dem oder der Antragstellenden innerhalb der Fristen nach Absatz 5 unter Angabe der Gründe mitzuteilen. Eine Ablehnung liegt auch dann vor, wenn der Informationszugang anders als beantragt gewährt wird. Die Ablehnung kann auf dieselbe Weise mitgeteilt werden, wie der Antrag gestellt wurde. Liegt ein Ablehnungsgrund nach den Absätzen 8 und 9 vor, sind die hiervon nicht betroffenen Informationen zugänglich zu machen, soweit sie ausgesondert werden können. Der oder die Antragstellende ist im Falle einer vollständigen oder teilweisen Ablehnung eines Antrages über die Rechtsschutzmöglichkeiten gegen diese Entscheidung sowie darüber zu belehren, bei welcher Stelle und innerhalb welcher Frist um Rechtsschutz nachgesucht werden kann.","children":[]},{"type":"subparagraph","label":"(7)","text":"Für Streitigkeiten nach dieser Vorschrift ist der Verwaltungsrechtsweg gegeben. Ein Widerspruchsverfahren ist nicht durchzuführen.","children":[]},{"type":"subparagraph","label":"(8)","text":"Soweit die Bekanntgabe der Informationen nachteilige Auswirkungen auf","children":[]},{"type":"item","label":"1.","text":"die Vertraulichkeit der Beratungen der Gremien des NDR oder","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"die Durchführung eines laufenden Gerichtsverfahrens, eines Ermittlungsverfahrens, eines Ordnungswidrigkeitenverfahrens oder eines Disziplinarverfahrens hätte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"ist der Antrag abzulehnen, wenn das schutzwürdige Interesse des NDR an der Geheimhaltung gegenüber dem öffentlichen Bekanntgabeinteresse überwiegt. Der Antrag ist auch abzulehnen, wenn der Antrag offensichtlich missbräuchlich gestellt wurde."},{"type":"subparagraph","label":"(9)","text":"Soweit durch die Bekanntgabe der Information","children":[]},{"type":"item","label":"1.","text":"personenbezogene Daten offenbart würden, deren Vertraulichkeit durch Rechtsvorschrift vorgesehen ist,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Rechte am geistigen Eigentum, insbesondere Urheberrechte, verletzt würden,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Betriebs- oder Geschäftsgeheimnisse zugänglich gemacht würden oder Informationen dem Steuer- oder Statistikgeheimnis unterliegen oder","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"die Interessen einer Person beeinträchtigt würden, die die beantragte Information, ohne rechtlich hierzu verpflichtet werden zu können, dem NDR freiwillig zur Verfügung gestellt hat","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"und das aus den Nummern 1 bis 4 jeweils folgende schutzwürdige Interesse an der Geheimhaltung gegenüber dem öffentlichen Bekanntgabeinteresse überwiegt, ist der Antrag abzulehnen, es sei denn, die jeweils Betroffenen haben zugestimmt. Die Betroffenen sind vor der Entscheidung über die Offenbarung anzuhören."},{"type":"subparagraph","label":"(10)","text":"Für die Bereitstellung von Informationen nach dieser Vorschrift werden Kosten (Gebühren und Auslagen) erhoben. Gebühren werden nicht erhoben für","children":[]},{"type":"item","label":"1.","text":"die Erteilung mündlicher, einfacher schriftlicher und einfacher elektronischer Auskünfte und","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"die Einsichtnahme vor Ort.","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"Die Gebühren sind auch unter Berücksichtigung des Verwaltungsaufwandes so zu bemessen, dass das Recht auf Zugang zu Informationen wirksam in Anspruch genommen werden kann. Das Nähere regelt die Satzung."},{"type":"subparagraph","label":"(11)","text":"Antragstellende, die der Ansicht sind, dass der Informationsanspruch zu Unrecht abgelehnt oder nicht beachtet worden ist oder dass nur eine unzulängliche Antwort gegeben worden ist, können den Rundfunkdatenschutzbeauftragten oder die Rundfunkdatenschutzbeauftragte des NDR anrufen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 48, 0, 1, '{"type":"paragraph","label":"§ 48","title":"Archivierung","children":[{"type":"paragraphText","text":"Der NDR entscheidet in eigener Zuständigkeit, ob Unterlagen dem Staatsarchiv Hamburg angeboten und übergeben oder in eigener Verantwortung archiviert werden."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 49, 0, 1, '{"type":"paragraph","label":"§ 49","title":"Kündigung","children":[{"type":"subparagraph","label":"(1)","text":"Dieser Staatsvertrag kann von jedem Land frühestens zum 31. August 2026 gekündigt werden. Die Kündigungsfrist beträgt zwei Jahre. Wird der Staatsvertrag nicht gekündigt, verlängert er sich stillschweigend um jeweils fünf Jahre. Kündigt ein Land, kann jedes andere innerhalb von drei Monaten nach Zugang der Kündigung erklären, dass es sich dieser anschließt; zwischen den übrigen Ländern bleibt der Staatsvertrag in Kraft. Im Falle der Kündigung durch mindestens drei Länder tritt der Staatsvertrag nach Ablauf der Kündigungsfrist außer Kraft und der NDR als Rundfunkanstalt ist aufgelöst.","children":[]},{"type":"subparagraph","label":"(2)","text":"Nach einer Kündigung oder Auflösung des NDR durch Vereinbarung schließen die Länder einen Staatsvertrag über die Auseinandersetzung.","children":[]},{"type":"subparagraph","label":"(3)","text":"Für den Fall, dass ein Staatsvertrag über die Auseinandersetzung nicht innerhalb eines Jahres abgeschlossen wird, entscheidet ein Schiedsgericht über die Auseinandersetzung. Das Schiedsgericht kann auch eine einstweilige Regelung treffen.","children":[]},{"type":"subparagraph","label":"(4)","text":"Einigen sich die Länder nicht über die Zusammensetzung des Schiedsgerichts, ernennen die Präsidenten oder Präsidentinnen der Oberverwaltungsgerichte der Freien und Hansestadt Hamburg und der Länder Mecklenburg-Vorpommern, Niedersachsen und Schleswig-Holstein gemeinsam ein aus vier Mitgliedern bestehendes Schiedsgericht. Die Schiedsrichter oder die Schiedsrichterinnen müssen die Befähigung zum Richteramt besitzen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 50, 0, 1, '{"type":"paragraph","label":"§ 50","title":"Beitritt","children":[{"type":"paragraphText","text":"Andere Länder können diesem Staatsvertrag beitreten. Der Beitritt bedarf eines Staatsvertrages der beteiligten Länder."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 51, 0, 1, '{"type":"paragraph","label":"§ 51","title":"Übergangsbestimmung","children":[{"type":"paragraphText","text":"Die Zusammensetzung sowie die Rechte und Pflichten der Mitglieder des Rundfunkrats, des Verwaltungsrats und ihrer jeweiligen Ausschüsse, bleiben bis zum Ablauf der zum Zeitpunkt des Inkrafttretens dieses Staatsvertrages laufenden Amtsperioden unberührt."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 52, 0, 1, '{"type":"paragraph","label":"§ 52","title":"Inkrafttreten, Außerkrafttreten","children":[{"type":"subparagraph","label":"(1)","text":"Dieser Staatsvertrag tritt am 1. September 2021 in Kraft. Sind bis zum 31. August 2021 nicht alle Ratifikationsurkunden bei der Senatskanzlei der Freien und Hansestadt Hamburg hinterlegt, wird der Staatsvertrag gegenstandslos.","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Senatskanzlei der Freien und Hansestadt Hamburg teilt den übrigen Ländern die Hinterlegung der Ratifikationsurkunden mit.","children":[]},{"type":"subparagraph","label":"(3)","text":"Der Staatsvertrag über den Norddeutschen Rundfunk (NDR) vom 17./18. November 1991, der Staatsvertrag über den Datenschutz beim Norddeutschen Rundfunk (NDR-Datenschutz-Staatsvertrag) vom 7. bis 15. Dezember 2017 und der Staatsvertrag über die Veranstaltung von digitalen terrestrischen Hörfunkprogrammen durch den Norddeutschen Rundfunk (NDR-Digitalradio-Staatsvertrag) vom 1./2. Februar 2012, jeweils in der geltenden Fassung, treten zum Zeitpunkt des Inkrafttretens dieses Staatsvertrages außer Kraft.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 53, 0, 1, '{"type":"annex","label":"Anhang","title":"Protokollerklärung aller Länder zum NDR-Staatsvertrag","children":[{"type":"paragraphText","text":"Die Länder bewerten die Integration der arbeitnehmerähnlichen Personen in die Personalvertretung des NDR als einen wichtigen Schritt für die Mitbestimmung im NDR ( § 41 NDR-Staatsvertrag ). Sie nehmen in Aussicht, zeitnah das Mitbestimmungsrecht des NDR insgesamt daraufhin zu überprüfen, ob der Verweis auf das Bundespersonalvertretungsgesetz durch eine für den NDR spezifische Regelung ersetzt werden kann und dabei auch weitere Möglichkeiten der Einbindung der arbeitnehmerähnlichen Personen in das Personalvertretungsregime beim NDR staatsvertraglich zu regeln."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 54, 0, 1, '{"type":"signature","title":"Für den Senat der Freien und Hansestadt Hamburg","text":"Hamburg, den 4. März 2021, gez. Dr. Peter Tschentscher"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 55, 0, 1, '{"type":"signature","title":"Für das Land Mecklenburg-Vorpommern","text":"Schwerin, den 9. März 2021, gez. Manuela Schwesig"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 56, 0, 1, '{"type":"signature","title":"Für das Land Niedersachsen","text":"Hannover, den 5. März 2021, gez. Stephan Weil"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ndr-staatsvertrag', '2026-09-03', 57, 0, 1, '{"type":"signature","title":"Für das Land Schleswig-Holstein","text":"Kiel, den 8. März 2021, gez. Daniel Günther"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('oberstufenund-abiturprufungsverordnung', '2024-10-15', 0, 0, 1, '{"type":"paragraph","label":"§§ 1 bis 8","children":[{"type":"paragraphText","text":"uverändert"}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('oberstufenund-abiturprufungsverordnung', '2024-10-15', 1, 0, 1, '{"type":"paragraph","label":"§ 8","title":"Wahl der Leistungskurse","children":[{"type":"item","label":"1)","text":"Jeder Schüler mit Ausnahme der in Absatz 3 genannten Schüler wählt aus dem Angebot seiner Schule Leistungskurse in zwei Fächern des Pflichtbereichs. Erstes Leistungskursfach ist Deutsch, Mathematik oder eine fortgeführte Fremdsprache. Folgende Leistungskurskombinationen sind zulässig.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"1.","text":"Deutsch – Mathematik","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Deutsch – fortgeführt Fremdsprache,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Deutsch – Biologie oder Chemie oder Physik,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"Deutsch – Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5.","text":"Deutsch – Gesellschaft, Rechtswissenschaften und Wirtschaft,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"6.","text":"Mathematik – Gesellschaft, Rechtswissenschaften und Wirtschaft,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"7.","text":"Mathematik – fortgeführte Fremdsprache,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"8.","text":"Mathematik – Biologie oder Chemie oder Physik,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"9.","text":"Mathematik – Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"10.","text":"fortgeführte Fremdsprache – Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"11.","text":"Gesellschaft, Rechtswissenschaften und Wirtschaft – Biologie oder Chemie – Physik,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"12.","text":"Gesellschaft, Rechtswissenschaften und Wirtschaft – fortgeführte Fremdsprache,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"13.","text":"Gesellschaft, Rechtswissenschaften und Wirtschaft – Geschichte.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2)","text":"Leistungskurse in Kunst und Musik sind nur an Schulen mit künstlerischem Profil oder vertiefter musischer Ausbildung gemäß § 4 Abs. 1 Buchst. a SOGY anzubieten. Sie können nur von Schülern, die dieses Profil in der Sekundarstufe I besucht haben, sowie von Schülern, die gleichwertige Leistungsnachweise erbringen, gewählt werden. Im Falle von Satz 1 ist an den Schulen mit künstlerischem Profil das erste Leistungskursfach Deutsch oder Mathematik.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3)","text":"Jeder Schüler in der vertieften Ausbildung gemäß § 4 SOGY wählt Leistungskurse in drei Fächern des Pflichtbereichs. Folgende Leistungskurskombinationen sind zulässig:","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"1.","text":"Bei vertiefter mathematisch-naturwissenschaftlicher Ausbildung.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"1)","text":"Mathematik mit Biologie oder Chemie oder Physik und Deutsch oder fortgeführter Fremdsprache oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2)","text":"Mathematik mit Deutsch und fortgeführter Fremdsprache oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3)","text":"Mathematik mit fortgeführter Fremdsprache und Deutsch oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4)","text":"Physik mit Biologie oder Chemie und Deutsch oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5)","text":"Physik mit Deutsch und fortgeführter Fremdsprache oder Geschichte.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Bei vertiefter musischer Ausbildung:","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"1)","text":"Deutsch mit Musik und Mathematik oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2)","text":"fortgeführte Fremdsprache mit Musik und Mathematik oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3)","text":"Mathematik mit Musik und Deutsch oder fortgeführter Fremdsprache oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4)","text":"Physik mit Musik und Deutsch oder Geschichte.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Bei vertiefter sportlicher Ausbildung:","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"1)","text":"Deutsch mit Sport und Mathematik oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2)","text":"fortgeführte Fremdsprache mit Sport und Mathematik oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3)","text":"Mathematik mit Sport und Deutsch oder fortgeführter Fremdsprache oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4)","text":"Physik mit Sport und Deutsch oder Geschichte.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"Bei vertiefter sprachlicher Ausbildung:","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"1)","text":"fortgeführte Fremdsprache mit Deutsch und Mathematik oder Physik oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2)","text":"fortgeführte Fremdsprache mit weiterer fortgeführter Fremdsprache und Mathematik oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3)","text":"fortgeführte Fremdsprache mit Physik und Deutsch oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4)","text":"fortgeführte Fremdsprache mit Geschichte und Deutsch oder Mathematik oder weiterer fortgeführter Fremdsprache oder Biologie oder Chemie oder Physik,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5)","text":"fortgeführte Fremdsprache mit Mathematik und Biologie oder Chemie oder Physik.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5.","text":"Bei vertiefter Ausbildung im binationalen Bildungsgang:","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"1)","text":"Polnisch beziehungsweise Tschechisch mit Mathematik und Biologie oder Chemie oder Physik oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2)","text":"Polnisch beziehungsweise Tschechisch mit Englisch und Mathematik oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3)","text":"Polnisch beziehungsweise Tschechisch mit Physik und Deutsch oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4)","text":"Polnisch beziehungsweise Tschechisch mit Deutsch und Mathematik oder Physik oder Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5)","text":"Polnisch beziehungsweise Tschechisch mit Geschichte und Biologie oder Chemie.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"6.","text":"Am sorbischen Gymnasium Bautzen sind neben den gemäß Absatz 1 zulässigen Leistungskurskombinationen folgende Leistungskurskombinationen zulässig:","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"1)","text":"Deutsch – Sorbisch,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2)","text":"Mathematik – Sorbisch,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3)","text":"fortgeführte Fremdsprache – Sorbisch,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4)","text":"Sorbisch – Geschichte,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5)","text":"Sorbisch – Biologie oder Chemie oder Physik. Im Abiturprüfungsbereich wird in den Fällen der Nummer 5 Buchst. a bis d ein Leistungskursfach, in den Fällen der Nummern 1 und 4 sowie Nummer 5 Buchst. e nach Wahl des Schülers das jeweils zweite oder dritte Leistungskursfach, in den Fällen der Nummern 2 und 3 das jeweils dritte Leistungskursfach als Grundkursfach gewertet und nach Wahl des Schülers schriftlich (P3 gemäß § 27 Abs. 2 Nr. 3) oder mündlich (P4 gemäß § 27 Abs. 2 Nr. 4) geprüft. Bei der Wahl des Faches Sorbisch gemäß Nummer 6 Buchst. b bis e als Leistungskursfach findet § 27 Abs. 5 Satz 1 hinsichtlich des Faches Deutsch keine Anwendung. Davon unberührt bleibt die Verpflichtung, die Leistungen aus vier Grundkursen im Fach Deutsch in die Gesamtqualifikation einzubringen.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4)","text":"Im Falle des Absatzes 3 Nr. 1 bis 5 ist auf dem Zeugnis der allgemeinen Hochschulreife unter dem Feld „Bemerkungen“ folgendes aufzunehmen: „Das Fach ... wurde auf Leistungskursniveau unterrichtet und im Abiturprüfungsbereich als Grundkursfach gewertet und geprüft.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5)","text":"Sollte eine Schule weniger als fünfzig Lehrer in Vollzeit angestellt haben, so finden die Buchstaben 4, 5, 10 und 14 des Absatzes 1 keine Anwendung.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"6)","text":"Die Vorgaben aus Absatz 1 Buchstabe 5, 6, 11, 12 und 13 treten zum Eginn des Schuljahres 2025/2026 in Kraft.","level":0,"numberingStyle":"decimal","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('oberstufenund-abiturprufungsverordnung', '2024-10-15', 2, 0, 1, '{"type":"paragraph","label":"§§ 9 bis 52","children":[{"type":"paragraphText","text":"unverändert"}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', 0, 0, 1, '{"type":"paragraphText","text":"Der Ostdeutsche Landtag hat am 13. Oktober 1992 das folgende Gesetz beschlossen:"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', 1, 0, 1, '{"type":"paragraph","label":"§ 1","title":"Gesetzliche Feiertage","children":[{"type":"subparagraph","label":"(1)","text":"Gesetzliche Feiertage sind:\nNeujahr (1. Januar),\nKarfreitag,\nOstermontag,\nTag der Arbeit (1. Mai),\nChristi Himmelfahrt,\nPfingstmontag,\nFronleichnam (nur in den vom Staatsministerium des Innern durch\nRechtsverordnung bestimmten Regionen),\nTag der Deutschen Einheit (3. Oktober),\nReformationsfest (31. Oktober),\nBuß- und Bettag,\n1. Weihnachtstag (25. Dezember),\n2. Weihnachtstag (26. Dezember).","children":[]},{"type":"subparagraph","label":"(2)","text":"Die gesetzlichen Feiertage sind Feiertage im Sinne bundes- und landesrechtlicher Vorschriften.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', 2, 0, 1, '{"type":"paragraph","label":"§ 2","title":"Gedenk- und Trauertage","children":[{"type":"paragraphText","text":"Gedenk- und Trauertage im Sinne dieses Gesetzes sind der Volkstrauertag (vorletzter Sonntag vor dem 1. Advent) und der Totensonntag (letzter Sonntag vor dem 1. Advent)."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', 3, 0, 1, '{"type":"paragraph","label":"§ 2a","title":"Örtlicher Gedenktag an die friedliche Revolution 1989","children":[{"type":"paragraphText","text":"Die Gemeinden können einen örtlichen Gedenktag zur Erinnerung an die friedliche Revolution des Jahres 1989 durch Satzung bestimmen."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', 4, 0, 1, '{"type":"paragraph","label":"§ 3","title":"Religiöse Feiertage","children":[{"type":"subparagraph","label":"(1)","text":"Religiöse Feiertage im Sinne dieses Gesetzes sind:\nErscheinungsfest (6. Januar),\nFrühjahrsbußtag (7. Mittwoch vor Ostern),\nGründonnerstag,\nFronleichnam (soweit nicht gesetzlicher Feiertag),\nJohannestag (24. Juni),\nPeter und Paul (29. Juni),\nMariä Himmelfahrt (15. August),\nAllerheiligen (1. November),\nMariä Empfängnis (8. Dezember).","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Staatsregierung wird ermächtigt, durch Rechtsverordnung weitere religiöse Feiertage festzulegen, soweit hierfür aufgrund der Bedeutung einer Religionsgemeinschaft nach Tradition oder Mitgliederzahl ein Bedürfnis besteht.","children":[]},{"type":"subparagraph","label":"(3)","text":"An den in Absatz 1 genannten und den nach Absatz 2 festgelegten religiösen Feiertagen haben","children":[]},{"type":"item","label":"1.","text":"Schüler und Auszubildende das Recht, dem Unterricht oder der Ausbildung fernzubleiben,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Personen, die in einem Beschäftigungsverhältnis stehen, das Recht, der Arbeit fernzubleiben, wenn keine zwingenden betrieblichen Erfordernisse entgegenstehen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"paragraphText","text":"soweit und solange dies erforderlich ist, um am Hauptgottesdienst ihrer Religionsgemeinschaft teilzunehmen."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', 5, 0, 1, '{"type":"paragraph","label":"§ 4","title":"Allgemeine Schutzvorschrift","children":[{"type":"subparagraph","label":"(1)","text":"Die Sonntage und die gesetzlichen Feiertage sind als Tage der Arbeitsruhe und seelischen Erhebung nach Maßgabe der gewerbe- und arbeitsrechtlichen Vorschriften sowie der Bestimmungen dieses Gesetzes geschützt.","children":[]},{"type":"subparagraph","label":"(2)","text":"An den Sonntagen und den gesetzlichen Feiertagen sind öffentlich bemerkbare Arbeiten und sonstige Handlungen, die geeignet sind, die Ruhe des Tages zu beeinträchtigen, verboten, soweit nicht durch Gesetz oder aufgrund eines Gesetzes etwas anderes bestimmt ist.","children":[]},{"type":"subparagraph","label":"(3)","text":"Absatz 2 gilt nicht für","children":[]},{"type":"item","label":"1.","text":"den Betrieb der Post, der Eisenbahnen und sonstiger Unternehmen, die der Personenbeförderung dienen, sowie der Hilfseinrichtungen des Verkehrs mit der Maßgabe, daß Instandsetzungsarbeiten an Kraftfahrzeugen nur vorgenommen werden dürfen, soweit sie für die Weiterfahrt erforderlich sind;","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"unaufschiebbare Arbeiten, die erforderlich sind","level":0,"numberingStyle":"decimal","children":[{"type":"item","label":"a)","text":"zur Abwendung eines Schadens an Gesundheit oder Eigentum,","level":1,"numberingStyle":"lower-latin","children":[]},{"type":"item","label":"b)","text":"zur Befriedigung häuslicher Bedürfnisse,","level":1,"numberingStyle":"lower-latin","children":[]},{"type":"item","label":"c)","text":"in landwirtschaftlichen Betrieben, insbesondere zur Ernte,","level":1,"numberingStyle":"lower-latin","children":[]},{"type":"item","label":"d)","text":"zur Be- oder Verarbeitung leicht verderblicher Nahrungsmittel und zur Versorgung der Bevölkerung mit Milch;","level":1,"numberingStyle":"lower-latin","children":[]}]},{"type":"item","label":"3.","text":"leichte Arbeiten nicht gewerblicher Art in Gärten, die keine störenden Geräusche verursachen,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"4.","text":"den Betrieb von Videotheken an den Sonntagen zwischen 12.00 und 20.00 Uhr.","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"5.","text":"den Betrieb von","level":0,"numberingStyle":"decimal","children":[{"type":"item","label":"a)","text":"vollautomatischen, gemeinsam mit Tankstellen betriebenen, Waschanlagen in geschlossener Bauform für Personenkraftwagen an den Sonntagen zwischen 8.00 und 20.00 Uhr,","level":1,"numberingStyle":"lower-latin","children":[]},{"type":"item","label":"b)","text":"gemeinsam mit Tankstellen betriebenen Selbstwaschanlagen für Personenkraftwagen an den Sonntagen zwischen 12.00 und 20.00 Uhr,","level":1,"numberingStyle":"lower-latin","children":[]},{"type":"item","label":"c)","text":"automatischen Waschanlagen und Selbstwaschanlagen für Personenkraftwagen in durch Bebauungsplan festgesetzten Gewerbe- und Industriegebieten an den Sonntagen zwischen 12.00 und 20.00 Uhr.","level":1,"numberingStyle":"lower-latin","children":[]}]},{"type":"paragraphText","text":"Satz 1 Nr. 4 und 5 gilt nicht für den Ostersonntag und Pfingstsonntag sowie für solche Sonntage, auf die ein gesetzlicher Feiertag nach § 1 Abs. 1 oder ein Gedenk- und Trauertag nach § 2 fällt."},{"type":"subparagraph","label":"(4)","text":"Soweit Arbeiten an Sonntagen und gesetzlichen Feiertagen zulässig sind, ist auf das Wesen des Tages Rücksicht zu nehmen.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', 6, 0, 1, '{"type":"paragraph","label":"§ 5","title":"Schutz religiöser Veranstaltungen","children":[{"type":"paragraphText","text":"An den Sonntagen, religiösen und gesetzlichen Feiertagen, mit Ausnahme des 1. Mai und des 3. Oktober, sind in der Nähe von Kirchen und anderen Gebäuden, die religiösen Zwecken dienen, alle Handlungen zu unterlassen, die geeignet sind, religiöse Veranstaltungen zu stören. Dasselbe gilt am 24. Dezember für die Zeit ab 14.00 Uhr."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', 7, 0, 1, '{"type":"paragraph","label":"§ 6","title":"Besondere Schutzvorschriften","children":[{"type":"paragraphText","text":"Am Karfreitag, am Buß- und Bettag und an den Gedenk- und Trauertagen nach § 2 sind verboten:"},{"type":"item","label":"1.","text":"öffentliche Tanzveranstaltungen und andere öffentliche Vergnügungen, die dem ernsten Charakter dieser Tage zuwiderlaufen, am Karfreitag während des ganzen Tages, an den übrigen Tagen von 3.00 Uhr bis 24.00 Uhr;","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"öffentliche Sportveranstaltungen am Karfreitag während des ganzen Tages, an den übrigen Tagen bis 11.00 Uhr.","level":0,"numberingStyle":"decimal","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', 8, 0, 1, '{"type":"paragraph","label":"§ 7","title":"Befreiungen","children":[{"type":"subparagraph","label":"(1)","text":"Die Kreispolizeibehörden können im Einzelfall aus wichtigem Grund von den Verbotsvorschriften der §§ 4 und 6 befreien.","children":[]},{"type":"subparagraph","label":"(2)","text":"Vor der Erteilung einer Befreiung sind die betroffenen Religionsgemeinschaften zu hören. Dies gilt nicht, soweit sich die Befreiung auf den 1. Mai oder den 3. Oktober bezieht.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', 9, 0, 1, '{"type":"paragraph","label":"§ 8","title":"Ordnungswidrigkeiten","children":[{"type":"subparagraph","label":"(1)","text":"Ordnungswidrig handelt, wer vorsätzlich oder fahrlässig den Vorschriften über das Verbot","children":[]},{"type":"item","label":"1.","text":"öffentlich bemerkbarer Arbeiten und sonstiger Handlungen (§ 4 Abs. 2),","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"von Handlungen, die geeignet sind, religiöse Veranstaltungen zu stören (§ 5),","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"bestimmter Veranstaltungen an besonders geschützten Tagen (§ 6)","level":0,"numberingStyle":"decimal","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Ordnungswidrigkeit kann mit einer Geldbuße bis zu 5 000 EUR geahndet werden.","children":[]},{"type":"subparagraph","label":"(3)","text":"Verwaltungsbehörden im Sinne des § 36 Abs. 1 Nr. 1 des Gesetzes über Ordnungswidrigkeiten sind die Ortspolizeibehörden.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', 10, 0, 1, '{"type":"paragraph","label":"§ 9","title":"Grundrechtseinschränkung","children":[{"type":"paragraphText","text":"Das Grundrecht der Versammlungsfreiheit (Artikel 8 Abs. 2 des Grundgesetzes und Artikel 23 Abs. 2 der Verfassung des Freistaates Ostdeutschland) wird nach Maßgabe der §§ 5 und 6 eingeschränkt."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', 11, 0, 1, '{"type":"paragraph","label":"§ 10","title":"Außerkrafttreten von Rechtsvorschriften","children":[{"type":"paragraphText","text":"Folgende Rechtsvorschriften treten außer Kraft:"},{"type":"item","label":"1.","text":"§ 168 Abs. 2 des Arbeitsgesetzbuches der Deutschen Demokratischen Republik vom 16. Juni 1977 (GBl. I Nr. 18 S. 185), zuletzt geändert durch Gesetz vom 22. Juni 1990 (GBl. I Nr. 35 S. 371),","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Verordnung über die Einführung gesetzlicher Feiertage vom 16. Mai 1990 (GBl. I Nr. 27 S. 248),","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"3.","text":"Erste Durchführungsbestimmung vom 7. Juni 1990 zur Verordnung über die Einführung gesetzlicher Feiertage (GBl. I Nr. 31 S.281).","level":0,"numberingStyle":"decimal","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2023-11-01', 12, 0, 1, '{"type":"paragraph","label":"§ 11","title":"Inkrafttreten","children":[{"type":"paragraphText","text":"Dieses Gesetz tritt am Tage nach seiner Verkündung in Kraft."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2024-03-07', 0, 0, 1, '{"type":"paragraphText","text":"Der Ostdeutsche Landtag hat am 13. Oktober 1992 das folgende Gesetz beschlossen:"}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2024-03-07', 1, 0, 1, '{"type":"paragraph","label":"§ 1","title":"Gesetzliche Feiertage","children":[{"type":"subparagraph","label":"(1)","text":"Gesetzliche Feiertage sind:\nNeujahr (1. Januar),\nWeltfrauentag (8. März),\nKarfreitag,\nOstermontag,\nTag des Fastenbrechens,\nTag der Arbeit (1. Mai),\nChristi Himmelfahrt,\nPfingstmontag,\nFronleichnam (nur in den vom Staatsministerium des Innern durch Rechtsverordnung bestimmten Regionen),\nJom Kippur, (Zweiter Tag)\nWeltkindertag (20. September),\nTag der Deutschen Einheit (3. Oktober),\nReformationstag (31. Oktober),\n1. Weihnachtstag (25. Dezember),\n2. Weihnachtstag (26. Dezember).","children":[]},{"type":"subparagraph","label":"(2)","text":"Die gesetzlichen Feiertage sind Feiertage im Sinne bundes- und landesrechtlicher Vorschriften.","children":[]}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2024-03-07', 2, 0, 1, '{"type":"paragraph","label":"§ 2","title":"Gedenk- und Trauertage","children":[{"type":"paragraphText","text":"Gedenk- und Trauertage im Sinne dieses Gesetzes sind der Luxemburg-Liebknecht-Gedenktag (15. Januar), Volkstrauertag (vorletzter Sonntag vor dem 1. Advent) und der Totensonntag (letzter Sonntag vor dem 1. Advent)."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2024-03-07', 3, 0, 1, '{"type":"paragraph","label":"§ 2a","title":"Örtlicher Gedenktag an die friedliche Revolution 1989","children":[{"type":"paragraphText","text":"Die Gemeinden können einen örtlichen Gedenktag zur Erinnerung an die friedliche Revolution des Jahres 1989 durch Satzung bestimmen."}]}');
INSERT INTO law_version_blocks (norm_id, version_id, block_index, part_index, part_count, block_json) VALUES ('ostdeutsches-feiertagsgesetz', '2024-03-07', 4, 0, 1, '{"type":"paragraph","label":"§ 3","title":"Religiöse Feiertage","children":[{"type":"subparagraph","label":"(1)","text":"Religiöse Feiertage im Sinne dieses Gesetzes sind:\nErscheinungsfest (6. Januar),\nFrühjahrsbußtag (7. Mittwoch vor Ostern),\nGründonnerstag,\nFronleichnam (soweit nicht gesetzlicher Feiertag),\nVesakhfest,\nJohannestag (24. Juni),\nPeter und Paul (29. Juni),\nMariä Himmelfahrt (15. August),\nTag des Guru Nanak,\nLakshmi Puja,\nAllerheiligen (1. November),\nMariä Empfängnis (8. Dezember).","children":[]},{"type":"subparagraph","label":"(2)","text":"Die Staatsregierung wird ermächtigt, durch Rechtsverordnung weitere religiöse Feiertage festzulegen, soweit hierfür aufgrund der Bedeutung einer Religionsgemeinschaft nach Tradition oder Mitgliederzahl ein Bedürfnis besteht.","children":[]},{"type":"subparagraph","label":"(3)","text":"An den in Absatz 1 genannten und den nach Absatz 2 festgelegten religiösen Feiertagen haben","children":[{"type":"item","label":"1.","text":"Schüler und Auszubildende das Recht, dem Unterricht oder der Ausbildung fernzubleiben,","level":0,"numberingStyle":"decimal","children":[]},{"type":"item","label":"2.","text":"Personen, die in einem Beschäftigungsverhältnis stehen, das Recht, der Arbeit fernzubleiben, soweit und solange dies erforderlich ist, um am Hauptgottesdienst oder den Feierlichkeiten ihrer Religionsgemeinschaft teilzunehmen.","level":0,"numberingStyle":"decimal","children":[]}]}]}');
