INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (9001, 'gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo', '2026-03-23', '0', 'artikel-1', 'article', '{"article":"1"}', 'gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo', 'Gesetz über die Einführung einer kommunalen Privatisierungsbremse im Freistaat Ostdeutschland', 'Gesetz über die Einführung einer kommunalen Privatisierungsbremse im Freistaat Ostdeutschland', '', 'Artikel 1', 'Änderung der Gemeindeordnung', 'Die Sächsische Gemeindeordnung in der Fassung der Bekanntmachung vom 9. März 2018 (SächsGVBl. S. 62), die zuletzt durch Art. 5 des Gesetzes vom 28. November 2023 (SächsGVBl. S. 870) geändert worden ist, wird wie folgt geändert:

Die Bezeichnung des Gesetzes wird wie folgt gefasst:

,,Gemeindeordnung

für den Ostdeutschen Freistaat

(Ostdeutsche Gemeindeordnung – OstGemO)”

Dem § 90 wird folgender Absatz angefügt:

“(5) Durch Satzung kann die Gemeinde Unternehmen veräußern, auf welche sie aufgrund Eigentum, finanzieller Beteiligung, Satzung oder sonstiger Bestimmungen, welche die Tätigkeit des Unternehmens regeln, unmittelbar oder mittelbar einen beherrschenden Einfluss ausübt und die

Verkehrsleistungen oder Leistungen der Abfall- oder Abwasserentsorgung oder der Energie- oder Wasserversorgung für die Allgemeinheit erbringen,

wesentliche Beiträge zur wirtschaftlichen, verkehrlichen, städtebaulichen oder kulturellen Infrastruktur leisten,

geeignet sind, die Sicherung der Versorgung mit angemessenem Wohnraum zu fördern oder

der allgemeinen Versorgung der Bevölkerung mit Krankenhäusern dienen.

Der Beschluss über eine solche Satzung bedarf der Mehrheit von zwei Dritteln der Gemeinderäte oder eines erfolgreichen Bürgerentscheids nach § 24. Sie tritt nicht vor Ablauf von sechs Monaten nach ihrer Bekanntgabe in Kraft. Als Veräußerung gilt jedes Rechtsgeschäft, welches den beherrschenden Einfluss der Gemeinde beseitigt. Auf kleine Kapitalgesellschaften im Sinne des § 267 Absatz 1 des Handelsgesetzbuchs findet diese Vorschrift keine Anwendung. Gleiches gilt, wenn die Veräußerung bei Entstehen der Beherrschung beabsichtigt war und zeitnah erfolgt.“');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (9002, 'gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo', '2026-03-23', '1', 'artikel-2', 'article', '{"article":"2"}', 'gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo', 'Gesetz über die Einführung einer kommunalen Privatisierungsbremse im Freistaat Ostdeutschland', 'Gesetz über die Einführung einer kommunalen Privatisierungsbremse im Freistaat Ostdeutschland', '', 'Artikel 2', 'Inkrafttreten', 'Dieses Gesetz tritt am Tag nach der Verkündung in Kraft.');
