INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10815, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '0', 'paragraph-1', 'paragraph', '{"paragraph":"1","subsections":["1","2","3"]}', 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '§ 1', 'Gesetzliche Feiertage', 'Gesetzliche Feiertage sind:
Neujahr (1. Januar),
Weltfrauentag (8. März),
Tag der Märzrevolution und Demokratie (18. März)
Karfreitag,
Ostermontag,
Tag der Arbeit (1. Mai),
Tag der Befreiung vom Nationalsozialismus und der Beendigung des Zweiten Weltkriegs in Europa (8. Mai),
Tag des Arbeiteraufstands (17. Juni),
Tag der Deutschen Einheit (3. Oktober),
Tag der Friedlichen Revolution (9. November),
1. Weihnachtstag (25. Dezember),
2. Weihnachtstag (26. Dezember).

Die gesetzlichen Feiertage nach Absatz 1 sind Feiertage im Sinne bundes- und landesrechtlicher Vorschriften.

Fallen die in Absatz 1 datumsfest bestimmten gesetzlichen Feiertage auf einen Sonnabend oder Sonntag wird für jeden dieser Tage am nächstmöglichen Wochenarbeitstag in der jeweiligen Folgewoche ein arbeitsfreier Tag gewährt (Ersatzfeiertag). Für den jeweiligen Ersatzfeiertag gelten die Bestimmungen des § 4.');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10816, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '1', 'paragraph-1a', 'paragraph', '{"paragraph":"1a","subsections":["1","2","3","4","5","6"]}', 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '§ 1a', 'Persönliche Feiertage', 'Arbeitnehmer:innen mit gewöhnlichem Arbeitsort im Freistaat Ostdeutschland haben in jedem Kalenderjahr Anspruch auf drei persönliche Feiertage.

Der persönliche Feiertag ist ein vom Arbeitnehmer frei gewählter Kalendertag. Er ist dem Arbeitgeber spätestens 14 Kalendertage vor dem beabsichtigten Zeitpunkt in Textform anzuzeigen. Eine Begründung ist nicht erforderlich.

Der Arbeitnehmer hat das Recht, an persönlichen Feiertagen der Arbeit fernzubleiben, wenn keine zwingenden betrieblichen Erfordernisse entgegenstehen. Im Fall zwingender betrieblicher Erfordernisse hat der Arbeitgeber unverzüglich einen Ersatztermin zu ermöglichen; der Ersatztermin ist innerhalb von drei Monaten zu gewähren.

Persönliche Feiertage gelten ausschließlich im Verhältnis Arbeitgeber zu Arbeitnehmer:innen als gesetzliche Feiertage im Sinne von § 9 Arbeitszeitgesetz und § 2 Entgeltfortzahlungsgesetz.

Die §§ 4 bis 7 dieses Gesetzes finden auf persönliche Feiertage keine Anwendung.

Absätze 1 bis 5 gelten nicht für Schüler:innen sowie Auszubildende.');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10817, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '2', 'paragraph-2', 'paragraph', '{"paragraph":"2"}', 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '§ 2', 'Gedenk- und Trauertage', 'Gedenk- und Trauertage im Sinne dieses Gesetzes sind der Luxemburg-Liebknecht-Gedenktag (15. Januar) und der Volkstrauertag (vorletzter Sonntag vor dem 1. Advent).');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10818, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '3', 'paragraph-2a', 'paragraph', '{"paragraph":"2a"}', 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '§ 2a', 'Örtlicher Gedenktag an die friedliche Revolution 1989', 'Die Gemeinden können einen örtlichen Gedenktag zur Erinnerung an die friedliche Revolution des Jahres 1989 durch Satzung bestimmen.');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10819, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '4', 'paragraph-3', 'paragraph', '{"paragraph":"3","subsections":["1","2","3"]}', 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '§ 3', 'Religiöse Feiertage', 'Religiöse Feiertage im Sinne dieses Gesetzes sind:
Erscheinungsfest (6. Januar),
Frühjahrsbußtag (7. Mittwoch vor Ostern),
Gründonnerstag,
Tag des Fastenbrechens,
Christi Himmelfahrt,
Pfingstmontag,
Fronleichnam,
Jom Kippur, (Zweiter Tag)
Vesakhfest,
Johannestag (24. Juni),
Peter und Paul (29. Juni),
Mariä Himmelfahrt (15. August),
Tag des Guru Nanak,
Lakshmi Puja,
Reformationstag (31. Oktober),
Allerheiligen (1. November),
Mariä Empfängnis (8. Dezember).

Die Staatsregierung wird ermächtigt, durch Rechtsverordnung weitere religiöse Feiertage festzulegen, soweit hierfür aufgrund der Bedeutung einer Religionsgemeinschaft nach Tradition oder Mitgliederzahl ein Bedürfnis besteht.

An den in Absatz 1 genannten und den nach Absatz 2 festgelegten religiösen Feiertagen haben

Schüler und Auszubildende das Recht, dem Unterricht oder der Ausbildung fernzubleiben,

Personen, die in einem Beschäftigungsverhältnis stehen, das Recht, der Arbeit fernzubleiben, soweit und solange dies erforderlich ist, um am Hauptgottesdienst oder den Feierlichkeiten ihrer Religionsgemeinschaft teilzunehmen.');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10820, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '5', 'paragraph-4', 'paragraph', '{"paragraph":"4","subsections":["1","2","3","4"]}', 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '§ 4', 'Allgemeine Schutzvorschrift', 'Die Sonntage und die gesetzlichen Feiertage sind als Tage der Arbeitsruhe und seelischen Erhebung nach Maßgabe der gewerbe- und arbeitsrechtlichen Vorschriften sowie der Bestimmungen dieses Gesetzes geschützt.

An den Sonntagen und den gesetzlichen Feiertagen sind öffentlich bemerkbare Arbeiten und sonstige Handlungen, die geeignet sind, die Ruhe des Tages zu beeinträchtigen, verboten, soweit nicht durch Gesetz oder aufgrund eines Gesetzes etwas anderes bestimmt ist.

Absatz 2 gilt nicht für

den Betrieb der Post, der Eisenbahnen und sonstiger Unternehmen, die der Personenbeförderung dienen, sowie der Hilfseinrichtungen des Verkehrs mit der Maßgabe, daß Instandsetzungsarbeiten an Kraftfahrzeugen nur vorgenommen werden dürfen, soweit sie für die Weiterfahrt erforderlich sind;

unaufschiebbare Arbeiten, die erforderlich sind

zur Abwendung eines Schadens an Gesundheit oder Eigentum,

zur Befriedigung häuslicher Bedürfnisse,

in landwirtschaftlichen Betrieben, insbesondere zur Ernte,

zur Be- oder Verarbeitung leicht verderblicher Nahrungsmittel und zur Versorgung der Bevölkerung mit Milch;

leichte Arbeiten nicht gewerblicher Art in Gärten, die keine störenden Geräusche verursachen,

den Betrieb von Videotheken an den Sonntagen zwischen 12.00 und 20.00 Uhr.

den Betrieb von

vollautomatischen, gemeinsam mit Tankstellen betriebenen, Waschanlagen in geschlossener Bauform für Personenkraftwagen an den Sonntagen zwischen 8.00 und 20.00 Uhr,

gemeinsam mit Tankstellen betriebenen Selbstwaschanlagen für Personenkraftwagen an den Sonntagen zwischen 12.00 und 20.00 Uhr,

automatischen Waschanlagen und Selbstwaschanlagen für Personenkraftwagen in durch Bebauungsplan festgesetzten Gewerbe- und Industriegebieten an den Sonntagen zwischen 12.00 und 20.00 Uhr.

Satz 1 Nr. 4 und 5 gilt nicht für den Ostersonntag und Pfingstsonntag sowie für solche Sonntage, auf die ein gesetzlicher Feiertag nach § 1 Abs. 1 oder ein Gedenk- und Trauertag nach § 2 fällt.

Soweit Arbeiten an Sonntagen und gesetzlichen Feiertagen zulässig sind, ist auf das Wesen des Tages Rücksicht zu nehmen.');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10821, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '6', 'paragraph-5', 'paragraph', '{"paragraph":"5"}', 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '§ 5', 'Schutz religiöser Veranstaltungen', 'An den Sonntagen, religiösen und gesetzlichen Feiertagen, mit Ausnahme des 1. Mai und des 3. Oktober, sind in der Nähe von Kirchen und anderen Gebäuden, die religiösen Zwecken dienen, alle Handlungen zu unterlassen, die geeignet sind, religiöse Veranstaltungen zu stören. Dasselbe gilt am 24. Dezember für die Zeit ab 14.00 Uhr.');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10822, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '7', 'paragraph-6', 'paragraph', '{"paragraph":"6"}', 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '§ 6', 'Besondere Schutzvorschriften', '(weggefallen)');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10823, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '8', 'paragraph-7', 'paragraph', '{"paragraph":"7","subsections":["1","2"]}', 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '§ 7', 'Befreiungen', 'Die Kreispolizeibehörden können im Einzelfall aus wichtigem Grund von den Verbotsvorschriften der §§ 4 und 6 befreien.

Vor der Erteilung einer Befreiung sind die betroffenen Religionsgemeinschaften zu hören. Dies gilt nicht, soweit sich die Befreiung auf den 1. Mai oder den 3. Oktober bezieht.');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10824, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '9', 'paragraph-8', 'paragraph', '{"paragraph":"8","subsections":["1","2","3"]}', 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '§ 8', 'Ordnungswidrigkeiten', 'Ordnungswidrig handelt, wer vorsätzlich oder fahrlässig den Vorschriften über das Verbot

öffentlich bemerkbarer Arbeiten und sonstiger Handlungen (§ 4 Abs. 2),

von Handlungen, die geeignet sind, religiöse Veranstaltungen zu stören (§ 5),

bestimmter Veranstaltungen an besonders geschützten Tagen (§ 6)

Die Ordnungswidrigkeit kann mit einer Geldbuße bis zu 5 000 EUR geahndet werden.

Verwaltungsbehörden im Sinne des § 36 Abs. 1 Nr. 1 des Gesetzes über Ordnungswidrigkeiten sind die Ortspolizeibehörden.');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10825, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '10', 'paragraph-9', 'paragraph', '{"paragraph":"9"}', 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '§ 9', 'Grundrechtseinschränkung', 'Das Grundrecht der Versammlungsfreiheit (Artikel 8 Abs. 2 des Grundgesetzes und Artikel 23 Abs. 2 der Verfassung des Freistaates Ostdeutschland) wird nach Maßgabe der §§ 5 und 6 eingeschränkt.');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10826, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '11', 'paragraph-10', 'paragraph', '{"paragraph":"10"}', 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '§ 10', 'Außerkrafttreten von Rechtsvorschriften', 'Folgende Rechtsvorschriften treten außer Kraft:

§ 168 Abs. 2 des Arbeitsgesetzbuches der Deutschen Demokratischen Republik vom 16. Juni 1977 (GBl. I Nr. 18 S. 185), zuletzt geändert durch Gesetz vom 22. Juni 1990 (GBl. I Nr. 35 S. 371),

Verordnung über die Einführung gesetzlicher Feiertage vom 16. Mai 1990 (GBl. I Nr. 27 S. 248),

Erste Durchführungsbestimmung vom 7. Juni 1990 zur Verordnung über die Einführung gesetzlicher Feiertage (GBl. I Nr. 31 S.281).');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10827, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '12', 'paragraph-11', 'paragraph', '{"paragraph":"11"}', 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '§ 11', 'Inkrafttreten', 'Dieses Gesetz tritt am Tage nach seiner Verkündung in Kraft.');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10828, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '13', '', 'supplement', NULL, 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '', '', 'Der Ostdeutsche Landtag hat am 13. Oktober 1992 das folgende Gesetz beschlossen:');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (10829, 'ostdeutsches-feiertagsgesetz', '2026-03-23', '14', '', 'metadata', NULL, 'ostdeutsches-feiertagsgesetz', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland', 'Ostdeutsches Feiertagsgesetz', 'OstFSG', '', '', 'Das Gesetz regelt den in „Ostdeutsches Feiertagsgesetz“ bezeichneten Gegenstand und bestimmt die maßgeblichen Rechte, Pflichten und Verfahren.
