INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (22368, 'abschiebe-aussetzungsverordnung', '2024-03-01', '0', 'abschnitt-geltungsbereich', 'section', NULL, 'abschiebe-aussetzungsverordnung', 'Verordnung Aussetzung von Abschiebungen', 'Abschiebe-Aussetzungsverordnung', '', '', 'Geltungsbereich', 'Diese Verordnung gilt für alle Abschiebungen in die folgenden Länder:

Syrien

