INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (22369, 'abschiebe-aussetzungsverordnung', '2024-03-01', '1', 'abschnitt-anwendungsbereich', 'section', NULL, 'abschiebe-aussetzungsverordnung', 'Verordnung Aussetzung von Abschiebungen', 'Abschiebe-Aussetzungsverordnung', '', '', 'Anwendungsbereich', 'Diese Verordnung findet Anwendung auf alle ausreisepflichtigen Personen, die sich im Geltungsbereich des Freistaates befinden und deren Abschiebung in eines der oben genannten Länder bevorsteht.');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (22370, 'abschiebe-aussetzungsverordnung', '2024-03-01', '2', 'abschnitt-inhalt', 'section', NULL, 'abschiebe-aussetzungsverordnung', 'Verordnung Aussetzung von Abschiebungen', 'Abschiebe-Aussetzungsverordnung', '', '', 'Inhalt', 'Die Abschiebung von ausreisepflichtigen Personen in die oben genannten Länder wird für einen Zeitraum von drei Monaten ab dem 01.03.2024 ausgesetzt.');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (22371, 'abschiebe-aussetzungsverordnung', '2024-03-01', '3', 'abschnitt-begrundung', 'section', NULL, 'abschiebe-aussetzungsverordnung', 'Verordnung Aussetzung von Abschiebungen', 'Abschiebe-Aussetzungsverordnung', '', '', 'Begründung', 'Die aktuelle Lage in den oben genannten Ländern ist durch Krieg, Bürgerkriege, Terrorismus und humanitäre Notlagen gekennzeichnet. Eine Abschiebung in diese Länder würde daher eine unzumutbare Härte für die betroffenen Personen darstellen.');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (22372, 'abschiebe-aussetzungsverordnung', '2024-03-01', '4', 'abschnitt-inkrafttreten', 'section', NULL, 'abschiebe-aussetzungsverordnung', 'Verordnung Aussetzung von Abschiebungen', 'Abschiebe-Aussetzungsverordnung', '', '', 'Inkrafttreten', 'Diese Verordnung tritt mit ihrer Verkündung in Kraft.');
