INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (32046, 'oberstufenund-abiturprufungsverordnung', '2024-10-15', '0', 'paragraph-1-bis-8', 'paragraph', '{"paragraph":"1"}', 'oberstufenund-abiturprufungsverordnung', 'Verordnung des Sächsischen Staatsministeriums für Kultus über die gymnasiale Oberstufe und die Abiturprüfung an allgemeinbildenden Gymnasien im Freistaat Sachsen', 'Oberstufen- und Abiturprüfungsverordnung', 'OAVO', '§§ 1 bis 8', '§§ 1 bis 8', 'uverändert');
INSERT INTO law_search_units (id, norm_id, version_id, provision_path, anchor, block_type, references_json, slug, title, short_title, abbr, label, heading, body) VALUES (32047, 'oberstufenund-abiturprufungsverordnung', '2024-10-15', '1', 'paragraph-8', 'paragraph', '{"paragraph":"8"}', 'oberstufenund-abiturprufungsverordnung', 'Verordnung des Sächsischen Staatsministeriums für Kultus über die gymnasiale Oberstufe und die Abiturprüfung an allgemeinbildenden Gymnasien im Freistaat Sachsen', 'Oberstufen- und Abiturprüfungsverordnung', 'OAVO', '§ 8', 'Wahl der Leistungskurse', 'Jeder Schüler mit Ausnahme der in Absatz 3 genannten Schüler wählt aus dem Angebot seiner Schule Leistungskurse in zwei Fächern des Pflichtbereichs. Erstes Leistungskursfach ist Deutsch, Mathematik oder eine fortgeführte Fremdsprache. Folgende Leistungskurskombinationen sind zulässig.

Deutsch – Mathematik

Deutsch – fortgeführt Fremdsprache,

Deutsch – Biologie oder Chemie oder Physik,

Deutsch – Geschichte,

Deutsch – Gesellschaft, Rechtswissenschaften und Wirtschaft,

Mathematik – Gesellschaft, Rechtswissenschaften und Wirtschaft,

Mathematik – fortgeführte Fremdsprache,

Mathematik – Biologie oder Chemie oder Physik,

Mathematik – Geschichte,

fortgeführte Fremdsprache – Geschichte,

Gesellschaft, Rechtswissenschaften und Wirtschaft – Biologie oder Chemie – Physik,

Gesellschaft, Rechtswissenschaften und Wirtschaft – fortgeführte Fremdsprache,

Gesellschaft, Rechtswissenschaften und Wirtschaft – Geschichte.

Leistungskurse in Kunst und Musik sind nur an Schulen mit künstlerischem Profil oder vertiefter musischer Ausbildung gemäß § 4 Abs. 1 Buchst. a SOGY anzubieten. Sie können nur von Schülern, die dieses Profil in der Sekundarstufe I besucht haben, sowie von Schülern, die gleichwertige Leistungsnachweise erbringen, gewählt werden. Im Falle von Satz 1 ist an den Schulen mit künstlerischem Profil das erste Leistungskursfach Deutsch oder Mathematik.

Jeder Schüler in der vertieften Ausbildung gemäß § 4 SOGY wählt Leistungskurse in drei Fächern des Pflichtbereichs. Folgende Leistungskurskombinationen sind zulässig:

Bei vertiefter mathematisch-naturwissenschaftlicher Ausbildung.

Mathematik mit Biologie oder Chemie oder Physik und Deutsch oder fortgeführter Fremdsprache oder Geschichte,

Mathematik mit Deutsch und fortgeführter Fremdsprache oder Geschichte,

Mathematik mit fortgeführter Fremdsprache und Deutsch oder Geschichte,

Physik mit Biologie oder Chemie und Deutsch oder Geschichte,

Physik mit Deutsch und fortgeführter Fremdsprache oder Geschichte.

Bei vertiefter musischer Ausbildung:

Deutsch mit Musik und Mathematik oder Geschichte,

fortgeführte Fremdsprache mit Musik und Mathematik oder Geschichte,

Mathematik mit Musik und Deutsch oder fortgeführter Fremdsprache oder Geschichte,

Physik mit Musik und Deutsch oder Geschichte.

Bei vertiefter sportlicher Ausbildung:

Deutsch mit Sport und Mathematik oder Geschichte,

fortgeführte Fremdsprache mit Sport und Mathematik oder Geschichte,

Mathematik mit Sport und Deutsch oder fortgeführter Fremdsprache oder Geschichte,

Physik mit Sport und Deutsch oder Geschichte.

Bei vertiefter sprachlicher Ausbildung:

fortgeführte Fremdsprache mit Deutsch und Mathematik oder Physik oder Geschichte,

fortgeführte Fremdsprache mit weiterer fortgeführter Fremdsprache und Mathematik oder Geschichte,

fortgeführte Fremdsprache mit Physik und Deutsch oder Geschichte,

fortgeführte Fremdsprache mit Geschichte und Deutsch oder Mathematik oder weiterer fortgeführter Fremdsprache oder Biologie oder Chemie oder Physik,

fortgeführte Fremdsprache mit Mathematik und Biologie oder Chemie oder Physik.

Bei vertiefter Ausbildung im binationalen Bildungsgang:

Polnisch beziehungsweise Tschechisch mit Mathematik und Biologie oder Chemie oder Physik oder Geschichte,

Polnisch beziehungsweise Tschechisch mit Englisch und Mathematik oder Geschichte,

Polnisch beziehungsweise Tschechisch mit Physik und Deutsch oder Geschichte,

Polnisch beziehungsweise Tschechisch mit Deutsch und Mathematik oder Physik oder Geschichte,

Polnisch beziehungsweise Tschechisch mit Geschichte und Biologie oder Chemie.

Am sorbischen Gymnasium Bautzen sind neben den gemäß Absatz 1 zulässigen Leistungskurskombinationen folgende Leistungskurskombinationen zulässig:

Deutsch – Sorbisch,

Mathematik – Sorbisch,

fortgeführte Fremdsprache – Sorbisch,

Sorbisch – Geschichte,

Sorbisch – Biologie oder Chemie oder Physik. Im Abiturprüfungsbereich wird in den Fällen der Nummer 5 Buchst. a bis d ein Leistungskursfach, in den Fällen der Nummern 1 und 4 sowie Nummer 5 Buchst. e nach Wahl des Schülers das jeweils zweite oder dritte Leistungskursfach, in den Fällen der Nummern 2 und 3 das jeweils dritte Leistungskursfach als Grundkursfach gewertet und nach Wahl des Schülers schriftlich (P3 gemäß § 27 Abs. 2 Nr. 3) oder mündlich (P4 gemäß § 27 Abs. 2 Nr. 4) geprüft. Bei der Wahl des Faches Sorbisch gemäß Nummer 6 Buchst. b bis e als Leistungskursfach findet § 27 Abs. 5 Satz 1 hinsichtlich des Faches Deutsch keine Anwendung. Davon unberührt bleibt die Verpflichtung, die Leistungen aus vier Grundkursen im Fach Deutsch in die Gesamtqualifikation einzubringen.

Im Falle des Absatzes 3 Nr. 1 bis 5 ist auf dem Zeugnis der allgemeinen Hochschulreife unter dem Feld „Bemerkungen“ folgendes aufzunehmen: „Das Fach ... wurde auf Leistungskursniveau unterrichtet und im Abiturprüfungsbereich als Grundkursfach gewertet und geprüft.

Sollte eine Schule weniger als fünfzig Lehrer in Vollzeit angestellt haben, so finden die Buchstaben 4, 5, 10 und 14 des Absatzes 1 keine Anwendung.

Die Vorgaben aus Absatz 1 Buchstabe 5, 6, 11, 12 und 13 treten zum Eginn des Schuljahres 2025/2026 in Kraft.');
