INSERT INTO law_search_documents (norm_id, version_id, document_json, updated_at) VALUES ('gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo', '2026-03-23', '{"id":"gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo:2026-03-23","slug":"gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo","versionId":"2026-03-23","url":"/norm/gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo/","currentUrl":"/norm/gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo/","isCurrent":true,"versionKind":"current","isAmendment":true,"origin":"ostdeutsch-original","title":"Gesetz über die Einführung einer kommunalen Privatisierungsbremse im Freistaat Ostdeutschland","shortTitle":"Gesetz über die Einführung einer kommunalen Privatisierungsbremse im Freistaat Ostdeutschland","abbr":"","aliases":[],"type":"aenderungsvorschrift","typeLabel":"Änderungsvorschrift","ministry":"Staatsministerium des Innern, Bau und für kommunale Angelegenheiten","subjects":["Kommunalrecht"],"keywords":["Kommunen","Landkreise","Verwaltung","über"],"status":"in-force","statusLabel":"in Kraft","summary":"Ändert die Ostdeutsche Gemeindeordnung: Kommunal beherrschte Versorgungs-, Infrastruktur-, Wohnungs- und Krankenhausunternehmen dürfen nur durch Satzung mit Zweidrittelmehrheit oder nach Bürgerentscheid veräußert werden.","initialCitation":"Gesetz vom 23. März 2026 (OGVBl. 2026 Nr. 19)","citation":"Gesetz über die Einführung einer kommunalen Privatisierungsbremse im Freistaat Ostdeutschland vom 23. März 2026 (OGVBl. 2026 Nr. 19)","publication":"OGVBl. 2026 Nr. 19","publicationSlug":"ogvbl-2026-19","publicationUrl":"/verkuendungen/ogvbl-2026-19/","publicationTitle":"Ostdeutsches Gesetz- und Verordnungsblatt 2026 Nr. 19","publicationAliases":[],"publicationDate":"2026-03-24","publicationIssue":"19","publicationSource":"OGVBl.","publicationYear":"2026","publicationPage":"2-3","publicationEntryTitle":"Gesetz über die Einführung einer kommunalen Privatisierungsbremse im Freistaat Ostdeutschland","changeNote":"Stammfassung.","validFrom":"2026-03-25","validTo":null,"lastChangeDate":"2026-03-25"}', '2026-01-01T00:00:00.000Z');
