INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('abschiebe-aussetzungsverordnung', 0, '2024-03-01', 'initial', 'Amtlich verkündet und in Kraft getreten.', 'Verordnung vom 1. März 2024 (amtliche Einzelverkündung)', NULL, '2024-03-01', NULL);
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('abschiebe-aussetzungsverordnung', 1, '2025-09-16', 'repeal', 'Ausdrücklich aufgehoben.', 'Artikel 1 der Verordnung vom 16. September 2025 (OGVBl. 2025 Nr. 9)', NULL, NULL, 'verordnung-zur-aufhebung-verfassungswidrig-erlassener-verordnungen');
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('aend-ostgemo-4399', 0, '2023-11-01', 'initial', 'Vollständige Ausgangsfassung zum Rechtsüberleitungsstichtag (Teil 10 § 73 Absatz 1 der Mantelvorschrift).', 'Änderung der Ostdeutschen Gemeindeordnung vom 24. November 2000 (SächsGVBl. S. 482, 492), das durch das Gesetz vom 24. November 2000 (SächsGVBl. S. 482; 2001 S. 704) geändert worden ist', NULL, '2023-11-01', NULL);
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('dienstanordnung-momentane-terrorgefahr-2024', 0, '2024-10-02', 'initial', 'Stammfassung verkündet.', 'Dienstanordnung vom 2. Oktober 2024 (OGVBl. 2024 Nr. II S. 4)', NULL, '2024-10-02', NULL);
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('dienstanordnung-momentane-terrorgefahr-2024', 1, '2026-08-27', 'notice', 'Datum und ausgelassenes Außerkrafttreten der nachgedruckten Dienstanordnung wurden amtlich berichtigt.', 'Berichtigung vom 14. August 2026 (OGVBl. 2026 Nr. 68 S. 2)', 'Deklaratorische Berichtigung der Verkündungsfassung; kein materieller Fassungswechsel.', '2024-10-02', 'berichtigung-verschiedener-verkuendungen-2026');
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('gesetz-uber-die-einfuhrung-einer-kommunalen-privatisierungsb-zue3jo', 0, '2026-03-23', 'initial', 'Stammfassung.', 'Gesetz vom 23. März 2026 (OGVBl. 2026 Nr. 19)', NULL, '2026-03-23', NULL);
