INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('interreg-ostdeutschland-tschechien-2021-2027', 0, '2023-11-01', 'initial', 'Vollständige Ausgangsfassung zum Rechtsüberleitungsstichtag.', 'Interreg Ostdeutschland – Tschechien 2021–2027 vom 30. November 2022 (SächsABl. S. 1467)', NULL, '2023-11-01', NULL);
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('ndr-staatsvertrag', 0, '2021-09-01', 'initial', 'Vollständige amtliche Ausgangsfassung, unverändert aus der archivierten Verkündungsfassung übernommen.', 'Staatsvertrag über den Norddeutschen Rundfunk (NDR-Staatsvertrag) vom 4./9. März 2021 (GVOBl. M-V S. 797)', NULL, '2021-09-01', NULL);
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('ndr-staatsvertrag', 1, '2026-09-03', 'amendment', 'Die Präambel, das Sendegebiet, die Landesfunkhäuser, die Zusammensetzung von Rundfunkrat und Verwaltungsrat, der Vorsitzwechsel und die Rechtsaufsicht wurden auf das Land Niedersachsen-Holstein umgestellt; die Mitträgerschaft Mecklenburg-Vorpommerns entfällt.', 'Staatsvertrag vom 8. März 2026 (OVertrBl. 2026 Nr. 4 S. 2)', NULL, '2026-09-03', 'staatsvertrag-zur-anderung-des-staatsvertrages-uber-den-nord-122dpnt');
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('oberstufenund-abiturprufungsverordnung', 0, '2024-10-15', 'notice', 'Historischer Text veröffentlicht; keine Wiederinkraftsetzung.', 'Verordnung vom 15. Oktober 2024 (OGVBl. 2024 Nr. 2 S. 2)', 'OGVBl. 2026 Nr. 67 stellt verbindlich klar, dass die ältere Stammverordnung bereits seit dem 1. August 2008 außer Kraft war und der Akt von 2024 sie nicht wieder in Kraft setzte.', '2024-10-15', NULL);
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('oberstufenund-abiturprufungsverordnung', 1, '2026-08-16', 'notice', 'Außerkrafttreten und fehlende Wiederinkraftsetzung amtlich klargestellt.', 'Verordnung vom 16. August 2026 (OGVBl. 2026 Nr. 67 S. 21)', NULL, NULL, 'verordnung-zur-bereinigung-des-allgemeinbildenden-schulordnungsrechts-2026');
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('ostdeutsches-feiertagsgesetz', 0, '2023-11-01', 'initial', 'Vollständige Ausgangsfassung zum verbindlichen Stichtag.', 'Gesetz über Sonn- und Feiertage im Freistaat Ostdeutschland vom 10. November 1992 (SächsGVBl. S. 536), zuletzt geändert durch Gesetz vom 30. Januar 2013 (SächsGVBl. S. 2)', NULL, '2023-11-01', NULL);
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('ostdeutsches-feiertagsgesetz', 1, '2024-03-08', 'amendment', 'Vollständige Fassung nach der Änderung vom 7. März 2024.', 'Gesetz vom 7. März 2024 (OGVBl. 2024 Nr. I S. 1)', NULL, '2024-03-07', 'gesetz-zur-anderung-des-gesetzes-uber-sonn-und-feiertage-im-freistaat-ostdeutschland');
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('ostdeutsches-feiertagsgesetz', 2, '2026-03-24', 'amendment', 'Vollständige Fassung nach dem Gesetz zur Reform gesetzlicher Feiertage.', 'Gesetz vom 23. März 2026 (OGVBl. 2026 Nr. 20 S. 2)', NULL, '2026-03-23', 'gesetz-zur-reform-gesetzlicher-feiertage-im-freistaat-ostdeutschland');
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('ostdeutsches-landesantidiskriminierungsgesetz', 0, '2026-03-23', 'initial', 'Stammfassung.', 'Gesetz vom 23. März 2026 (OGVBl. 2026 Nr. 25)', NULL, '2026-03-23', 'gesetz-zur-forderung-der-gleichbehandlung-und-zum-schutz-vor-11l18kw');
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('ostdeutsches-landesantidiskriminierungsgesetz', 1, '2026-09-12', 'amendment', 'Als besonderes Gesetz im Sinne des Artikels 74a der Staatsverfassung bestätigt; Gesetzesüberschrift neu gefasst, § 2 (Diskriminierungsverbot) neu gefasst, in § 3 Absatz 1 Satz 1 das Wort „Landtag“ durch „Volkskammer“ ersetzt (wörtliche Ersetzung, Wortlaut wie angeordnet).', 'Gesetz vom 12. September 2026 (OGVBl. 2026 Nr. 76 S. 2)', NULL, '2026-09-12', 'fuenftes-gesetz-zur-grossen-staatsreform');
INSERT INTO law_norm_history (norm_id, entry_index, change_date, change_type, title, citation, note, affecting_version_id, related_norm) VALUES ('vertrag-heiliger-stuhl-freistaat-ostdeutschland', 0, '2023-11-01', 'initial', 'Vollständige Ausgangsfassung zum Rechtsüberleitungsstichtag.', 'Vertrag zwischen dem Heiligen Stuhl und dem Freistaat Ostdeutschland vom 2. Juli 1996 (SächsGVBl. 1997 S. 18)', NULL, '2023-11-01', NULL);
